Future<void> openPdf(String filePath) async {
  final result = await OpenFilex.open(filePath);
  print(result); // Optional: لمراجعة حالة الفتح
}

// ============================================================================
// Branding
// ============================================================================

Color appTeal(BuildContext context) {
  try {
    return UniSpaceApp.of(context).tealColor;
  } catch (_) {
    return kDefaultTeal;
  }
}

Color appTealLight(BuildContext context) {
  return Color.lerp(appTeal(context), Colors.white, 0.55)!;
}

Color appTealDark(BuildContext context) {
  return Color.lerp(appTeal(context), Colors.black, 0.35)!;
}

// ============================================================================
// Bootstrap
// ============================================================================
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
    await initPushNotifications();
  } catch (error, stackTrace) {
    debugPrint('Firebase initialization failed: $error');
    debugPrintStack(stackTrace: stackTrace);
  }
  await Hive.initFlutter();
  tz.initializeTimeZones();
  tz.setLocalLocation(tz.getLocation('Africa/Algiers'));

  Hive.registerAdapter(ModuleModelAdapter());
  await AppSettings.instance.load();
  await UserProfileService.instance.initialize();

  final p = await SharedPreferences.getInstance();
  final themeIdx = p.getInt('pref_themeMode');
  final lang = p.getString('pref_locale');

  final themeMode = (themeIdx != null &&
      themeIdx >= 0 &&
      themeIdx < ThemeMode.values.length)
      ? ThemeMode.values[themeIdx]
      : ThemeMode.system;

  final locale = (lang != null && lang.isNotEmpty)
      ? Locale(lang)
      : const Locale('en');

  runApp(UniSpaceApp(
    initialThemeMode: themeMode,
    initialLocale: locale,
  ));
}

