class _CommunityHeader extends StatelessWidget {
  const _CommunityHeader();

  @override
  Widget build(BuildContext context) {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return const SizedBox.shrink();

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('notifications')
          .orderBy('createdAt', descending: true)
          .limit(30)
          .snapshots(),
      builder: (context, snap) {
        if (snap.hasError) {
          debugPrint('notif stream error: ${snap.error}');
          return const SizedBox.shrink();
        }
        return FutureBuilder<Set<String>>(
          future: loadBlockedUserIds(),
          builder: (context, blockedSnap) {
            final blocked = blockedSnap.data ?? {};
            final items = (snap.data?.docs ?? [])
                .map(_notificationFromDoc)
                .where((n) => n.actorId == null || !blocked.contains(n.actorId))
                .toList();
            return NotificationsShowcase(
              notifications: items,
              onDismiss: (id) => _dismissNotification(uid, id),
              onDismissAll: () =>
                  _dismissAllNotifications(uid, items.map((e) => e.id)),
            );
          },
        );
      },
    );
  }
}



class NotificationItem {
  const NotificationItem({
    required this.id,
    required this.sender,
    required this.message,
    this.time,
    this.type = 'comment',
    this.actorId,
    this.actorPhotoUrl,
    this.postId,
    this.commentId,
    this.read = false,
  });

  final String id;
  final String sender;
  final String message;
  final String? time;
  final String type; // follow | comment | reply
  final String? actorId;
  final String? actorPhotoUrl;
  final String? postId;
  final String? commentId;
  final bool read;
}

String _notifTimeAgo(DateTime? dt) {
  if (dt == null) return 'الآن';
  final d = DateTime.now().difference(dt);
  if (d.inSeconds < 60) return 'الآن';
  if (d.inMinutes < 60) return '${d.inMinutes}د';
  if (d.inHours < 24) return '${d.inHours}س';
  if (d.inDays < 7) return '${d.inDays}ي';
  return '${dt.day}/${dt.month}';
}

NotificationItem _notificationFromDoc(
    QueryDocumentSnapshot<Map<String, dynamic>> doc,
    ) {
  final d = doc.data();
  final created = d['createdAt'];
  DateTime? at;
  if (created is Timestamp) at = created.toDate();
  return NotificationItem(
    id: doc.id,
    sender: (d['actorName'] ?? 'طالب').toString(),
    message: (d['message'] ?? '').toString(),
    time: _notifTimeAgo(at),
    type: (d['type'] ?? 'comment').toString(),
    actorId: d['actorId']?.toString(),
    actorPhotoUrl: d['actorPhotoUrl']?.toString(),
    postId: d['postId']?.toString(),
    commentId: d['commentId']?.toString(),
    read: d['read'] == true,
  );
}

Future<void> pushNotification({
  required String toUid,
  required String type,
  required String actorName,
  String? actorPhotoUrl,
  required String message,
  String? postId,
  String? commentId,
  String? docId,
}) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || toUid.isEmpty || toUid == me) return;

  try {
    if (await isAccountBlocked(toUid)) return;
    if (await isBlockedByAccount(toUid)) return;
  } catch (_) {}

  final id = docId ?? (type == 'follow' ? 'follow_$me' : null);
  final col = FirebaseFirestore.instance
      .collection('users')
      .doc(toUid)
      .collection('notifications');
  final ref = id == null ? col.doc() : col.doc(id);

  try {
    await ref.set({
      'type': type,
      'actorId': me,
      'actorName': actorName,
      'actorPhotoUrl': actorPhotoUrl,
      'message': message,
      if (postId != null) 'postId': postId,
      if (commentId != null) 'commentId': commentId,
      'read': false,
      'createdAt': FieldValue.serverTimestamp(),
    });
    debugPrint('notif OK → $toUid type=$type id=${ref.id}');
  } catch (e) {
    debugPrint('notif FAIL → $toUid type=$type $e');
  }
}

Future<void> pushNotificationFromMe({
  required String toUid,
  required String type,
  required String message,
  String? postId,
  String? commentId,
  String? docId,
}) async {
  final me = FirebaseAuth.instance.currentUser;
  if (me == null) return;
  var name = (me.displayName ?? '').trim();
  String? photo = me.photoURL;
  try {
    final d = await FirebaseFirestore.instance.collection('users').doc(me.uid).get();
    final fn = (d.data()?['firstName'] ?? '').toString().trim();
    final ln = (d.data()?['lastName'] ?? '').toString().trim();
    final fromNames = [fn, ln].where((e) => e.isNotEmpty).join(' ');
    if (fromNames.isNotEmpty) name = fromNames;
    final p = d.data()?['profileImageUrl']?.toString();
    if (p != null && p.isNotEmpty) photo = p;
  } catch (_) {}

  await pushNotification(
    toUid: toUid,
    type: type,
    actorName: name.isEmpty ? 'طالب UniSpace' : name,
    actorPhotoUrl: photo,
    message: message,
    postId: postId,
    commentId: commentId,
    docId: docId,
  );
}
Future<void> notifyFollowersOfNewPost({
  required String postId,
  required String title,
}) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return;

  final snap = await FirebaseFirestore.instance
      .collection('users')
      .doc(me)
      .collection('followers')
      .limit(40)
      .get();

  final t = title.trim();
  final msg = t.isEmpty ? 'نشر منشوراً جديداً' : 'نشر: $t';
  final short = msg.length > 70 ? '${msg.substring(0, 70)}…' : msg;

  for (final d in snap.docs) {
    final toUid = (d.data()['uid'] ?? d.id).toString();
    unawaited(pushNotificationFromMe(
      toUid: toUid,
      type: 'new_post',
      message: short,
      postId: postId,
      docId: 'post_$postId',
    ));
  }
}

Future<void> _markNotificationRead(String uid, String id) async {
  try {
    await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('notifications')
        .doc(id)
        .update({'read': true});
  } catch (e) {
    debugPrint('mark notif read failed: $e');
  }
}

Future<void> _dismissNotification(String uid, String id) async {
  await FirebaseFirestore.instance
      .collection('users')
      .doc(uid)
      .collection('notifications')
      .doc(id)
      .delete();
}

Future<void> _dismissAllNotifications(String uid, Iterable<String> ids) async {
  final batch = FirebaseFirestore.instance.batch();
  final col = FirebaseFirestore.instance
      .collection('users')
      .doc(uid)
      .collection('notifications');
  for (final id in ids) {
    batch.delete(col.doc(id));
  }
  await batch.commit();
}

Future<void> _markAllNotificationsRead(String uid) async {
  try {
    final snap = await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('notifications')
        .orderBy('createdAt', descending: true)
        .limit(80)
        .get();
    final unread = snap.docs.where((d) => d.data()['read'] != true);
    if (unread.isEmpty) return;
    final batch = FirebaseFirestore.instance.batch();
    for (final d in unread) {
      batch.update(d.reference, {'read': true});
    }
    await batch.commit();
  } catch (e) {
    debugPrint('mark all read failed: $e');
  }
}

IconData _notificationIcon(String type) {
  switch (type) {
    case 'follow':
    case 'follow_accepted':
      return Icons.person_add_alt_1_rounded;
    case 'follow_request':
      return Icons.person_add_rounded;
    case 'like':
    case 'like_comment':
      return Icons.favorite_rounded;
    case 'reply':
      return Icons.reply_rounded;
    case 'new_post':
      return Icons.article_outlined;
    default:
      return Icons.chat_bubble_outline_rounded;
  }
}

