Future<void> _openNotification(
    BuildContext context,
    NotificationItem n,
    ) async {
  final uid = FirebaseAuth.instance.currentUser?.uid;
  if (uid != null) unawaited(_markNotificationRead(uid, n.id));
  final actorId = (n.actorId ?? '').trim();
  final type = n.type;

  if (type == 'follow_request') {
    Navigator.of(context).push(
      MaterialPageRoute(builder: (_) => const FollowRequestsScreen()),
    );
    return;
  }

  if ((type == 'follow' || type == 'follow_accepted') && actorId.isNotEmpty) {
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => UserProfileScreen(
          userId: actorId,
          initialName: n.sender,
          initialPhotoUrl: n.actorPhotoUrl,
        ),
      ),
    );
    return;
  }

  final postId = n.postId?.trim() ?? '';
  if (postId.isNotEmpty) {
    final doc = await FirebaseFirestore.instance
        .collection('community_posts')
        .doc(postId)
        .get();
    if (!doc.exists || !context.mounted) return;
    final post = _Post.fromFirestore(doc);
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => CommentsScreen(
          post: post,
          initialCommentId: n.commentId,
        ),
      ),
    );
    return;
  }

  if (actorId.isNotEmpty) {
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => UserProfileScreen(
          userId: actorId,
          initialName: n.sender,
          initialPhotoUrl: n.actorPhotoUrl,
        ),
      ),
    );
  }
}

