class _NotificationsOverlayState extends State<_NotificationsOverlay> {
  late List<NotificationItem> _items = List.of(widget.initial);
  final _panelKey = GlobalKey();

  void _expandToScreen() {
    final box = _panelKey.currentContext?.findRenderObject() as RenderBox?;
    final origin = box == null
        ? null
        : (box.localToGlobal(Offset.zero) & box.size);
    final nav = Navigator.of(context, rootNavigator: true);
    nav.pop();
    nav.push(
      _ExpandPanelRoute(
        originRect: origin,
        child: const NotificationsScreen(),
      ),
    );
  }
  void _dismiss(String id) {
    widget.onDismiss(id);
    setState(() => _items.removeWhere((n) => n.id == id));
    if (_items.isEmpty) Navigator.of(context).pop();
  }

  void _dismissAll() {
    widget.onDismissAll();
    Navigator.of(context).pop();
  }

  Future<void> _openItem(NotificationItem n) async {
    Navigator.of(context).pop();
    await _openNotification(context, n);
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;

    return Center(
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 370, maxHeight: 480),
        child: ClipRRect(
          key: _panelKey,
          borderRadius: BorderRadius.circular(20),
          child: BackdropFilter(
            filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
            child: Material(
              color: scheme.surface.withValues(alpha: 0.92),
              elevation: 0,
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        Text(
                          'الإشعارات',
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w800,
                            color: scheme.onSurface,
                          ),
                        ),
                        const SizedBox(width: 6),
                        Text(
                          '${_items.length}',
                          style: TextStyle(
                            fontSize: 12,
                            color: scheme.onSurfaceVariant,
                          ),
                        ),
                        const Spacer(),
                        if (_items.isNotEmpty)
                          TextButton(
                            onPressed: _dismissAll,
