class CommunityScreen extends StatefulWidget {
  const CommunityScreen({super.key, required this.onOpenDrawer});

  final VoidCallback onOpenDrawer;

  @override
  State<CommunityScreen> createState() => _CommunityScreenState();
}

class _CommunityScreenState extends State<CommunityScreen> {
  bool _publishing = false;

  final _scrollController = ScrollController();
  final List<_Post> _posts = [];
  DocumentSnapshot<Map<String, dynamic>>? _lastDoc;
  bool _loadingMore = false;
  bool _hasMore = true;
  bool _initialLoading = true;
  String? _error;
  static const int _pageSize = 25;
  Set<String> _blockedIds = {};

  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _newPostsSub;
  final GlobalKey _searchButtonKey = GlobalKey();
  CollectionReference<Map<String, dynamic>> get _postsRef =>
      FirebaseFirestore.instance.collection('community_posts');


  Future<String> _uploadImage(Uint8List bytes, String postId, int index) async {
    try {
      final storage = FirebaseStorage.instance;
      final ref = storage
          .ref()
          .child('community_posts')
          .child(postId)
          .child('images')
          .child('image_$index.jpg');

      final uploadTask = ref.putData(
        bytes,
        SettableMetadata(contentType: 'image/jpeg'),
      );

      final snapshot = await uploadTask;
      return await snapshot.ref.getDownloadURL();
    } on FirebaseException catch (e, stack) {
      rethrow;
    } catch (e, stack) {
      rethrow;
    }
  }
  @override
  void initState() {
    super.initState();
    _loadInitial();
    _scrollController.addListener(_onScroll);

    blockedListRevision.addListener(_onBlockedListChanged);
    authorProfileRevision.addListener(_onAuthorProfileChanged);
  }
  void _onAuthorProfileChanged() {
    if (mounted) _loadInitial();
  }
// في CommunityScreen
  void _onBlockedListChanged() {
    if (mounted) _loadInitial();
  }
  @override
  void dispose() {
    authorProfileRevision.removeListener(_onAuthorProfileChanged);
    blockedListRevision.removeListener(_onBlockedListChanged);
    _scrollController.removeListener(_onScroll);
    _scrollController.dispose();
    _newPostsSub?.cancel();
    super.dispose();
  }

  Query<Map<String, dynamic>> get _baseQuery => _postsRef
      .orderBy('createdAt', descending: true);

  Future<void> _loadInitial({bool showFullLoader = true}) async {
    setState(() {
      if (showFullLoader || _posts.isEmpty) _initialLoading = true;
      _error = null;
    });

    try {
      final snap = await _baseQuery.limit(_pageSize).get();
      final hidden = await loadHiddenPostIds();
      final blocked = await loadBlockedUserIds();
      final followingIds = await loadFollowingIds();
      final me = FirebaseAuth.instance.currentUser?.uid;
      _blockedIds = blocked;

      final list = _docsToPosts(snap.docs).where((p) {

        final id = p.id?.trim();
        if (id == null || id.isEmpty) return false;
        if (hidden.contains(id)) return false;
        if (isBlockedPost(p, blocked)) return false;
        if (p.authorPrivate) {
          final a = (p.authorId ?? '').trim();
          if (a.isNotEmpty && a != me && !followingIds.contains(a)) {
            return false;
          }
        }
        return true;
      }).toList();

      setState(() {
        _posts
          ..clear()
          ..addAll(list);
        _lastDoc = snap.docs.isEmpty ? null : snap.docs.last;
        _hasMore = snap.docs.length >= _pageSize;
        _initialLoading = false;
      });
      _newPostsSub?.cancel();
      _listenForNewPosts();
      _precacheImages(list);
      _prefetchFirstVideos(list);
    } catch (e) {
      setState(() {
        _error = e.toString();
        _initialLoading = false;
      });

    }
  }

  Future<List<_Post>> loadMoreForPager() async {
    await _loadMore();
    return List<_Post>.from(_posts);
  }
  Future<void> _loadMore() async {
    if (_loadingMore || !_hasMore || _lastDoc == null) return;

    setState(() => _loadingMore = true);

    try {
      final followingIds = await loadFollowingIds();
      final me = FirebaseAuth.instance.currentUser?.uid;
      final snap = await _baseQuery
          .startAfterDocument(_lastDoc!)
          .limit(_pageSize)
          .get();

      final hidden = await loadHiddenPostIds();
      final list = _docsToPosts(snap.docs).where((p) {
        final id = p.id?.trim();
        if (id == null || id.isEmpty) return false;
        if (hidden.contains(id)) return false;
        if (isBlockedPost(p, _blockedIds)) return false;
        if (p.authorPrivate) {
          final a = (p.authorId ?? '').trim();
          if (a.isNotEmpty && a != me && !followingIds.contains(a)) {
            return false;
          }
        }
        return true;
      }).toList();

      setState(() {
        _posts.addAll(list);
        _lastDoc = snap.docs.isEmpty ? null : snap.docs.last;
        _hasMore = snap.docs.length >= _pageSize;
        _loadingMore = false;
      });

      _precacheImages(list);
      _prefetchFirstVideos(list);
    } catch (e) {
      setState(() => _loadingMore = false);
      debugPrint('loadMore failed: $e');
    }
  }
  void _prefetchFirstVideos(List<_Post> posts) {
    // لا await في الحلقة حتى لا تُحظر الواجهة
    for (final post in posts) {
      final urls = [
        ...post.videoPaths,
        ...post.pollSlides
            .where((s) => s['type']?.toString() == 'video')
            .map((s) => (s['url'] ?? s['mediaPath'] ?? '').toString()),
      ];
      final first = urls.map((e) => e.trim()).firstWhere(
            (u) => u.startsWith('http'),
        orElse: () => '',
      );
      if (first.isEmpty) continue;

      // في الخلفية — DefaultCacheManager يتجاهل إن وُجد في الكاش
      DefaultCacheManager().getSingleFile(first).then((_) {}, onError: (_) {});
    }
  }
  void _onScroll() {
    if (!_scrollController.hasClients) return;
    final pos = _scrollController.position;
    // قبل النهاية بـ ~1000px → حمّل الصفحة التالية
    if (pos.pixels >= pos.maxScrollExtent - 1000) {
      _loadMore();
    }
  }

  List<_Post> _docsToPosts(
      List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
      ) {
    final out = <_Post>[];
    for (final doc in docs) {
      final data = doc.data();
      final status = data['status']?.toString().trim().toLowerCase();
      if (status == 'uploading') continue;
      try {
        out.add(_Post.fromFirestore(doc));
      } catch (e, st) {
        debugPrintStack(stackTrace: st);
      }
    }
    return out;
  }

  void _precacheImages(List<_Post> posts) {
    for (final post in posts) {
      for (final url in post.imagePaths) {
        final u = url.trim();
        if (u.startsWith('http')) {
          precacheImage(CachedNetworkImageProvider(u), context);
        }
      }

      for (final s in post.pollSlides) {
        if (s['type']?.toString() != 'image') continue;
        final u = (s['url'] ?? s['mediaPath'] ?? '').toString().trim();
        if (u.startsWith('http')) {
          precacheImage(CachedNetworkImageProvider(u), context);
        }
      }
    }
  }



  /// منشورات جديدة تُضاف في الأعلى بدون إعادة تحميل الكل
  void _listenForNewPosts() {
    _newPostsSub = _baseQuery.limit(5).snapshots().listen((snap) {
      if (!mounted || snap.docs.isEmpty) return;
      final newest = _docsToPosts(snap.docs)
          .where((p) => !isBlockedPost(p, _blockedIds))
          .toList();
      if (newest.isEmpty) return;

      final toAdd = <_Post>[];
      for (final p in newest.reversed) {
        if (!_posts.any((e) => e.id == p.id)) {
          toAdd.add(p);
        }
      }
      if (toAdd.isEmpty) return;

      setState(() {
        for (final p in toAdd) {
          _posts.insert(0, p);
        }
      });
      _precacheImages(toAdd);
    });
  }



  Future<String> _uploadVideo(String localPath, String postId, int index) async {
    final file = File(localPath);
    if (!await file.exists()) {
      throw Exception('Video file not found: $localPath');
    }

    final extension = localPath.split('.').last.toLowerCase();
    final contentType = extension == 'mov' ? 'video/quicktime' : 'video/mp4';

    final ref = FirebaseStorage.instance
        .ref()
        .child('community_posts/$postId/videos/video_$index.$extension');

    await ref.putFile(file, SettableMetadata(contentType: contentType));
    return await ref.getDownloadURL();
  }

  Future<void> _newPost() async {
    if (_publishing) return;

    final result = await Navigator.of(context).push<List<PostItem>>(
      MaterialPageRoute(builder: (_) => const CreatePostScreen()),
    );

    if (!mounted || result == null || result.isEmpty) return;

    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

// NEW: نجيبو رابط صورة الحساب من وثيقة المستخدم (نفس اللي كتحفظ
// فيها _uploadProfileAsset فصفحة البروفايل)
    String? authorPhotoUrl;
    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final saved = userDoc.data()?['profileImageUrl']?.toString().trim();
      if (saved != null && saved.isNotEmpty) {
        authorPhotoUrl = saved;
      }
    } catch (e) {
      debugPrint('Fetch author photo failed: $e');
    }

// إن لم توجد صورة مرفوعة → صورة حساب Google / المزود
    authorPhotoUrl ??= user.photoURL?.trim();
    if (authorPhotoUrl != null && authorPhotoUrl.isEmpty) {
      authorPhotoUrl = null;
    }

    String title = '';
    String body = '';
    final outsideImages = <Uint8List>[];
    final outsideVideos = <String>[]; // مسارات محلية
    List<PollData> pollDataList = [];
    List<Map<String, dynamic>> pollSlides = [];
    List<String> postTags = [];

    for (final item in result) {
      switch (item.type) {
        case PostItemType.text:
          final text = item.title.trim();
          if (text.isEmpty) break;
          if (title.isEmpty) {
            title = text;
          } else {
            body = body.isEmpty ? text : '$body\n$text';
          }
          break;

        case PostItemType.image:
          if (item.imageBytes != null) outsideImages.add(item.imageBytes!);
          break;

        case PostItemType.video:
          if (item.mediaPath != null && item.mediaPath!.isNotEmpty) {
            outsideVideos.add(item.mediaPath!);
          }
          break;

        case PostItemType.poll:
          pollDataList = item.pollDataList ?? [];
          pollSlides = List<Map<String, dynamic>>.from(item.pollSlides ?? []);
          break;

        case PostItemType.tags:
          postTags = item.tags ?? [];
          break;
      }
    }

    final hasContent = title.isNotEmpty ||
        body.isNotEmpty ||
        outsideImages.isNotEmpty ||
        outsideVideos.isNotEmpty ||
        pollDataList.isNotEmpty ||
        pollSlides.isNotEmpty;

    if (!hasContent) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('المنشور فارغ')),
      );
      return;
    }
    var authorPrivate = false;
    var authorAppearInSearch = true;
    var authorHideLikeCounts = false;
    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final priv = userDoc.data()?['privacy'];
      if (priv is Map) {
        authorPrivate = priv['privateAccount'] == true;
        authorAppearInSearch = priv['appearInSearch'] != false;
        authorHideLikeCounts = priv['hideLikeCounts'] == true;
      }
    } catch (_) {}

    setState(() => _publishing = true);
    DocumentReference<Map<String, dynamic>>? postRef;

    try {
      postRef = _postsRef.doc();

      await postRef.set({
        'authorId': user.uid,
        'authorName': (user.displayName ?? '').trim().isNotEmpty
            ? user.displayName!.trim()
            : 'طالب UniSpace',
        'title': title,
        'authorPhotoUrl': authorPhotoUrl,

        'body': body,
        'status': 'uploading',
        'createdAt': FieldValue.serverTimestamp(),
        'imageUrls': <String>[],
        'videoUrls': <String>[],
        'pollSlides': <Map<String, dynamic>>[],
        'polls': pollDataList.map(_pollToMap).toList(),
        'tags': postTags,
        'votes': 0,
        'upvotedBy': <String>[],
        'downvotedBy': <String>[],
        'commentsCount': 0,
        'version': 1,
        'authorPrivate': authorPrivate,
        'authorAppearInSearch': authorAppearInSearch,
        'authorHideLikeCounts': authorHideLikeCounts,
        'searchKeywords': buildSearchKeywords(
          title: title,
          body: body,
          tags: postTags,
          author: user.displayName,
        ),
      });

      // ===== 1) رفع وسائط خارج البول =====
      final imageUrls = <String>[];
      for (int i = 0; i < outsideImages.length; i++) {
        final url = await _uploadImage(outsideImages[i], postRef.id, i);
        imageUrls.add(url);
      }

      final videoUrls = <String>[];
      for (int i = 0; i < outsideVideos.length; i++) {
        final url = await _uploadVideo(outsideVideos[i], postRef.id, i);
        videoUrls.add(url);
      }

      // ===== 2) رفع شرائح البول بالترتيب =====
      final resolvedSlides = <Map<String, dynamic>>[];
      int pollImg = 0;
      int pollVid = 0;

      for (final s in pollSlides) {
        final type = s['type']?.toString();

        if (type == 'text') {
          final t = s['text']?.toString() ?? '';
          if (t.isNotEmpty) {
            resolvedSlides.add({'type': 'text', 'text': t});
          }
        } else if (type == 'poll') {
          resolvedSlides.add({
            'type': 'poll',
            'pollIndex': s['pollIndex'],
          });
        } else if (type == 'image') {
          final path = s['mediaPath']?.toString() ?? s['path']?.toString();
          if (path != null && path.isNotEmpty) {
            final file = File(path);
            if (await file.exists()) {
              final bytes = await file.readAsBytes();
              final url = await _uploadImage(bytes, postRef.id, 1000 + pollImg);
              pollImg++;
              resolvedSlides.add({'type': 'image', 'url': url});
            }
          } else if (s['imageBytes'] is Uint8List) {
            final url = await _uploadImage(
              s['imageBytes'] as Uint8List,
              postRef.id,
              1000 + pollImg,
            );
            pollImg++;
            resolvedSlides.add({'type': 'image', 'url': url});
          }
        } else if (type == 'video') {
          final path = s['mediaPath']?.toString() ?? s['path']?.toString();
          if (path != null && path.isNotEmpty) {
            final url = await _uploadVideo(path, postRef.id, 1000 + pollVid);
            pollVid++;
            resolvedSlides.add({'type': 'video', 'url': url});
          }
        } else if (type == 'text') {
          final t = s['text']?.toString() ?? '';
          if (t.isNotEmpty) {
            resolvedSlides.add({'type': 'text', 'text': t});
          }
        }
      }
      try {
        final encoded = pollDataList.map(_pollToMap).toList();
        debugPrint('POLLS JSON OK: $encoded');
      } catch (e, st) {
        debugPrint('POLL MAP ERROR: $e');
        debugPrintStack(stackTrace: st);
        rethrow;
      }
      await _loadInitial(); // أو الاعتماد على _listenForNewPosts
      await postRef.update({
        'imageUrls': imageUrls,
        'videoUrls': videoUrls,
        'pollSlides': resolvedSlides,
        'polls': pollDataList.map(_pollToMap).toList(),
        'tags': postTags,
        'status': 'published',
        'updatedAt': FieldValue.serverTimestamp(),
        'authorPrivate': authorPrivate,
        'authorAppearInSearch': authorAppearInSearch,
        'authorHideLikeCounts': authorHideLikeCounts,
        'searchKeywords': buildSearchKeywords(
          title: title,
          body: body,
          tags: postTags,
          author: user.displayName,
        ),
      });
      unawaited(notifyFollowersOfNewPost(
        postId: postRef.id,
        title: title,
      ));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(S.of(context).post)),
      );

    } catch (e, stack) {
      debugPrintStack(stackTrace: stack);
      if (postRef != null) {
        try {
          await postRef.update({
            'status': 'failed',
            'error': e.toString(),
            'updatedAt': FieldValue.serverTimestamp(),
          });
        } catch (_) {}
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('تعذر نشر المنشور: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _publishing = false);
    }
  }

  Future<void> _deletePost(_Post post) async {
    final postId = post.id;
    if (postId == null || postId.isEmpty) return;

    try {
      await _postsRef.doc(postId).delete();
      try {
        await FirebaseStorage.instance.ref('community_posts/$postId').delete();
      } catch (_) {}

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('تم حذف المنشور')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('تعذر حذف المنشور')),
        );
      }
    }
  }

  List<_Post> _visiblePosts(QuerySnapshot<Map<String, dynamic>> snapshot) {
    final List<_Post> posts = [];

    for (final doc in snapshot.docs) {
      final data = doc.data();
      final status = data['status']?.toString().trim().toLowerCase();

      if (status == 'uploading') continue;

      try {
        posts.add(_Post.fromFirestore(doc));
      } catch (e, stack) {
        debugPrintStack(stackTrace: stack);
        posts.add(
          _Post(
            id: doc.id,
            author: (data['authorName'] ?? data['author'] ?? 'طالب UniSpace').toString(),
            authorId: data['authorId']?.toString(),
            authorPhotoUrl: data['authorPhotoUrl']?.toString(),
            title: (data['title'] ?? '').toString(),
            body: (data['body'] ?? '').toString(),
            authorAppearInSearch: data['authorAppearInSearch'] != false,
            createdAt: data['createdAt'] is Timestamp
                ? (data['createdAt'] as Timestamp).toDate()
                : DateTime.now(),
            imagePaths: _stringList(data['imageUrls']),
            videoPaths: _stringList(data['videoUrls']),
            tags: _stringList(data['tags']),
            votes: (data['votes'] as num?)?.toInt() ?? 0,
            isRepost: data['isRepost'] == true,
            repostOf: data['repostOf'] is Map
                ? Map<String, dynamic>.from(data['repostOf'] as Map)
                : null,
          ),
        );
      }
    }

    posts.sort((a, b) => b.createdAt.compareTo(a.createdAt));
    return posts;
  }

  void _openAiSearch() async {
    final RenderBox? box =
    _searchButtonKey.currentContext?.findRenderObject() as RenderBox?;

    Rect? originRect;
    if (box != null && box.hasSize) {
      final offset = box.localToGlobal(Offset.zero);
      originRect = offset & box.size;
    }

    await Navigator.of(context).push(
      _ExpandSearchRoute(
        originRect: originRect,
        child: const RedditStyleAiSearchScreen(),
      ),
    );

    // بعد الرجوع من البحث → حدّث المنشورات
    if (mounted) {
      _loadInitial();
    }
  }



