  Widget _buildFeedBody() {
    if (_initialLoading) {
      return const _FeedSkeleton();
    }

    if (_error != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Text(
            'تعذر تحميل المنشورات.\n\n$_error',
            textAlign: TextAlign.center,
          ),
        ),
      );
    }

    if (_posts.isEmpty) {
      return CustomScrollView(
        slivers: [
          const SliverPadding(
            padding: EdgeInsets.fromLTRB(8, 0, 8, 0),
            sliver: SliverToBoxAdapter(
              child: Column(
                children: [
                  _CommunityHeader(),
                  SizedBox(height: 20),
                ],
              ),
            ),
          ),
          SliverFillRemaining(
            hasScrollBody: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 152),
              child: _CommunityEmptyState(onCreatePost: _newPost),
            ),
          ),
        ],
      );
    }

    return CustomScrollView(
      cacheExtent: 1500,
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      slivers: [

        SliverPadding(
          padding: const EdgeInsets.fromLTRB(8, 0, 8, 0),
          sliver: SliverToBoxAdapter(
            child: Column(
              children: [
                const _CommunityHeader(),
                if (_publishing) ...[

                  const LinearProgressIndicator(),
                ],
                const SizedBox(height: 20),
              ],
            ),
          ),
        ),
        SliverPadding(
          padding: const EdgeInsets.fromLTRB(0, 0, 0, 152),
          sliver: SliverList(
            delegate: SliverChildBuilderDelegate(
                  (context, index) {
                if (index == _posts.length) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 2),
                    child: Center(
                      child: _loadingMore
                          ? const CircularProgressIndicator()
                          : (!_hasMore
                          ? Text(
                        'لا مزيد من المنشورات',
                        style: TextStyle(color: Colors.grey.shade600),
                      )
                          : const SizedBox.shrink()),
                    ),
                  );
                }

                final post = _posts[index];
                return Padding(
                  padding: const EdgeInsets.only(bottom: 2),
                  child: ClipRRect(
                    borderRadius: index == 0
                        ? const BorderRadius.vertical(top: Radius.circular(20))
                        : BorderRadius.zero,
                    child: _PostCard(
                      post: post,
                      onChanged: () async {
                        _blockedIds = await loadBlockedUserIds();
                        if (!mounted) return;
                        setState(() {
                          _posts.removeWhere((p) => isBlockedPost(p, _blockedIds));
                        });
                      },
                      onDelete: () async {
                        await _deletePost(post);
                        if (!mounted) return;
                        setState(() {
                          _posts.removeWhere((p) => p.id == post.id);
                        });
                      },
                      onHidden: () {
                        setState(() {
                          _posts.removeWhere((p) => p.id == post.id);
                        });
                      },
                      feedPosts: _posts,
                      onLoadMoreFeed: _loadMore,
                    ),
                  ),
                );
              },
              childCount: _posts.length + 1,
            ),
          ),
        ),
      ],
    );
  }
}

