class _RedditStylePostCard extends StatefulWidget {
  const _RedditStylePostCard({required this.post, required this.accent});

  final _Post post;
  final Color accent;

  @override
  State<_RedditStylePostCard> createState() => _RedditStylePostCardState();
}

class _RedditStylePostCardState extends State<_RedditStylePostCard> {
  late int _score;
  late bool _isLiked;
  late bool _isDisliked;

  @override
  void initState() {
    super.initState();
    _score = widget.post.votes;
    _isLiked = widget.post.upvoted;
    _isDisliked = widget.post.downvoted;
    final id = widget.post.authorId?.trim() ?? '';
    if (id.isNotEmpty) AuthorProfiles.ensure(id);
  }

  @override
  void didUpdateWidget(covariant _RedditStylePostCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.post.id != widget.post.id ||
        oldWidget.post.votes != widget.post.votes ||
        oldWidget.post.upvoted != widget.post.upvoted ||
        oldWidget.post.downvoted != widget.post.downvoted) {
      _score = widget.post.votes;
      _isLiked = widget.post.upvoted;
      _isDisliked = widget.post.downvoted;
    }
  }

  String _timeAgo(DateTime date) {
    final diff = DateTime.now().difference(date);
    if (diff.inDays > 0) return '${diff.inDays} ي';
    if (diff.inHours > 0) return '${diff.inHours} س';
    if (diff.inMinutes > 0) return '${diff.inMinutes} د';
    return 'الآن';
  }

  String _authorLabel(String author) {
    final cleaned = author.trim();
    if (cleaned.isEmpty || cleaned == 'current_user') return 'طالب UniSpace';
    return cleaned.replaceFirst(RegExp(r'^u/'), '');
  }

  bool get _hasMedia {
    final p = widget.post;
    return p.imagePaths.any((s) => s.trim().isNotEmpty) ||
        p.videoPaths.any((s) => s.trim().isNotEmpty) ||
        p.pollSlides.isNotEmpty ||
        p.pollDataList.isNotEmpty;
  }

  String? get _firstImageUrl {
    for (final u in widget.post.imagePaths) {
      final s = u.trim();
      if (s.startsWith('http')) return s;
    }
    for (final s in widget.post.pollSlides) {
      if (s['type']?.toString() == 'image') {
        final url = (s['url'] ?? s['mediaPath'] ?? '').toString().trim();
        if (url.startsWith('http')) return url;
      }
    }
    return null;
  }

  bool get _hasVideo {
    if (widget.post.videoPaths.any((s) => s.trim().isNotEmpty)) return true;
    for (final s in widget.post.pollSlides) {
      if (s['type']?.toString() == 'video') return true;
    }
    return false;
  }

  bool get _hasPoll {
    if (widget.post.pollDataList.isNotEmpty) return true;
    for (final s in widget.post.pollSlides) {
      if (s['type']?.toString() == 'poll') return true;
    }
    return false;
  }

  Future<void> _likePost() async {
    final post = widget.post;
    final uid = FirebaseAuth.instance.currentUser?.uid;

    if (uid == null || post.id == null || post.id!.isEmpty) return;

    final ref =
    FirebaseFirestore.instance.collection('community_posts').doc(post.id);

    try {
      final newVotes = await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(ref);
        if (!snap.exists) throw Exception('Post does not exist');

        final data = snap.data() ?? <String, dynamic>{};
        final upvotedBy = _stringList(data['upvotedBy']);
        final downvotedBy = _stringList(data['downvotedBy']);
        int votes = (data['votes'] as num?)?.toInt() ?? 0;

        final wasLiked = upvotedBy.contains(uid);
        final wasDisliked = downvotedBy.contains(uid);

        if (wasLiked) {
          // liked → neutral
          upvotedBy.remove(uid);
          votes -= 1;
        } else {
          // neutral / disliked → liked
          if (wasDisliked) {
            downvotedBy.remove(uid);
            votes += 1;
          }
          upvotedBy.add(uid);
          votes += 1;
        }

        tx.update(ref, {
          'upvotedBy': upvotedBy,
          'downvotedBy': downvotedBy,
          'votes': votes,
        });
        return votes;
      });

      if (!mounted) return;
      final likedNow = !post.upvoted;
      setState(() {
        if (post.upvoted) {
          post.upvoted = false;
        } else {
          if (post.downvoted) post.downvoted = false;
          post.upvoted = true;
        }
        post.votes = newVotes;
      });
      HapticFeedback.lightImpact();
      if (likedNow) {
        unawaited(pushNotificationFromMe(
          toUid: post.authorId ?? '',
          type: 'like',
          message: 'أعجب بمنشورك',
          postId: post.id,
          docId: 'like_post_${post.id}_$uid',
        ));
      }
    } catch (e, stack) {
      debugPrint('Like failed: $e');
      debugPrintStack(stackTrace: stack);
    }
  }

  Future<void> _dislikePost() async {
    final post = widget.post;
    final uid = FirebaseAuth.instance.currentUser?.uid;

    if (uid == null || post.id == null || post.id!.isEmpty) return;

    final ref =
    FirebaseFirestore.instance.collection('community_posts').doc(post.id);

    try {
      final newVotes = await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(ref);
        if (!snap.exists) throw Exception('Post does not exist');

        final data = snap.data() ?? <String, dynamic>{};
        final upvotedBy = _stringList(data['upvotedBy']);
        final downvotedBy = _stringList(data['downvotedBy']);
        int votes = (data['votes'] as num?)?.toInt() ?? 0;

        final wasLiked = upvotedBy.contains(uid);
        final wasDisliked = downvotedBy.contains(uid);

        if (wasDisliked) {
          // disliked → neutral
          downvotedBy.remove(uid);
          votes += 1;
        } else {
          // neutral / liked → disliked
          if (wasLiked) {
            upvotedBy.remove(uid);
            votes -= 1;
          }
          downvotedBy.add(uid);
          votes -= 1;
        }

        tx.update(ref, {
          'upvotedBy': upvotedBy,
          'downvotedBy': downvotedBy,
          'votes': votes,
        });
        return votes;
      });

      if (!mounted) return;
      setState(() {
        if (post.downvoted) {
          post.downvoted = false;
        } else {
          if (post.upvoted) post.upvoted = false;
          post.downvoted = true;
        }
        post.votes = newVotes;
      });

      HapticFeedback.mediumImpact();
    } catch (e, stack) {
      debugPrint('Dislike failed: $e');
      debugPrintStack(stackTrace: stack);
    }
  }

  Future<void> _openComments() async {
    await Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => CommentsScreen(post: widget.post)),
    );
    if (!mounted) return;

    try {
      final snap = await FirebaseFirestore.instance
          .collection('community_posts')
          .doc(widget.post.id)
          .get();

      if (!snap.exists) return;
      final data = snap.data()!;
      final uid = FirebaseAuth.instance.currentUser?.uid;

      final votes = (data['votes'] as num?)?.toInt() ?? widget.post.votes;
      final count = (data['commentsCount'] as num?)?.toInt()
          ?? widget.post.commentsCount;
      final upvotedBy = List<String>.from(data['upvotedBy'] ?? []);
      final downvotedBy = List<String>.from(data['downvotedBy'] ?? []);

      setState(() {
        _score = votes;
        _isLiked = uid != null && upvotedBy.contains(uid);
        _isDisliked = uid != null && downvotedBy.contains(uid);
        widget.post.votes = votes;
        widget.post.upvoted = _isLiked;
        widget.post.downvoted = _isDisliked;
      });
    } catch (e) {
      debugPrint('Refresh post after comments failed: $e');
    }
  }

