class _ExpandSearchRoute extends PageRouteBuilder {
  final Rect? originRect;
  final Widget child;

  _ExpandSearchRoute({
    required this.originRect,
    required this.child,
  }) : super(
    pageBuilder: (context, animation, secondaryAnimation) => child,
    transitionDuration: const Duration(milliseconds: 520),
    reverseTransitionDuration: const Duration(milliseconds: 400),
    opaque: false,
  );

  @override
  Widget buildTransitions(
      BuildContext context,
      Animation<double> animation,
      Animation<double> secondaryAnimation,
      Widget child,
      ) {
    final size = MediaQuery.sizeOf(context);

    // مركز الدائرة = مركز زر البحث
    final Offset center = originRect?.center ??
        Offset(size.width * 0.82, 52); // احتياطي قريب من مكان الزر

    // أكبر مسافة محتاجينها عشان الدائرة تغطي الشاشة كلها
    final double maxRadius = _calcMaxRadius(center, size);

    final curved = CurvedAnimation(
      parent: animation,
      curve: Curves.easeOutCubic,
      reverseCurve: Curves.easeInCubic,
    );

    return AnimatedBuilder(
      animation: curved,
      builder: (context, child) {
        final double radius = maxRadius * curved.value;

        return ClipPath(
          clipper: _CircleRevealClipper(
            center: center,
            radius: radius,
          ),
          child: child,
        );
      },
      child: child,
    );
  }

  double _calcMaxRadius(Offset center, Size size) {
    final distances = [
      (center - Offset.zero).distance,
      (center - Offset(size.width, 0)).distance,
      (center - Offset(0, size.height)).distance,
      (center - Offset(size.width, size.height)).distance,
    ];
    return distances.reduce((a, b) => a > b ? a : b);
  }
}

class _CircleRevealClipper extends CustomClipper<Path> {
  final Offset center;
  final double radius;

  _CircleRevealClipper({
    required this.center,
    required this.radius,
  });

  @override
  Path getClip(Size size) {
    return Path()
      ..addOval(Rect.fromCircle(center: center, radius: radius));
  }

  @override
  bool shouldReclip(_CircleRevealClipper oldClipper) {
    return oldClipper.radius != radius || oldClipper.center != center;
  }
}

//=========================================================
class _Post {
  final String? id;
   bool isEdited;
  final String author;
  final String? authorId;
  final String? authorPhotoUrl;
  final bool authorPrivate;
  String title;
  String body;

  final DateTime createdAt;

  final List<String> imagePaths;
  final List<String> videoPaths;

  final List<PollData> pollDataList;
  final bool isRepost;
  final Map<String, dynamic>? repostOf;
  List<String> tags;

  final String? mediaUrl;
  final int commentsCount;
  int votes;

  bool upvoted;
  bool downvoted;
  final bool authorAppearInSearch;
  final List<_Comment> comments;
  final List<Map<String, dynamic>> pollSlides;
  final bool authorHideLikeCounts;

  _Post({
    this.id,
    required this.author,
    this.authorId,
    this.commentsCount = 0,
    this.authorPhotoUrl,
    required this.title,
    required this.body,
    required this.createdAt,
    this.imagePaths = const [],
    this.videoPaths = const [],
    this.pollDataList = const [],
    this.tags = const [],
    this.mediaUrl,
    this.votes = 0,
    this.upvoted = false,
    this.downvoted = false,
    this.isRepost = false,
    this.repostOf,
    this.isEdited = false,
    this.authorPrivate = false,
    this.authorAppearInSearch = true,
    this.authorHideLikeCounts = false,
    this.pollSlides = const [],
    List<_Comment>? comments,
  }) : comments = comments ?? [];

  factory _Post.fromFirestore(DocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data() ?? <String, dynamic>{};
    final rawSlides = data['pollSlides'];
    final pollSlides = rawSlides is List
        ? rawSlides
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList()
        : <Map<String, dynamic>>[];
    final imageUrls = _stringList(
      data['imageUrls'] ?? data['imagePaths'],
    );

    final videoUrls = _stringList(
      data['videoUrls'] ?? data['videoPaths'],
    );

    debugPrint(
      'POST ${doc.id} MEDIA => '
          'images=${imageUrls.length}, '
          'videos=${videoUrls.length}',
    );

    for (final url in imageUrls) {
      debugPrint('IMAGE URL: $url');
    }

    for (final url in videoUrls) {
      debugPrint('VIDEO URL: $url');
    }
    final currentUid =
        FirebaseAuth.instance.currentUser?.uid;

    final upvotedBy =
    _stringList(data['upvotedBy']);

    final downvotedBy =
    _stringList(data['downvotedBy']);

    // ----------------------------------------
    // createdAt
    // ----------------------------------------

    DateTime createdAt = DateTime.now();

    final rawDate = data['createdAt'];

    if (rawDate is Timestamp) {
      createdAt = rawDate.toDate();
    } else if (rawDate is String) {
      createdAt =
          DateTime.tryParse(rawDate) ??
              createdAt;
    }

    // ----------------------------------------
    // Polls
    // ----------------------------------------

    final rawPolls = data['polls'];

    final List<PollData> polls =
    rawPolls is List
        ? rawPolls
        .whereType<Map>()
        .map(
          (e) => _pollFromMap(
        Map<String, dynamic>.from(e),
      ),
    )
        .toList()
        : <PollData>[];

    // ----------------------------------------
    // إنشاء Model
    // ----------------------------------------
    final rawComments = data['comments'];

    final List<_Comment> comments = rawComments is List
        ? rawComments
        .whereType<Map>()
        .map(
          (item) => Map<String, dynamic>.from(item),
    )
        .where((item) {
      final replyToId = item['replyToId'];

      // التعليق الرئيسي فقط
      return replyToId == null ||
          replyToId.toString().isEmpty;
    })
        .map(
          (item) => _commentFromMap(item),
    )
        .toList()
        : <_Comment>[];

    final commentsCount = (data['commentsCount'] as num?)?.toInt()
        ?? (comments.isNotEmpty ? comments.length : 0);
    final isRepost = data['isRepost'] == true;
    final repostRaw = data['repostOf'];

    final Map<String, dynamic>? repostOf = repostRaw is Map
        ? Map<String, dynamic>.from(repostRaw)
        : null;
    return _Post(
      id: doc.id,
      authorPrivate: data['authorPrivate'] == true,
      author:
      (data['authorName'] ??
          data['author'] ??
          'طالب UniSpace')
          .toString(),
      authorHideLikeCounts: data['authorHideLikeCounts'] == true,
      authorId: data['authorId']?.toString(),
      authorPhotoUrl: data['authorPhotoUrl']?.toString(),
      isEdited: data['isEdited'] == true,
      title: (data['title'] ?? '').toString(),
      commentsCount: commentsCount,
      body: (data['body'] ?? '').toString(),

      createdAt: createdAt,

      imagePaths: imageUrls,
      videoPaths: videoUrls,

      isRepost: isRepost,
      repostOf: repostOf,
      pollDataList: polls,
      pollSlides: pollSlides,

      tags: _stringList(
        data['tags'],
      ),

      mediaUrl:
      data['mediaUrl']?.toString(),

      votes:
      (data['votes'] as num?)?.toInt() ??
          0,

      upvoted:
      currentUid != null &&
          upvotedBy.contains(currentUid),

      comments: comments,

      downvoted:
      currentUid != null &&
          downvotedBy.contains(currentUid),
    );
  }

  String get timeAgo {
    final now = DateTime.now();

    final difference =
    now.difference(createdAt);

    if (difference.inSeconds < 60) {
      return '${difference.inSeconds}s';
    }

    if (difference.inMinutes < 60) {
      return '${difference.inMinutes}m';
    }

    if (difference.inHours < 24) {
      return '${difference.inHours}h';
    }

    if (difference.inDays < 7) {
      return '${difference.inDays}d';
    }

    if (difference.inDays < 30) {
      return '${(difference.inDays / 7).floor()}w';
    }

    if (difference.inDays < 365) {
      return '${(difference.inDays / 30).floor()}mo';
    }

    return '${(difference.inDays / 365).floor()}y';
  }
}

List<String> _stringList(dynamic value) {
  if (value is! List) {
    return <String>[];
  }

  return value
      .map((e) => e.toString())
      .where((e) => e.isNotEmpty)
      .toList();
}


// ==================== PostCard ====================
class _PostCard extends StatefulWidget {
  final _Post post;
  final VoidCallback onChanged;
  final Future<void> Function() onDelete;
  final bool isEmbedded;
  final bool isInsideComments;
  final List<_Post>? feedPosts;
  final Future<void> Function()? onLoadMoreFeed;
  final VoidCallback? onHidden;
  final bool showAuthorHeader;
  final bool compact;
  final bool allowPin;
  final bool isPinned;
  final Future<void> Function(String? postId)? onSetPinned;

  const _PostCard({
    required this.post,
    required this.onChanged,
    required this.onDelete,
    this.isEmbedded = false,
    this.isInsideComments = false,
    this.feedPosts,
    this.onLoadMoreFeed,
    this.onHidden,
    this.showAuthorHeader= true,
    this.compact = false,
    this.allowPin = false,
    this.isPinned = false,
    this.onSetPinned,

  });

  @override
  State<_PostCard> createState() => _PostCardState();
}

class _PostCardState extends State<_PostCard> {
  final GlobalKey _likeButtonKey = GlobalKey();
  final Map<int, dynamic> _pollAnswers = {};

  bool _isNavigating = false;
  Timer? _updateTimer;
  int _currentPollPage = 0;
  final Map<String, VideoPlayerController> _pollVideoControllers = {};

  bool _isSaved = false;

  Future<void> _togglePinPost() async {
    final id = widget.post.id?.trim();
    if (id == null || id.isEmpty || widget.onSetPinned == null) return;
    final next = widget.isPinned ? null : id;
    await widget.onSetPinned!(next);
    if (!mounted) return;
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
      SnackBar(
        content: Text(next == null ? 'تم إلغاء التثبيت' : 'تم تثبيت المنشور'),
      ),
    );
  }

  Future<void> _loadSavedState() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final postId = widget.post.id?.trim();
    if (uid == null || postId == null || postId.isEmpty) return;
    final doc = await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('saved_posts')
        .doc(postId)
        .get();
    if (mounted) setState(() => _isSaved = doc.exists);
  }

  Future<void> _toggleSavePost() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final postId = widget.post.id?.trim();
    if (uid == null || postId == null || postId.isEmpty) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final ref = FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('saved_posts')
        .doc(postId);

    try {
      if (_isSaved) {
        await ref.delete();
        if (!mounted) return;
        setState(() => _isSaved = false);
        widget.onChanged();
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          const SnackBar(content: Text('تم إلغاء الحفظ')),
        );
      } else {
        await ref.set({
          'postId': postId,
          'savedAt': FieldValue.serverTimestamp(),
        });
        if (!mounted) return;
        setState(() => _isSaved = true);
        widget.onChanged();
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          const SnackBar(content: Text('تم حفظ المنشور')),
        );
      }
    } catch (e) {
      debugPrint('toggle save failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر حفظ المنشور')),
      );
    }
  }

  Future<_Post> _resolveRepostRoot(_Post post) async {
    if (!post.isRepost) return post;

    var id = post.repostOf?['postId']?.toString().trim();
    _Post current = post;

    for (var i = 0; i < 5; i++) {
      if (id == null || id.isEmpty) return current;

      try {
        final query = await FirebaseFirestore.instance
            .collection('community_posts')
            .where(FieldPath.documentId, isEqualTo: id)
            .limit(1)
            .get();

        if (query.docs.isEmpty) return current;

        final found = _Post.fromFirestore(query.docs.first);
        if (!found.isRepost) return found;

        current = found;
        id = found.repostOf?['postId']?.toString().trim();
      } catch (e) {
        debugPrint('resolve repost root failed: $e');
        return current;
      }
    }
    return current;
  }

  List<_PostMediaItem> _downloadableItemsFor(_Post post) {
    final items = <_PostMediaItem>[];
    for (final p in post.imagePaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.image(p.trim()));
    }
    for (final p in post.videoPaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.video(p.trim()));
    }
    return items;
  }

  Future<void> _saveMediaItem(_PostMediaItem item) async {
    final path = item.path.trim();
    final isVideo = item.kind == _MediaKind.video;
    if (path.startsWith('http://') || path.startsWith('https://')) {
      final file = await DefaultCacheManager().getSingleFile(path);
      if (isVideo) {
        await Gal.putVideo(file.path, album: 'UniSpace');
      } else {
        await Gal.putImage(file.path, album: 'UniSpace');
      }
    } else {
      if (isVideo) {
        await Gal.putVideo(path, album: 'UniSpace');
      } else {
        await Gal.putImage(path, album: 'UniSpace');
      }
    }
  }

  Future<void> _downloadPostMedia() async {
    final pager = _FullscreenPostPagerState.current;
    final target = pager?.currentPost ?? widget.post;
    final items = _downloadableItemsFor(target);
    if (items.isEmpty) return;

    final overlayContext = pager?.context ?? context;

    List<_PostMediaItem> selected = items;
    if (items.length > 1) {
      final picked = await showModalBottomSheet<_DownloadPickResult>(
        context: overlayContext,
        useRootNavigator: true,
        showDragHandle: true,
        builder: (_) => _DownloadMediaSheet(items: items),
      );
      if (picked == null || picked.items.isEmpty) return;
      selected = picked.items;
    }

    final granted = await Gal.requestAccess(toAlbum: true);
    if (granted != true) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('يجب السماح بالوصول لألبوم الصور')),
      );
      return;
    }

    showDialog<void>(
      context: overlayContext,
      useRootNavigator: true,
      barrierDismissible: false,
      builder: (_) => const Center(child: CircularProgressIndicator()),
    );

    try {
      for (final item in selected) {
        await _saveMediaItem(item);
      }
      if (Navigator.of(overlayContext, rootNavigator: true).canPop()) {
        Navigator.of(overlayContext, rootNavigator: true).pop();
      }
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          content: Text(
            selected.length == 1 ? 'تم حفظ الوسائط' : 'تم حفظ ${selected.length} ملفات',
          ),
        ),
      );
    } catch (e) {
      debugPrint('download media failed: $e');
      if (Navigator.of(overlayContext, rootNavigator: true).canPop()) {
        Navigator.of(overlayContext, rootNavigator: true).pop();
      }
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر التحميل')),
      );
    }
  }

  Future<void> _initPollVideo(String url) async {
    final u = url.trim();
    if (u.isEmpty || !u.startsWith('http')) return;
    if (_pollVideoControllers.containsKey(u)) return;

    final c = VideoPlayerController.networkUrl(Uri.parse(u));
    try {
      await c.initialize();
      await c.setLooping(true);
      if (!mounted) {
        await c.dispose();
        return;
      }
      _pollVideoControllers[u] = c;
      if (mounted) setState(() {});
    } catch (e) {
      debugPrint('poll video init failed: $e');
      await c.dispose();
    }
  }
  bool _hasAnswer(PollData poll, int key) {
    if (!_pollAnswers.containsKey(key)) return false;
    final answer = _pollAnswers[key];
    if (answer is String) return answer.trim().isNotEmpty;
    if (answer is Set) return answer.isNotEmpty;
    if (answer is Map) {
      return answer.values.any((v) => v is Set && v.isNotEmpty);
    }
    if (answer is int || answer is double) return true;
    if (answer is List) {
      return answer.isNotEmpty;
    }
    if (answer is DateTime) {
      if (poll.includeTime || poll.dateConfig?.includeTime == true) {
        return _pollAnswers.containsKey(key + 100000);
      }
      return true;
    }
    if (answer is TimeOfDay) return true;
    return false;
  }
// فقط منشورات فيها صورة/فيديو وما فيهاش بول
  List<_Post> _swipeableMediaPosts(List<_Post> source) {
    return source.where((p) {
      final hasPoll = p.pollDataList.isNotEmpty;
      if (hasPoll) return false;
      final hasMedia = p.imagePaths.any((s) => s.trim().isNotEmpty) ||
          p.videoPaths.any((s) => s.trim().isNotEmpty);
      return hasMedia;
    }).toList();
  }

  List<_PostMediaItem> _mediaItemsForPost(_Post post) {
    final items = <_PostMediaItem>[];
    for (final p in post.imagePaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.image(p.trim()));
    }
    for (final p in post.videoPaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.video(p.trim()));
    }
    return items;
  }
  void _precachePostMedia() {
    // ===== خارج البول =====
    for (final p in widget.post.imagePaths) {
      final u = p.trim();
      if (u.startsWith('http')) {
        precacheImage(CachedNetworkImageProvider(u), context);
      }
    }

    // ===== داخل البول =====
    for (final s in widget.post.pollSlides) {
      final type = s['type']?.toString();
      if (type == 'image') {
        final u = (s['url'] ?? s['mediaPath'] ?? '').toString().trim();
        if (u.startsWith('http')) {
          precacheImage(CachedNetworkImageProvider(u), context);
        }
      }
      if (s['type']?.toString() == 'video') {
        final u = (s['url'] ?? s['mediaPath'] ?? '').toString();
        _initPollVideo(u);
      }
      // الفيديو: لا يوجد precache جاهز مثل الصور؛ يُهيَّأ عند العرض
      // يمكن لاحقاً تهيئة خفيفة للفيديو الحالي فقط
    }
  }
  @override
  void initState() {
    super.initState();
    _updateTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
    _loadSavedState();

    // بعد أول إطار (لأن context جاهز لـ precacheImage)
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _precachePostMedia();
    });
  }

  List<_PostMediaItem> _postMediaItems() {
    final items = <_PostMediaItem>[];
    for (final p in widget.post.imagePaths) {
      if (p.trim().isNotEmpty) {
        items.add(_PostMediaItem.image(p.trim()));
      }
    }
    for (final p in widget.post.videoPaths) {
      if (p.trim().isNotEmpty) {
        items.add(_PostMediaItem.video(p.trim()));
      }
    }
    return items;
  }

  void _openPostMediaFullscreen(String currentPath) {
    final items = _postMediaItems();
    if (items.isEmpty) return;

    final i = items.indexWhere((e) => e.path == currentPath);
    final index = i < 0 ? 0 : i;

    // ===== الجديد: إذا عندنا لائحة كل المنشورات، نفتح الـ Pager العمودي =====
    final allPosts = widget.feedPosts;
    if (allPosts != null && allPosts.isNotEmpty) {
      final swipeable = _swipeableMediaPosts(allPosts);
      debugPrint('ALL feedPosts = ${allPosts.length}');
      debugPrint('SWIPEABLE     = ${swipeable.length}');
      debugPrint('CURRENT id    = ${widget.post.id}');
      final startIndex = swipeable.indexWhere((p) => p.id == widget.post.id);

      if (startIndex != -1) {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => FullscreenPostPager(
              posts: swipeable,
              initialIndex: startIndex,
              initialMediaIndex: index,
              onChanged: widget.onChanged,
              menuButton: _buildFullscreenMenu(),
              onAuthorBlocked: (id) {
                widget.onChanged();
              },
              onNearEnd: () async {
                // 1) حمّل الدفعة التالية في الشاشة الأم
                await widget.onLoadMoreFeed?.call();
                // 2) أعد كل المنشورات الحالية (بعد التحديث)
                return widget.feedPosts ?? <_Post>[];
              },
            ),
          ),
        );
        return;
      }
    }

    // ===== الاحتياطي القديم: منشور واحد فقط (بدون سحب عمودي) =====
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => FullscreenMediaViewer(
          items: items,
          initialIndex: index,
          authorName: _authorLabel(widget.post.author),
          authorPhotoUrl: widget.post.authorPhotoUrl,
          postTitle: widget.post.title,
          postBody: widget.post.body,
          menuButton: _buildFullscreenMenu(),
          votes: widget.post.votes,
          isLiked: widget.post.upvoted,
          isDisliked: widget.post.downvoted,
          commentsCount: widget.post.comments.length,
          tagsCount: widget.post.tags.length,
          onLike: _likePost,
          onDislike: _dislikePost,
          onComment: () async {
            await _openComments();
            return widget.post.comments.length;
          },
          onTags: _showTagsSheet,
        ),
      ),
    );
  }
  Future<void> _openOriginalPost() async {
    final id = widget.post.repostOf?['postId']?.toString().trim();
    if (id == null || id.isEmpty) return;

    final nav = Navigator.of(context, rootNavigator: true);

    try {
      final query = await FirebaseFirestore.instance
          .collection('community_posts')
          .where(FieldPath.documentId, isEqualTo: id)
          .limit(1)
          .get();

      if (!mounted) return;

      if (query.docs.isEmpty) {
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          const SnackBar(content: Text('المنشور الأصلي غير موجود')),
        );
        return;
      }

      final original = _Post.fromFirestore(query.docs.first);

      await nav.push(
        MaterialPageRoute(
          builder: (_) => CommentsScreen(post: original),
        ),
      );

      // بعد الرجوع فقط — وليس قبل الفتح
      if (mounted) widget.onChanged();
    } catch (e) {
      debugPrint('Open original post failed: $e');
    }
  }
  @override
  void dispose() {
    _updateTimer?.cancel();
    for (final c in _pollVideoControllers.values) {
      c.dispose();
    }
    _pollVideoControllers.clear();
    super.dispose();
  }

  Future<void> _openComments() async {
    if (widget.isInsideComments) return;
    if (_isNavigating) return;
    _isNavigating = true;
    final hidden = await Navigator.push<bool>(
      context,
      MaterialPageRoute(builder: (_) => CommentsScreen(post: widget.post)),
    );
    _isNavigating = false;
    if (!mounted) return;
    if (hidden == true) {
      widget.onHidden?.call();
    } else {
      widget.onChanged();
    }
  }

  Widget _buildImageSlide(String path) {
    final value = path.trim();

    if (value.isEmpty) {
      return _mediaErrorWidget('رابط الصورة فارغ');
    }

    final bool isNetwork =
        value.startsWith('http://') || value.startsWith('https://');

    return _AutoSizeImage(
      path: value,
      isNetwork: isNetwork,
      maxHeight: 480,
      onTap: () {
        final postImages = widget.post.imagePaths
            .where((p) => p.trim().isNotEmpty)
            .toList();
        final isFromPost = postImages.contains(value);

        if (isFromPost) {
          _openPostMediaFullscreen(value); // ← هنا
        } else {
          // ===== صورة من داخل البول → عارض بسيط =====
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (_) => SimpleFullscreenImageViewer(
                images: [value],
                initialIndex: 0,
              ),
            ),
          );
        }
      },
    );
  }

