      );
      return;
    }

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => UserProfileScreen(
          userId: id,
          initialName: _authorLabel(widget.post.author),
          initialPhotoUrl: widget.post.authorPhotoUrl,
        ),
      ),
    );
  }
  Widget _wrapSlide({
    required Widget child,
    required bool isDark,
    required ThemeData theme,
  }) {
    return GestureDetector(
      onTap: () {}, // لا يفتح التعليقات
      behavior: HitTestBehavior.opaque,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(18),
        child: ColoredBox(
          color: isDark ? theme.colorScheme.surface : Colors.white,
          child: child,
        ),
      ),
    );
  }

  Widget _buildPollBlock(List<PollData> polls) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    final pages = <Widget>[];

    for (final s in widget.post.pollSlides) {
      if (s['type'] == 'text') {
        pages.add(
          Center(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Text(
                s['text']?.toString() ?? '',
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontSize: 16,
                  height: 1.5,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ),
        );
      }
      // لاحقاً: image / video
    }

    for (int i = 0; i < polls.length; i++) {
      pages.add(
        PollQuestionSlideView(
          poll: polls[i],
          slideIndex: i,
          answers: _pollAnswers,
          onAnswer: (key, value) {
            setState(() => _pollAnswers[key] = value);
          },
        ),
      );
    }

    pages.add(_buildSubmitSlide(polls, theme, isDark));

    return GestureDetector(
      onTap: () {},
      behavior: HitTestBehavior.opaque,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(18),
        child: Container(
          height: 320, // ← ارتفاع ثابت واضح
          color: isDark ? theme.colorScheme.surface : Colors.white,
          child: Column(
            children: [
              Expanded(
                child: PageView.builder(
                  itemCount: pages.length,
                  onPageChanged: (i) => setState(() => _currentPollPage = i),
                  itemBuilder: (context, index) => pages[index],
                ),
              ),
              if (pages.length > 1)
                Padding(
                  padding: const EdgeInsets.only(bottom: 8, top: 4),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: List.generate(pages.length, (i) {
                      return Container(
                        margin: const EdgeInsets.symmetric(horizontal: 3),
                        width: _currentPollPage == i ? 10 : 6,
                        height: 6,
                        decoration: BoxDecoration(
                          color: _currentPollPage == i
                              ? theme.colorScheme.primary
                              : Colors.grey.shade400,
                          borderRadius: BorderRadius.circular(10),
                        ),
                      );
                    }),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildSubmitSlide(
      List<PollData> polls,
      ThemeData theme,
      bool isDark,
      ) {
    final required = <int>[];
    for (int i = 0; i < polls.length; i++) {
      if (polls[i].isRequired) required.add(i);
    }

    final answeredRequired =
        required.where((i) => _hasAnswer(polls[i], i)).length;
    final totalRequired = required.length;
    final answeredAll = List.generate(polls.length, (i) => i)
        .where((i) => _hasAnswer(polls[i], i))
        .length;

    final ok = totalRequired == 0
        ? answeredAll == polls.length
        : answeredRequired == totalRequired;

    Object? serializeAnswer(dynamic v) {
      if (v == null) return null;
      if (v is String || v is num || v is bool) return v;
      if (v is DateTime) return v.toIso8601String();
      if (v is TimeOfDay) {
        return {'hour': v.hour, 'minute': v.minute};
      }
      if (v is Set) {
        return v.map(serializeAnswer).toList();
      }
      if (v is List) {
        return v.map(serializeAnswer).toList();
      }
      if (v is Map) {
        return v.map(
              (k, val) => MapEntry(k.toString(), serializeAnswer(val)),
        );
      }
      return v.toString();
    }

    return Padding(
      padding: const EdgeInsets.all(16),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(
            ok ? Icons.check_circle_outline : Icons.pending_outlined,
            size: 48,
            color: ok ? AppTeal.main : theme.colorScheme.primary,
          ),
          const SizedBox(height: 12),
          const Text(
            'Submit answers',
            style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800),
          ),
          const SizedBox(height: 8),
          Text('$answeredAll / ${polls.length} answered'),
          if (totalRequired > 0) ...[
            const SizedBox(height: 4),
            Text(
              '$answeredRequired / $totalRequired required',
              style: TextStyle(
                color: ok ? AppTeal.main : Colors.redAccent,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
          const SizedBox(height: 16),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: () async {
                if (!ok) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('يجب الإجابة على جميع الأسئلة الإلزامية أولاً'),
                      backgroundColor: Colors.redAccent,
                    ),
                  );
                  return;
                }

                final uid = FirebaseAuth.instance.currentUser?.uid;
                final postId = widget.post.id; // ← متاح في _PostCard فقط
                final user = FirebaseAuth.instance.currentUser;

                if (uid == null || postId == null || postId.isEmpty) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
                  );
                  return;
                }
// ===== اسم الحساب =====
                String respondentName = 'طالب UniSpace';
                if (user != null) {
                  try {
                    final doc = await FirebaseFirestore.instance
                        .collection('users')
                        .doc(uid)
                        .get();
                    final data = doc.data();
                    final fromProfile =
                        data?['userName'] ?? data?['name'] ?? data?['displayName'];
                    if (fromProfile is String && fromProfile.trim().isNotEmpty) {
                      respondentName = fromProfile.trim();
                    } else if (user.displayName != null &&
                        user.displayName!.trim().isNotEmpty) {
                      respondentName = user.displayName!.trim();
                    }
                  } catch (_) {
                    if (user.displayName != null && user.displayName!.trim().isNotEmpty) {
                      respondentName = user.displayName!.trim();
                    }
                  }
                }
                Object? serializeAnswer(dynamic v) {
                  if (v == null) return null;
                  if (v is String || v is num || v is bool) return v;
                  if (v is DateTime) return v.toIso8601String();
                  if (v is TimeOfDay) return {'hour': v.hour, 'minute': v.minute};
                  if (v is Set) return v.map(serializeAnswer).toList();
                  if (v is List) return v.map(serializeAnswer).toList();
                  if (v is Map) {
                    return v.map((k, val) => MapEntry(k.toString(), serializeAnswer(val)));
                  }
                  return v.toString();
                }

                final messenger = ScaffoldMessenger.maybeOf(context);

                try {
                  final encoded = <String, dynamic>{};
                  _pollAnswers.forEach((k, v) {
                    encoded[k.toString()] = serializeAnswer(v);
                  });
                  final messenger = ScaffoldMessenger.maybeOf(context);
                  await FirebaseFirestore.instance
                      .collection('community_posts')
                      .doc(postId)
                      .collection('poll_responses')
                      .doc(uid)
                      .set({
                    'answers': encoded,
                    'respondentId': uid,
                    'respondentName': respondentName,
                    'submittedAt': FieldValue.serverTimestamp(),
                  }, SetOptions(merge: true));

                  if (!mounted) return;
                  messenger?.hideCurrentSnackBar();
                  messenger?.showSnackBar(
                    const SnackBar(content: Text('تم إرسال الإجابات')),
                  );
                } catch (e) {
                  if (!mounted) return;
                  messenger?.showSnackBar(
                    const SnackBar(content: Text('تعذر إرسال الإجابات')),
                  );
                }
              },
              child: const Text('Confirm & Submit'),
            ),
          ),
        ],
      ),
    );
  }

  String _authorLabel(String author) {
    final cleaned = author.trim();
    if (cleaned.isEmpty || cleaned == 'current_user') return 'طالب UniSpace';
    return cleaned.replaceFirst(RegExp(r'^u/'), '');
  }

  Future<void> _likePost() async {
    final post = widget.post;
    final uid = FirebaseAuth.instance.currentUser?.uid;

    if (uid == null || post.id == null || post.id!.isEmpty) return;

    final ref =
    FirebaseFirestore.instance.collection('community_posts').doc(post.id);

    try {
      final newVotes = await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(ref);
        if (!snap.exists) throw Exception('Post does not exist');

        final data = snap.data() ?? <String, dynamic>{};
        final upvotedBy = _stringList(data['upvotedBy']);
        final downvotedBy = _stringList(data['downvotedBy']);
        int votes = (data['votes'] as num?)?.toInt() ?? 0;

        final wasLiked = upvotedBy.contains(uid);
        final wasDisliked = downvotedBy.contains(uid);

        if (wasLiked) {
          // liked → neutral
          upvotedBy.remove(uid);
          votes -= 1;
        } else {
          // neutral / disliked → liked
          if (wasDisliked) {
            downvotedBy.remove(uid);
            votes += 1;
          }
          upvotedBy.add(uid);
          votes += 1;
        }

        tx.update(ref, {
          'upvotedBy': upvotedBy,
          'downvotedBy': downvotedBy,
          'votes': votes,
        });
        return votes;
      });

      if (!mounted) return;
      final likedNow = !post.upvoted;
      setState(() {
        if (post.upvoted) {
          post.upvoted = false;
        } else {
          if (post.downvoted) post.downvoted = false;
          post.upvoted = true;
        }
        post.votes = newVotes;
      });
      HapticFeedback.lightImpact();
      if (likedNow) {
        unawaited(pushNotificationFromMe(
          toUid: post.authorId ?? '',
          type: 'like',
          message: 'أعجب بمنشورك',
          postId: post.id,
          docId: 'like_post_${post.id}_$uid',
        ));
      }
    } catch (e, stack) {
      debugPrint('Like failed: $e');
      debugPrintStack(stackTrace: stack);
    }
  }

  Future<void> _dislikePost() async {
    final post = widget.post;
    final uid = FirebaseAuth.instance.currentUser?.uid;

    if (uid == null || post.id == null || post.id!.isEmpty) return;

    final ref =
    FirebaseFirestore.instance.collection('community_posts').doc(post.id);

    try {
      final newVotes = await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(ref);
        if (!snap.exists) throw Exception('Post does not exist');

        final data = snap.data() ?? <String, dynamic>{};
        final upvotedBy = _stringList(data['upvotedBy']);
        final downvotedBy = _stringList(data['downvotedBy']);
        int votes = (data['votes'] as num?)?.toInt() ?? 0;

        final wasLiked = upvotedBy.contains(uid);
        final wasDisliked = downvotedBy.contains(uid);

        if (wasDisliked) {
          // disliked → neutral
          downvotedBy.remove(uid);
          votes += 1;
        } else {
          // neutral / liked → disliked
          if (wasLiked) {
            upvotedBy.remove(uid);
            votes -= 1;
          }
          downvotedBy.add(uid);
          votes -= 1;
        }

        tx.update(ref, {
          'upvotedBy': upvotedBy,
          'downvotedBy': downvotedBy,
          'votes': votes,
        });
        return votes;
      });

      if (!mounted) return;
      setState(() {
        if (post.downvoted) {
          post.downvoted = false;
        } else {
          if (post.upvoted) post.upvoted = false;
          post.downvoted = true;
        }
        post.votes = newVotes;
      });

      HapticFeedback.mediumImpact();
    } catch (e, stack) {
      debugPrint('Dislike failed: $e');
      debugPrintStack(stackTrace: stack);
    }
  }

