  Future<void> _openSystemShareSheet() async {
    try {
      final file = await _buildPostShareImage();
      final text = _postSharePayload();

      final box = context.findRenderObject() as RenderBox?;
      final origin =
      box != null ? box.localToGlobal(Offset.zero) & box.size : null;

      if (file != null) {
        await Share.shareXFiles(
          [XFile(file.path)],
          text: text,
          subject: 'UniSpace',
          sharePositionOrigin: origin,
        );
      } else {
        // احتياطي: نص فقط إذا فشل توليد الصورة
        await Share.share(
          text,
          subject: 'UniSpace',
          sharePositionOrigin: origin,
        );
      }
    } catch (e, st) {
      debugPrint('Share failed: $e');
      debugPrintStack(stackTrace: st);
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر فتح قائمة المشاركة')),
      );
    }
  }

  Future<File?> _buildPostShareImage() async {
    final repaintKey = GlobalKey();
    final completed = Completer<void>();

    // نعرض البطاقة خارج الشاشة لالتقاطها
    final entry = OverlayEntry(
      builder: (ctx) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!completed.isCompleted) completed.complete();
        });
        return Positioned(
          left: -5000, // خارج الشاشة
          top: 0,
          child: Material(
            color: Colors.transparent,
            child: RepaintBoundary(
              key: repaintKey,
              child: _PostShareCard(
                author: _authorLabel(widget.post.author),
                authorPhotoUrl: widget.post.authorPhotoUrl,
                title: widget.post.title.trim(),
                body: widget.post.body.trim(),
                imageUrl: widget.post.imagePaths
                    .map((e) => e.trim())
                    .firstWhere((e) => e.startsWith('http'), orElse: () => ''),
              ),
            ),
          ),
        );
      },
    );

    final overlay = Overlay.of(context);
    overlay.insert(entry);

    try {
      await completed.future;
      // إطار إضافي لضمان اكتمال الرسم
      await Future<void>.delayed(const Duration(milliseconds: 80));
      await WidgetsBinding.instance.endOfFrame;

      final boundary =
      repaintKey.currentContext?.findRenderObject() as RenderRepaintBoundary?;
      if (boundary == null) return null;

      final image = await boundary.toImage(pixelRatio: 3);
      final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
      if (bytes == null) return null;

      final dir = await getTemporaryDirectory();
      final file = File(
        '${dir.path}/unispace_share_${widget.post.id ?? DateTime.now().millisecondsSinceEpoch}.png',
      );
      await file.writeAsBytes(bytes.buffer.asUint8List());
      return file;
    } finally {
      entry.remove();
    }
  }

