  Future<void> _reportPost() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final pager = _FullscreenPostPagerState.current;
    final target = pager?.currentPost ?? widget.post;
    final postId = target.id?.trim();
    if (postId == null || postId.isEmpty) return;

    final ownerId = target.authorId?.trim();
    if (ownerId != null && ownerId.isNotEmpty && ownerId == user.uid) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('لا يمكنك تبليغ محتواك')),
      );
      return;
    }

    final already = await hasCommunityReport(
      type: CommunityReportType.post,
      targetId: postId,
    );
    if (!mounted) return;

    if (!already) {
      final result = await showCommunityReportSheet(
        context,
        type: CommunityReportType.post,
        useRootNavigator: true,
      );
      if (result == null || !mounted) return;

      try {
        await submitCommunityReport(
          type: CommunityReportType.post,
          targetId: postId,
          ownerId: ownerId,
          ownerName: _authorLabel(target.author),
          reason: result.reasonId,
          details: result.details,
          snapshot: communityReportSnapshotFromPost(target),
        );
      } catch (error) {
        debugPrint('Community report failed: $error');
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(messageForCommunityReportError(error))),
        );
        return;
      }
    }

    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('hidden_posts')
          .doc(postId)
          .set({
        'postId': postId,
        'source': 'report',
        'hiddenAt': FieldValue.serverTimestamp(),
      });
    } catch (e) {
      debugPrint('hide after report failed: $e');
    }

    if (!mounted) return;
    await showReportSubmittedSheet(
      context,
      type: CommunityReportType.post,
      ownerId: ownerId,
      ownerName: _authorLabel(target.author),
      ownerPhotoUrl: target.authorPhotoUrl,
      useRootNavigator: true,
      alreadyReported: already,
      onBlocked: () {
        if (ownerId == null) return;
        final livePager = _FullscreenPostPagerState.current;
        if (livePager != null && livePager.mounted) {
          livePager._onAuthorBlocked(ownerId);
        }
        widget.onHidden?.call();
        widget.onChanged();
      },
    );

    if (!mounted) return;
    final livePager = _FullscreenPostPagerState.current;
    if (livePager != null && livePager.mounted) {
      livePager.hidePost(postId);
    } else {
      widget.onHidden?.call();
      if (!widget.isInsideComments) widget.onChanged();
    }
  }

  Future<void> _repostPost() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    if (widget.post.id == null || widget.post.id!.trim().isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إعادة نشر هذا المنشور')),
      );
      return;
    }

    final original = await _resolveRepostRoot(widget.post);
    if (!mounted) return;

    final originalId = original.id?.trim();
    if (originalId == null || originalId.isEmpty) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إعادة نشر هذا المنشور')),
      );
      return;
    }

    final allowed = await canRepostAuthor(original.authorId ?? '');
    if (!allowed) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('إعادة النشر غير مسموحة لهذا الحساب')),
      );
      return;
    }

    final draft = await _askRepostDraft(original);
    if (!mounted) return;
    if (draft == null) return;

    String? authorPhotoUrl;
    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      authorPhotoUrl = userDoc.data()?['profileImageUrl']?.toString();
    } catch (_) {}

    if (!mounted) return;

    final authorName = (user.displayName ?? '').trim().isNotEmpty
        ? user.displayName!.trim()
        : 'طالب UniSpace';

    String? firstImage;
    for (final path in original.imagePaths) {
      final u = path.trim();
      if (u.startsWith('http://') || u.startsWith('https://')) {
        firstImage = u;
        break;
      }
    }

    final bodyPreview = original.body.trim();
    final shortBody = bodyPreview.length > 180
        ? '${bodyPreview.substring(0, 180)}…'
        : bodyPreview;

    try {
      await FirebaseFirestore.instance.collection('community_posts').add({
        'authorId': user.uid,
        'authorName': authorName,
        'authorPhotoUrl': authorPhotoUrl,
        'title': draft.title,
        'body': draft.body,
        'searchKeywords': buildSearchKeywords(
          title: draft.title,
          body: draft.body,
          author: authorName,
        ),
        'status': 'published',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
        'isRepost': true,
        'repostOf': {
          'postId': originalId,
          'authorId': original.authorId,
          'authorName': _authorLabel(original.author),
          'authorPhotoUrl': original.authorPhotoUrl,
          'title': original.title.trim(),
          'body': shortBody,
          'imageUrl': firstImage,
          'imageUrls': original.imagePaths,
          'videoUrls': original.videoPaths,
        },
        'imageUrls': <String>[],
        'videoUrls': <String>[],
        'pollSlides': <Map<String, dynamic>>[],
        'polls': <Map<String, dynamic>>[],
        'tags': <String>[],
        'votes': 0,
        'upvotedBy': <String>[],
        'downvotedBy': <String>[],
        'commentsCount': 0,
        'version': 1,
      });

      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تمت إعادة النشر')),
      );
    } catch (e, st) {
      debugPrint('Repost failed: $e');
      debugPrintStack(stackTrace: st);
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إعادة النشر، حاول مجددًا')),
      );
    }
  }

  Future<void> _publishCommunityRepost({
    required _Post original,
    required _RepostDraft draft,
    _Comment? comment,
  }) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    final originalId = original.id?.trim();
    if (originalId == null || originalId.isEmpty) return;

    String? authorPhotoUrl;
    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      authorPhotoUrl = userDoc.data()?['profileImageUrl']?.toString();
    } catch (_) {}

    final authorName = (user.displayName ?? '').trim().isNotEmpty
        ? user.displayName!.trim()
        : 'طالب UniSpace';

    String? firstImage;
    for (final path in original.imagePaths) {
      final u = path.trim();
      if (u.startsWith('http://') || u.startsWith('https://')) {
        firstImage = u;
        break;
      }
    }

    final sourceText = comment?.text.trim() ?? original.body.trim();
    final shortBody = sourceText.length > 180
        ? '${sourceText.substring(0, 180)}…'
        : sourceText;

    String authorLabel(String author) {
      final cleaned = author.trim();
      if (cleaned.isEmpty || cleaned == 'current_user') return 'طالب UniSpace';
      return cleaned.replaceFirst(RegExp(r'^u/'), '');
    }

    await FirebaseFirestore.instance.collection('community_posts').add({
      'authorId': user.uid,
      'authorName': authorName,
      'authorPhotoUrl': authorPhotoUrl,
      'title': draft.title,
      'body': draft.body,
      'searchKeywords': buildSearchKeywords(
        title: draft.title,
        body: draft.body,
        author: authorName,
      ),
      'status': 'published',
      'createdAt': FieldValue.serverTimestamp(),
      'updatedAt': FieldValue.serverTimestamp(),
      'isRepost': true,
      'repostOf': {
        'postId': originalId,
        'authorId': original.authorId,
        'authorName': authorLabel(original.author),
        'authorPhotoUrl': original.authorPhotoUrl,
        'title': original.title.trim(),
        'body': shortBody,
        'imageUrl': firstImage,
        'imageUrls': original.imagePaths,
        'videoUrls': original.videoPaths,
        if (comment != null) ...{
          'kind': 'comment',
          'commentId': comment.id,
          'commentAuthor': comment.author,
          'commentAuthorId': comment.authorId,
          'commentAuthorPhotoUrl': comment.authorPhotoUrl,
          'commentText': comment.text,
          'commentMediaUrl': comment.mediaUrl,
          'commentMediaType': comment.mediaType,
        },
      },
      'imageUrls': <String>[],
      'videoUrls': <String>[],
      'pollSlides': <Map<String, dynamic>>[],
      'polls': <Map<String, dynamic>>[],
      'tags': <String>[],
      'votes': 0,
      'upvotedBy': <String>[],
      'downvotedBy': <String>[],
      'commentsCount': 0,
      'version': 1,
    });
  }

  Future<_RepostDraft?> _askRepostDraft([
    _Post? previewPost,
    _Comment? comment,
  ]) async {
    final original = previewPost ?? widget.post;
    final nav = Navigator.of(context, rootNavigator: true);

    await Future<void>.delayed(const Duration(milliseconds: 120));
    if (!mounted) return null;

    return nav.push<_RepostDraft>(
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (_) => _RepostComposePage(
          original: original,
          comment: comment,
        ),
      ),
    );
  }

  Future<void> _blockAccount({bool closeViewer = false}) async {
    final user = FirebaseAuth.instance.currentUser;
    final pager = _FullscreenPostPagerState.current;
    final targetPost = pager?.currentPost ?? widget.post;
    final targetId = targetPost.authorId?.trim();

    if (user == null) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }
    if (targetId == null || targetId.isEmpty) return;
    if (targetId == user.uid) return;

    final name = _authorLabel(targetPost.author);
    final overlayContext = pager?.context ?? context;

    final confirmed = await showDialog<bool>(
      context: overlayContext,
      useRootNavigator: true,
      builder: (ctx) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
          title: const Text('حظر الحساب؟'),
          content: Text(
            'لن تظهر منشورات $name في فيدك بعد الآن. يمكنك إلغاء الحظر لاحقًا من الإعدادات.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFDC2626),
                foregroundColor: Colors.white,
              ),
              child: const Text('حظر'),
            ),
          ],
        ),
      ),
    );

    if (confirmed != true || !mounted) return;

    try {
      await blockAccount(
        targetId: targetId,
        targetName: name,
        targetPhotoUrl: targetPost.authorPhotoUrl,
      );
      if (!mounted) return;

      if (pager != null && pager.mounted) {
        pager._onAuthorBlocked(targetId);
        widget.onChanged();
        return;
      }

      widget.onHidden?.call();
      if (widget.isInsideComments) return;
      widget.onChanged();
      if (closeViewer && Navigator.of(context).canPop()) {
        Navigator.of(context).pop();
      }
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(content: Text('تم حظر $name')),
      );
    } catch (e) {
      debugPrint('Block account failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر حظر الحساب، حاول مجددًا')),
      );
    }
  }

  String _liveAuthorName(_Post post) {
    final live = AuthorProfiles.nameOf(post.authorId)?.trim();
    if (live != null && live.isNotEmpty) return _authorLabel(live);
    return _authorLabel(post.author);
  }

  Future<void> _confirmDeletePost() async {
    if (!_isOwner) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(22),
          ),
          title: const Text('حذف المنشور؟'),
          content: const Text(
            'سيتم حذف هذا المنشور نهائيًا ولا يمكن التراجع عن العملية.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('إلغاء'),
            ),
            FilledButton.icon(
              onPressed: () => Navigator.pop(context, true),
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFDC2626),
                foregroundColor: Colors.white,
              ),
              icon: const Icon(Icons.delete_outline_rounded, size: 18),
              label: const Text('حذف'),
            ),
          ],
        ),
      ),
    );

    if (confirmed != true) return;
    try {
      await widget.onDelete();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم حذف المنشور')),
      );
    } catch (error) {
      debugPrint('Community delete failed: $error');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حذف المنشور، حاول مجددًا')),
      );
    }
  }

  Future<void> _editPost() async {
    if (!_isOwner) return;
    if (widget.post.id == null || widget.post.id!.isEmpty) return;

    final nav = Navigator.of(context, rootNavigator: true);
    final post = widget.post;

    final result = await nav.push<List<PostItem>>(
      MaterialPageRoute(
        builder: (_) => CreatePostScreen(editingPost: post),
      ),
    );


    if (!mounted || result == null || result.isEmpty) return;

    String title = '';
    String body = '';
    final newImages = <Uint8List>[];
    final keepImageUrls = <String>[];
    final newVideos = <String>[];
    final keepVideoUrls = <String>[];
    List<PollData> pollDataList = [];
    List<Map<String, dynamic>> pollSlides = [];
    List<String> postTags = [];

    for (final item in result) {
      switch (item.type) {
        case PostItemType.text:
          final text = item.title.trim();
          if (text.isEmpty) break;
          if (title.isEmpty) {
            title = text;
          } else {
            body = body.isEmpty ? text : '$body\n$text';
          }
          break;
        case PostItemType.image:
          if (item.imageBytes != null) {
            newImages.add(item.imageBytes!);
          } else {
            final u = item.mediaPath?.trim() ?? '';
            if (u.startsWith('http')) keepImageUrls.add(u);
          }
          break;
        case PostItemType.video:
          final u = item.mediaPath?.trim() ?? '';
          if (u.startsWith('http')) {
            keepVideoUrls.add(u);
          } else if (u.isNotEmpty) {
            newVideos.add(u);
          }
          break;
        case PostItemType.poll:
          pollDataList = item.pollDataList ?? [];
          pollSlides = List<Map<String, dynamic>>.from(item.pollSlides ?? []);
          break;
        case PostItemType.tags:
          postTags = item.tags ?? [];
          break;
      }
    }

    final postId = widget.post.id!;

    try {
      final imageUrls = [...keepImageUrls];
      for (int i = 0; i < newImages.length; i++) {
        final ref = FirebaseStorage.instance
            .ref()
            .child('community_posts')
            .child(postId)
            .child('images')
            .child('edit_${DateTime.now().millisecondsSinceEpoch}_$i.jpg');
        await ref.putData(newImages[i], SettableMetadata(contentType: 'image/jpeg'));
        imageUrls.add(await ref.getDownloadURL());
      }

      final videoUrls = [...keepVideoUrls];
      for (int i = 0; i < newVideos.length; i++) {
        final file = File(newVideos[i]);
        if (!await file.exists()) continue;
        final ext = newVideos[i].split('.').last.toLowerCase();
        final ref = FirebaseStorage.instance
            .ref()
            .child('community_posts/$postId/videos/edit_${DateTime.now().millisecondsSinceEpoch}_$i.$ext');
        await ref.putFile(
          file,
          SettableMetadata(contentType: ext == 'mov' ? 'video/quicktime' : 'video/mp4'),
        );
        videoUrls.add(await ref.getDownloadURL());
      }

      final resolvedSlides = <Map<String, dynamic>>[];
      int pollImg = 0;
      int pollVid = 0;
      for (final s in pollSlides) {
        final type = s['type']?.toString();
        if (type == 'text') {
          final t = s['text']?.toString() ?? '';
          if (t.isNotEmpty) resolvedSlides.add({'type': 'text', 'text': t});
        } else if (type == 'poll') {
          resolvedSlides.add({'type': 'poll', 'pollIndex': s['pollIndex']});
        } else if (type == 'image') {
          final existing = s['url']?.toString() ?? '';
          if (existing.startsWith('http')) {
            resolvedSlides.add({'type': 'image', 'url': existing});
          } else if (s['imageBytes'] is Uint8List) {
            final ref = FirebaseStorage.instance.ref(
              'community_posts/$postId/images/poll_edit_${pollImg++}.jpg',
            );
            await ref.putData(
              s['imageBytes'] as Uint8List,
              SettableMetadata(contentType: 'image/jpeg'),
            );
            resolvedSlides.add({'type': 'image', 'url': await ref.getDownloadURL()});
          }
        } else if (type == 'video') {
          final existing = s['url']?.toString() ?? '';
          if (existing.startsWith('http')) {
            resolvedSlides.add({'type': 'video', 'url': existing});
          } else {
            final path = s['mediaPath']?.toString() ?? '';
            if (path.isNotEmpty) {
              final file = File(path);
              if (await file.exists()) {
                final ref = FirebaseStorage.instance.ref(
                  'community_posts/$postId/videos/poll_edit_${pollVid++}.mp4',
                );
                await ref.putFile(file, SettableMetadata(contentType: 'video/mp4'));
                resolvedSlides.add({'type': 'video', 'url': await ref.getDownloadURL()});
              }
            }
          }
        }
      }

      await FirebaseFirestore.instance
          .collection('community_posts')
          .doc(postId)
          .update({
        'title': title,
        'body': body,
        'tags': postTags,
        'imageUrls': imageUrls,
        'videoUrls': videoUrls,
        'polls': pollDataList.map(_pollToMap).toList(),
        'pollSlides': resolvedSlides,
        'isEdited': true,
        'editedAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
        if (widget.post.isRepost && widget.post.repostOf != null) ...{
          'isRepost': true,
          'repostOf': widget.post.repostOf,
        },
      });

      if (!mounted) return;

      setState(() {
        widget.post.title = title;
        widget.post.body = body;
        widget.post.tags
          ..clear()
          ..addAll(postTags);
        widget.post.isEdited = true;

        widget.post.imagePaths
          ..clear()
          ..addAll(imageUrls);
        widget.post.videoPaths
          ..clear()
          ..addAll(videoUrls);
        widget.post.pollDataList
          ..clear()
          ..addAll(pollDataList);
        widget.post.pollSlides
          ..clear()
          ..addAll(resolvedSlides);
      });

      widget.onChanged();
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تم تعديل المنشور')),
      );
    } catch (e, st) {
      debugPrint('Edit post failed: $e');
      debugPrintStack(stackTrace: st);
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر تعديل المنشور')),
      );
    }
  }

  PopupMenuItem<_PostMenuAction> _menuItem({
