  Widget _buildOptionsMenu() {
    return Container(
      width: 24,
      height: 30,

      child: PopupMenuButton<_PostMenuAction>(
        tooltip: 'خيارات المنشور',
        padding: EdgeInsets.zero,
        child: SizedBox(
          width: 34,
          height: 34,
          child: Icon(
            Icons.more_vert_rounded,
            color: AppTeal.main,
            size: 20,
          ),
        ),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(18),
        ),
        color: Theme.of(context).colorScheme.surface,
        position: PopupMenuPosition.under,
        onSelected: (action) {
          switch (action) {
            case _PostMenuAction.pin:
              _togglePinPost();
              break;
            case _PostMenuAction.pollResponses:
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => PollResponsesScreen(post: widget.post),
                ),
              );
              break;
            case _PostMenuAction.edit:
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) _editPost();
              });
              break;
            case _PostMenuAction.delete:
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) _confirmDeletePost();
              });
              break;
            case _PostMenuAction.share:
              _sharePost();
              break;
            case _PostMenuAction.save:
              _toggleSavePost();
              break;
            case _PostMenuAction.download:
              _downloadPostMedia();
              break;
            case _PostMenuAction.repost:
              Future<void>.delayed(const Duration(milliseconds: 150), () async {
                if (!mounted) return;
                final ok = await canRepostAuthor(widget.post.authorId ?? '');
                if (!ok) {
                  if (!mounted) return;
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('إعادة النشر غير مسموحة لهذا الحساب'),
                    ),
                  );
                  return;
                }
                await _repostPost();
              });
              break;
            case _PostMenuAction.report:
              _reportPost();
              break;
            case _PostMenuAction.block:
              Future<void>.delayed(const Duration(milliseconds: 150), () {
                if (mounted) _blockAccount();
              });
              break;
            case _PostMenuAction.copy:
              _copyPostText();
              break;
          }
        },
        itemBuilder: (context) => [
          if (widget.allowPin && _isOwner)
            _menuItem(
              value: _PostMenuAction.pin,
              icon: widget.isPinned
                  ? Icons.push_pin_rounded
                  : Icons.push_pin_outlined,
              label: widget.isPinned ? 'إلغاء التثبيت' : 'تثبيت المنشور',
              color: widget.isPinned ? AppTeal.main : null,
            ),
          if (_isOwner && widget.post.pollDataList.isNotEmpty)
            _menuItem(
              value: _PostMenuAction.pollResponses,
              label:'ردود الاستطلاع',
              icon: Icons.find_in_page,
              color: Theme.of(context).colorScheme.onSurface,
            ),
          if (_isOwner) ...[
            _menuItem(
              value: _PostMenuAction.edit,
              icon: Icons.edit_rounded,
              label: 'تعديل المنشور',
              color:  AppTeal.main,
            ),
            _menuItem(
              value: _PostMenuAction.delete,
              icon: Icons.delete_outline_rounded,
              label: 'حذف المنشور',
              color: const Color(0xFFDC2626),
            ),
            const PopupMenuDivider(height: 6),
          ],
          _menuItem(
            value: _PostMenuAction.save,
            icon: _isSaved ? Icons.bookmark_rounded : Icons.bookmark_border_rounded,
            label: _isSaved ? 'إلغاء الحفظ' : 'حفظ المنشور',
            color: _isSaved ? AppTeal.main : null,
          ),
          if (_downloadableItemsFor(widget.post).isNotEmpty)
            _menuItem(
              value: _PostMenuAction.download,
              icon: Icons.download_rounded,
              label: 'تحميل ',
            ),
          _menuItem(
            value: _PostMenuAction.repost,
            icon: Icons.repeat_rounded,
            label: 'إعادة نشر',
          ),
          _menuItem(
            value: _PostMenuAction.share,
            icon: Icons.ios_share_rounded,
            label: 'مشاركة',
          ),

          if (!_isOwner) ...[
            _menuItem(
              value: _PostMenuAction.report,
              icon: Icons.flag_outlined,
              label: 'تبليغ',
            ),
            _menuItem(
              value: _PostMenuAction.block,
              icon: Icons.block_rounded,
              label: 'حظر الحساب',
              color: const Color(0xFFDC2626),
            ),
          ],
          _menuItem(
            value: _PostMenuAction.copy,
            icon: Icons.copy_rounded,
            label: 'نسخ النص',
          ),
        ],
      ),
    );
  }
  Widget _buildFullscreenMenu() {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    PopupMenuItem<_PostMenuAction> item({
      required _PostMenuAction value,
      required IconData icon,
      required String label,
      Color? color,
    }) {
      final c = color ?? (isDark ? Colors.white : Colors.white);
      return PopupMenuItem<_PostMenuAction>(
        value: value,
        child: Row(
          children: [
            Icon(icon, size: 20, color: c),
            const SizedBox(width: 12),
            Text(
              label,
              style: TextStyle(
                color: c,
                fontWeight: FontWeight.w600,
                fontSize: 14,
              ),
            ),
          ],
        ),
      );
    }

    return Theme(
      data: Theme.of(context).copyWith(
        splashColor: Colors.white24,
        highlightColor: Colors.white10,
      ),
      child: PopupMenuButton<_PostMenuAction>(
        tooltip: 'خيارات المنشور',
        padding: EdgeInsets.zero,
        color: const Color(0xFF1A1A1B),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(14),
        ),
        icon: const Icon(
          Icons.more_vert_rounded,
          color: Colors.white,
          size: 22,
        ),
        onSelected: (action) {
          switch (action) {
            case _PostMenuAction.pin:
              _togglePinPost();
              break;
            case _PostMenuAction.pollResponses:
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => PollResponsesScreen(post: widget.post),
                ),
              );
              break;
            case _PostMenuAction.edit:
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) _editPost();
              });
              break;
            case _PostMenuAction.delete:
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) _confirmDeletePost();
              });
              break;
            case _PostMenuAction.share:
              _sharePost();
              break;
            case _PostMenuAction.save:
              _toggleSavePost();
              break;
            case _PostMenuAction.repost:
              Future<void>.delayed(const Duration(milliseconds: 150), () async {
                if (!mounted) return;
                final ok = await canRepostAuthor(widget.post.authorId ?? '');
                if (!ok) {
                  if (!mounted) return;
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('إعادة النشر غير مسموحة لهذا الحساب'),
                    ),
                  );
                  return;
                }
                await _repostPost();
              });
              break;
            case _PostMenuAction.report:
              _reportPost();
              break;
            case _PostMenuAction.download:
              _downloadPostMedia();
              break;
            case _PostMenuAction.block:
              Future<void>.delayed(const Duration(milliseconds: 150), () {
                if (mounted) _blockAccount(closeViewer: true);
              });
              break;
            case _PostMenuAction.copy:
              _copyPostText();
              break;
          }
        },
        itemBuilder: (context) => [
          if (widget.allowPin && _isOwner)
            _menuItem(
              value: _PostMenuAction.pin,
              icon: widget.isPinned
                  ? Icons.push_pin_rounded
                  : Icons.push_pin_outlined,
              label: widget.isPinned ? 'إلغاء التثبيت' : 'تثبيت المنشور',
              color: widget.isPinned ? AppTeal.main : null,
            ),
          if (_isOwner && widget.post.pollDataList.isNotEmpty)
            item(
              value: _PostMenuAction.pollResponses,
              icon: Icons.poll_outlined,
              label: 'ردود الاستطلاع',
              color: const Color(0xFF4FD1C5),
            ),
          if (_isOwner) ...[
            item(
              value: _PostMenuAction.edit,
              icon: Icons.edit_rounded,
              label: 'تعديل المنشور',
              color: const Color(0xFF4FD1C5),
            ),
            item(
              value: _PostMenuAction.delete,
