  const _DownloadPickResult(this.items);
  final List<_PostMediaItem> items;
}

class _DownloadMediaSheet extends StatefulWidget {
  const _DownloadMediaSheet({required this.items});
  final List<_PostMediaItem> items;

  @override
  State<_DownloadMediaSheet> createState() => _DownloadMediaSheetState();
}

class _DownloadMediaSheetState extends State<_DownloadMediaSheet> {
  late final Set<int> _selected = {for (var i = 0; i < widget.items.length; i++) i};

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              'اختر ما تريد تحميله',
              style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 12),
            GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              itemCount: widget.items.length,
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 3,
                mainAxisSpacing: 8,
                crossAxisSpacing: 8,
              ),
              itemBuilder: (context, i) {
                final item = widget.items[i];
                final on = _selected.contains(i);
                final isVideo = item.kind == _MediaKind.video;
                return GestureDetector(
                  onTap: () => setState(() {
                    if (on) {
                      _selected.remove(i);
                    } else {
                      _selected.add(i);
                    }
                  }),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(12),
                    child: Stack(
                      fit: StackFit.expand,
                      children: [
                        if (isVideo)
                          ColoredBox(
                            color: Colors.black87,
                            child: Icon(Icons.play_circle_outline_rounded,
                                color: Colors.white.withValues(alpha: 0.85), size: 36),
                          )
                        else
                          item.path.startsWith('http')
                              ? CachedNetworkImage(imageUrl: item.path, fit: BoxFit.cover)
                              : Image.file(File(item.path), fit: BoxFit.cover),
                        if (isVideo)
                          const Positioned(
                            left: 6,
                            bottom: 6,
                            child: Icon(Icons.videocam_rounded, color: Colors.white, size: 16),
                          ),
                        Positioned(
                          top: 6,
                          right: 6,
                          child: Icon(
                            on ? Icons.check_circle_rounded : Icons.circle_outlined,
                            color: on ? AppTeal.main : Colors.white,
                            size: 22,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
            const SizedBox(height: 14),
            SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: _selected.isEmpty
                    ? null
                    : () {
                  final picked = _selected
                      .map((i) => widget.items[i])
                      .toList();
                  Navigator.pop(context, _DownloadPickResult(picked));
                },
                style: FilledButton.styleFrom(backgroundColor: AppTeal.main),
                child: Text('تحميل (${_selected.length})'),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

