  final String title;
  final List<Map<String, dynamic>>? pollSlides;
  final String? mediaPath;

  final Uint8List? imageBytes;

  final List<String>? pollOptions;

  final List<PollData>? pollDataList;

  final List<String>? tags;

  PostItem({
    required this.type,
    required this.title,
    this.mediaPath,
    this.imageBytes,
    this.pollOptions,
    this.pollDataList,
    this.tags,
    this.pollSlides,
  });
}

