// ==================== MediaCarousel ====================
class _MediaCarousel extends StatefulWidget {
  const _MediaCarousel({
    required this.slides,
    this.autoHeightFlags, // NEW: true = ارتفاع مرن (صورة/فيديو خارج البول)، false/null = ثابت 250
  });

  final List<Widget> slides;
  final List<bool>? autoHeightFlags;

  static const double _fixedHeight = 250;

  @override
  State<_MediaCarousel> createState() => _MediaCarouselState();
}

class _MediaCarouselState extends State<_MediaCarousel> {
  int _current = 0;
  late final PageController _ctrl;

  // NEW: نخزّن الارتفاع المقاس لكل شريحة auto-height بعد قياسها فعليًا
  final Map<int, double> _measuredHeights = {};

  @override
  void initState() {
    super.initState();
    _ctrl = PageController();
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  bool _isAutoHeight(int index) {
    if (widget.autoHeightFlags == null) return false;
    if (index >= widget.autoHeightFlags!.length) return false;
    return widget.autoHeightFlags![index];
  }

  void _reportHeight(int index, double height) {
    if (_measuredHeights[index] == height) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      setState(() => _measuredHeights[index] = height);
    });
  }

  double get _currentHeight {
    if (!_isAutoHeight(_current)) return _MediaCarousel._fixedHeight;
    // NEW: أثناء انتظار القياس الأول، نبدأ بنفس الارتفاع الثابت لتفادي "قفزة" كبيرة
    return _measuredHeights[_current] ?? _MediaCarousel._fixedHeight;
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
          height: _currentHeight,
          child: PageView.builder(
            controller: _ctrl,
            allowImplicitScrolling: true,
            itemCount: widget.slides.length,
            onPageChanged: (i) => setState(() => _current = i),
            itemBuilder: (_, i) {
              final child = Padding(
                padding: const EdgeInsets.symmetric(horizontal: 2),
                child: widget.slides[i],
              );

              if (!_isAutoHeight(i)) {
                // FIX: بحالها كيف قبل — ارتفاع ثابت 250
                return child;
              }

              // NEW: نلف الشريحة بودجة قياس باش ناخدو ارتفاعها الطبيعي
              return _MeasuredSlide(
                onHeightMeasured: (h) => _reportHeight(i, h),
                child: child,
              );
            },
          ),
        ),
        if (widget.slides.length > 1) ...[
          const SizedBox(height: 8),
           // يجبر الصف على أخذ كامل العرض
             Center(
              child: _SlideDotsIndicator(
                count: widget.slides.length,
                currentIndex: _current,
                maxWidth: 200,
              ),
            ),

        ],
      ],
    );
  }
}

class _MeasureSize extends SingleChildRenderObjectWidget {
  const _MeasureSize({required this.onChange, required Widget child})
      : super(child: child);

  final ValueChanged<Size> onChange;

  @override
  _MeasureSizeRenderObject createRenderObject(BuildContext context) {
    return _MeasureSizeRenderObject(onChange);
  }

  @override
  void updateRenderObject(
      BuildContext context, _MeasureSizeRenderObject renderObject) {
    renderObject.onChange = onChange;
  }
}

class _MeasureSizeRenderObject extends RenderProxyBox {
  _MeasureSizeRenderObject(this.onChange);

  ValueChanged<Size> onChange;
  Size? _oldSize;

  @override
  void performLayout() {
    super.performLayout();
    final newSize = child?.size;
    if (newSize != null && newSize != _oldSize) {
      _oldSize = newSize;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        onChange(newSize);
      });
    }
  }
}

class _MeasuredSlide extends StatelessWidget {
  const _MeasuredSlide({required this.child, required this.onHeightMeasured});

  final Widget child;
  final ValueChanged<double> onHeightMeasured;

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      physics: const NeverScrollableScrollPhysics(),
      child: _MeasureSize(
        onChange: (size) => onHeightMeasured(size.height),
        child: child,
      ),
    );
  }
}

// NEW: فيديو خارج البول — بعرض كامل، الارتفاع محسوب من النسبة الحقيقية
// ديال الفيديو (بحال الصور)، بدل ارتفاع ثابت مقصوص.
class _FeedVideoCoordinator {
  _FeedVideoCoordinator._();
  static final instance = _FeedVideoCoordinator._();

  void Function()? _pauseCurrent;

  void claim(void Function() pause) {
    if (_pauseCurrent != null && _pauseCurrent != pause) {
      _pauseCurrent!();
    }
    _pauseCurrent = pause;
  }

  void release(void Function() pause) {
    if (_pauseCurrent == pause) _pauseCurrent = null;
  }
}
class _AutoSizeVideo extends StatefulWidget {
  const _AutoSizeVideo({
    required this.path,
    this.maxHeight = 480,
    this.authorPhotoUrl,
    this.authorName,
    this.postTitle,
    this.postBody,
    this.menuButton,
    this.votes,
    this.isLiked,
    this.isDisliked,
    this.commentsCount,
    this.tagsCount,
    this.onLike,
    this.onDislike,
    this.onComment,
    this.onTags,
    this.onOpenFullscreen,
  });

  final String path;
  final double maxHeight;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody;
  final Widget? menuButton;

  final int? votes;
  final bool? isLiked;
  final bool? isDisliked;
  final int? commentsCount;
  final int? tagsCount;
  final VoidCallback? onLike;
  final VoidCallback? onDislike;
  final Future<int?> Function()? onComment;
  final VoidCallback? onTags;
  final VoidCallback? onOpenFullscreen;

  @override
  State<_AutoSizeVideo> createState() => _AutoSizeVideoState();
}

class _AutoSizeVideoState extends State<_AutoSizeVideo> {
  VideoPlayerController? _controller;
  bool _loading = false; // كان true — اتركه false حتى تبدأ التهيئة
  String? _error;
  bool _finished = false;
  bool _muted = true; // يبدأ مكتومًا
  bool _initialized = false;
  bool _initializing = false;
  late final Key _visibilityKey =
  ValueKey('autosize_video_${widget.path}');
  Timer? _disposeTimer;
  static const double _visibilityThreshold = 0.75;

  @override
  void initState() {
    super.initState();

  }

  Future<void> _initializeVideo() async {
    if (_initialized || _initializing) return;
    _initializing = true;

    final path = widget.path.trim();
    if (path.isEmpty) {
      _initializing = false;
      if (mounted) {
        setState(() {
          _loading = false;
          _error = 'رابط الفيديو فارغ';
        });
      }
      return;
    }

    await _VideoInitGate.instance.acquire();
    if (!mounted) {
      _VideoInitGate.instance.release();
      _initializing = false;
      return;
    }

    try {
      final isNetwork =
          path.startsWith('http://') || path.startsWith('https://');

      VideoPlayerController controller;

      if (isNetwork) {
        // 1) حمّل للقرص (أو من الكاش) ثم شغّل من File
        final file = await DefaultCacheManager().getSingleFile(path);
        if (!mounted) {
          _VideoInitGate.instance.release();
          _initializing = false;
          return;
        }
        controller = VideoPlayerController.file(
          file,
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else {
        controller = VideoPlayerController.file(
          File(path),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      }

      await controller.initialize();
      await controller.setLooping(false);
      await controller.setVolume(0); // مكتوم في الخلاصة

      if (!mounted) {
        await controller.dispose();
        return;
      }

      controller.addListener(_onControllerUpdate);

      setState(() {
        _controller = controller;
        _loading = false;
        _initialized = true;
        _error = null;
      });
    } catch (e, st) {
      debugPrint('AutoSizeVideo init failed: $e');
      debugPrintStack(stackTrace: st);
      if (mounted) {
        setState(() {
          _loading = false;
          _error = 'تعذر تحميل الفيديو';
        });
      }
    } finally {
      _VideoInitGate.instance.release();
      _initializing = false;
    }
  }

  void _onControllerUpdate() {
    final c = _controller;
    if (c == null || !c.value.isInitialized || !mounted || _finished) return;

    final d = c.value.duration;
    final p = c.value.position;
    if (d > Duration.zero &&
        p >= d - const Duration(milliseconds: 300)) {
      c.pause();
      setState(() => _finished = true);
    }
  }

  void _handleVisibilityChanged(VisibilityInfo info) {
    final visible = info.visibleFraction >= _visibilityThreshold;

    if (visible) {
      _disposeTimer?.cancel(); // ← هنا

      if (!_initialized && !_initializing) {
        _initializeVideo();
        return;
      }

      final c = _controller;
      if (c == null || !c.value.isInitialized) return;

      if (_finished) {
        c.seekTo(Duration.zero);
        setState(() => _finished = false);
      }

      // نفس المرجع دائماً → يوقف الفيديو السابق ثم يسجّل هذا
      _FeedVideoCoordinator.instance.claim(_pauseSelf);

      c.setVolume(_muted ? 0 : 1);
      if (!c.value.isPlaying) c.play();
    } else {
      _pauseSelf();
      _FeedVideoCoordinator.instance.release(_pauseSelf);
      _disposeTimer?.cancel();
      _disposeTimer = Timer(const Duration(seconds: 8), () {
        if (!mounted) return;
        final c = _controller;
        if (c == null) return;
        c.removeListener(_onControllerUpdate);
        c.dispose();
        _controller = null;
        _initialized = false;
        _initializing = false;
        if (mounted) setState(() {});
      });
    }
  }

  void _toggleMute() {
    final c = _controller;
    if (c == null) return;

    setState(() {
      _muted = !_muted;
      c.setVolume(_muted ? 0 : 1);
    });
  }

  Future<void> _openFullscreen() async {
    final c = _controller;

    if (c == null) return;

    await c.pause();
    await c.setVolume(0);
    if (!mounted) return;
    if (widget.onOpenFullscreen != null) {
      widget.onOpenFullscreen!();
      // بعد الرجوع من العارض الموحّد
      if (!mounted) return;
      final isCurrentlyMuted = c.value.volume == 0;
      await c.seekTo(Duration.zero);
      await c.pause();
      await c.setVolume(0);
      setState(() {
        _finished = true;
        _muted = isCurrentlyMuted;
      });
      return;
    }
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => FullscreenVideoViewer(
          controller: c,
          authorName: widget.authorName,
          authorPhotoUrl: widget.authorPhotoUrl,
          postTitle: widget.postTitle,
          postBody: widget.postBody,
          menuButton: widget.menuButton,
          votes: widget.votes,
          isLiked: widget.isLiked ?? false,
          isDisliked: widget.isDisliked ?? false,
          commentsCount: widget.commentsCount,
          tagsCount: widget.tagsCount,
          onLike: widget.onLike,
          onDislike: widget.onDislike,
          onComment:widget.onComment,
          onTags: widget.onTags,

        ),
      ),
    );

    if (!mounted) return;

    // مزامنة حالة الكتم بعد الرجوع
    final isCurrentlyMuted = c.value.volume == 0;

    await c.seekTo(Duration.zero);
    await c.pause();
    await c.setVolume(0);

    setState(() {
      _finished = true;
      _muted = isCurrentlyMuted; // ← المهم
    });
  }

  void _pauseSelf() {
    final c = _controller;
    if (c == null) return;
    if (c.value.isPlaying) c.pause();
    c.setVolume(0);
  }

  @override
  void dispose() {
    _pauseSelf();
    _disposeTimer?.cancel(); // ← هنا
    _FeedVideoCoordinator.instance.release(_pauseSelf);
    final c = _controller;
    if (c != null) {
      c.removeListener(_onControllerUpdate);
      c.dispose();
    }
    _controller = null;
    super.dispose();
  }

  Widget _placeholderBox({required bool isError}) {
    return Container(
      height: 220,
      color: Colors.black,
      alignment: Alignment.center,
      child: isError
          ? Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(Icons.video_library_outlined,
              color: Colors.white70, size: 42),
          const SizedBox(height: 8),
          Text(
            _error ?? 'تعذر تحميل الفيديو',
            style: const TextStyle(color: Colors.white70, fontSize: 12),
          ),
        ],
      )
          : const CircularProgressIndicator(color: Colors.white),
    );
  }

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(18),
      child: VisibilityDetector(
        key: _visibilityKey,
        onVisibilityChanged: _handleVisibilityChanged,
        child: _buildBody(),
      ),
    );
  }

  Widget _buildBody() {
    if (_loading || _initializing || (!_initialized && _error == null)) {
      return _placeholderBox(isError: false);
    }
    if (_error != null || _controller == null) {
      return _placeholderBox(isError: true);
    }

    final controller = _controller!;
    final rawRatio = controller.value.aspectRatio;
    final aspectRatio =
    (rawRatio.isFinite && rawRatio > 0) ? rawRatio : 16 / 9;

    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth;
        final naturalHeight = width / aspectRatio;
        final displayHeight =
        naturalHeight > widget.maxHeight ? widget.maxHeight : naturalHeight;
        final needsCover = naturalHeight > widget.maxHeight;

        return SizedBox(
          width: width,
          height: displayHeight,
          child: Container(
            color: Colors.black,
            child: Stack(
              alignment: Alignment.center,
              children: [
                needsCover
                    ? FittedBox(
                  fit: BoxFit.cover,
                  child: SizedBox(
                    width: controller.value.size.width,
                    height: controller.value.size.height,
                    child: VideoPlayer(controller),
                  ),
                )
                    : SizedBox.expand(child: VideoPlayer(controller)),

                // الضغط لفتح ملء الشاشة — تحت الأزرار
                Positioned.fill(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: _openFullscreen,
                  ),
                ),

                // كتم — فوق طبقة الفتح
                Positioned(
                  top: 10,
                  right: 10,
                  child: Material(
                    color: Colors.transparent,
                    child: InkWell(
                      onTap: _toggleMute,
                      customBorder: const CircleBorder(),
                      child: Container(
                        padding: const EdgeInsets.all(7),
                        decoration: BoxDecoration(
                          color: Colors.black.withValues(alpha: 0.55),
                          shape: BoxShape.circle,
                        ),
                        child: Icon(
                          _muted
                              ? Icons.volume_off_rounded
                              : Icons.volume_up_rounded,
                          color: Colors.white,
                          size: 18,
                        ),
                      ),
                    ),
                  ),
                ),

                if (_finished)
                  Positioned.fill(
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: _openFullscreen,
                      child: Container(
                        color: Colors.black.withValues(alpha: 0.55),
                        alignment: Alignment.center,
                        child: const Icon(Icons.replay_rounded,
                            color: Colors.white, size: 34),
                      ),
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }
}
class _PickedVideoTile extends StatefulWidget {
  const _PickedVideoTile({
    super.key,
    required this.file,
    required this.onDelete,
  });

  final File file;
  final VoidCallback onDelete;

  @override
  State<_PickedVideoTile> createState() => _PickedVideoTileState();
}

class _PickedVideoTileState extends State<_PickedVideoTile> {
  VideoPlayerController? _controller;
  bool _loading = true;
  String? _error;

  void _onUpdate() {
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _init() async {
    try {
      final controller = VideoPlayerController.file(widget.file);
      await controller.initialize();
      await controller.setLooping(false);
      await controller.setVolume(0);
      await controller.pause();

      if (!mounted) {
        await controller.dispose();
        return;
      }

      controller.addListener(_onUpdate);

      setState(() {
        _controller = controller;
        _loading = false;
      });
    } catch (e) {
      debugPrint('Picked video init failed: $e');
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = 'تعذر تحميل الفيديو';
      });
    }
  }

  void _togglePlay() {
    final c = _controller;
    if (c == null || !c.value.isInitialized) return;

    if (c.value.isPlaying) {
      c.pause();
    } else {
      if (c.value.position >=
          c.value.duration - const Duration(milliseconds: 300)) {
        c.seekTo(Duration.zero);
      }
      c.play();
    }
  }

  @override
  void dispose() {
    _controller?.removeListener(_onUpdate);
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;

    if (_loading) {
      return const Center(child: CircularProgressIndicator());
    }

    if (_error != null || controller == null) {
      return Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.error_outline, color: Colors.white70, size: 36),
            const SizedBox(height: 8),
            Text(
              _error ?? 'خطأ',
              style: const TextStyle(color: Colors.white70, fontSize: 12),
            ),
          ],
        ),
      );
    }

    final isPlaying = controller.value.isPlaying;

    return Stack(
      fit: StackFit.expand,
      children: [
        FittedBox(
          fit: BoxFit.cover,
          child: SizedBox(
            width: controller.value.size.width,
            height: controller.value.size.height,
            child: VideoPlayer(controller),
          ),
        ),

        // زر التشغيل / الإيقاف
        Center(
          child: GestureDetector(
            onTap: _togglePlay,
            child: Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: Colors.black.withValues(alpha: 0.45),
                shape: BoxShape.circle,
              ),
              child: Icon(
                isPlaying ? Icons.pause_rounded : Icons.play_arrow_rounded,
                color: Colors.white,
                size: 36,
              ),
            ),
          ),
        ),

        // زر الحذف
        Positioned(
          top: 10,
          right: 10,
          child: GestureDetector(
            onTap: widget.onDelete,
            child: Container(
              padding: const EdgeInsets.all(4),
              decoration: const BoxDecoration(
                color: Colors.black54,
                shape: BoxShape.circle,
              ),
              child: const Icon(Icons.close, size: 16, color: Colors.white),
            ),
          ),
        ),

        // شريط التقدم
        Positioned(
          bottom: 0,
          left: 0,
          right: 0,
          child: VideoProgressIndicator(
            controller,
            allowScrubbing: true,
            colors: const VideoProgressColors(
              playedColor: Colors.redAccent,
              bufferedColor: Colors.white38,
              backgroundColor: Colors.white24,
            ),
          ),
        ),
      ],
    );
  }
}
// ==================== VideoSlideWidget ====================
class _VideoSlideWidget extends StatefulWidget {
  final String videoPath;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody;
  final Widget? menuButton;

  const _VideoSlideWidget({
    required this.videoPath,
    this.authorName,
    this.authorPhotoUrl,
    this.postTitle,
    this.postBody,
    this.menuButton,
  });

  @override
  State<_VideoSlideWidget> createState() => _VideoSlideWidgetState();
}

class _VideoSlideWidgetState extends State<_VideoSlideWidget> {
  VideoPlayerController? _controller;
  bool _loading = true;
  String? _error;
  bool _finished = false;
  bool _hasStartedLoading = false;
  bool _muted = true; // يبدأ مكتومًا

  late final Key _visibilityKey =
  ValueKey('feed_video_${widget.videoPath}');

  static const double _visibilityThreshold = 0.5;

  @override
  void initState() {
    super.initState();

  }

  Future<void> _initializeVideo() async {
    if (_hasStartedLoading) return;
    _hasStartedLoading = true;

    final path = widget.videoPath.trim();
    if (path.isEmpty) {
      setState(() {
        _loading = false;
        _error = 'رابط الفيديو فارغ';
      });
      return;
    }

    await _VideoInitGate.instance.acquire();
    if (!mounted) {
      _VideoInitGate.instance.release();
      return;
    }

    try {
      final isNetwork =
          path.startsWith('http://') || path.startsWith('https://');

      late final VideoPlayerController controller;

      if (isNetwork) {
        final file = await DefaultCacheManager().getSingleFile(path);
        if (!mounted) {
          _VideoInitGate.instance.release();
          return;
        }
        controller = VideoPlayerController.file(
          file,
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else {
        controller = VideoPlayerController.file(
          File(path),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      }

      await controller.initialize();
      await controller.setLooping(false);
      await controller.setVolume(0);

      if (!mounted) {
        await controller.dispose();
        return;
      }

      controller.addListener(_onControllerUpdate);

      setState(() {
        _controller = controller;
        _loading = false;
        _error = null;
      });
    } catch (e, st) {
      debugPrint('VIDEO LOAD ERROR: $path\n$e');
      debugPrintStack(stackTrace: st);
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = 'تعذر تحميل الفيديو';
      });
    } finally {
      _VideoInitGate.instance.release();
    }
  }

  void _onControllerUpdate() {
    final c = _controller;
    if (c == null || !c.value.isInitialized || !mounted || _finished) return;

    final d = c.value.duration;
    final p = c.value.position;
    if (d > Duration.zero &&
        p >= d - const Duration(milliseconds: 300)) {
      c.pause();
      setState(() => _finished = true);
    }
  }

  void _handleVisibilityChanged(VisibilityInfo info) {
    final visible = info.visibleFraction >= _visibilityThreshold;
    if (visible && !_hasStartedLoading) {
      _initializeVideo();
      return; // الكونترولر مازال مكاينش، غادي نستنى الفريم الجاي
    }
    final c = _controller;
    if (c == null || !c.value.isInitialized) return;



    if (visible) {
      // عند الظهور مرة أخرى → نعيد الحالة الطبيعية
      if (_finished) {
        c.seekTo(Duration.zero);
        setState(() => _finished = false);
      }
      if (!c.value.isPlaying) {
        c.play();
      }
    } else {
      // عند الاختفاء → نوقف الفيديو
      if (c.value.isPlaying) {
        c.pause();
      }
    }
  }

  void _toggleMute() {
    final c = _controller;
    if (c == null) return;

    setState(() {
      _muted = !_muted;
      c.setVolume(_muted ? 0 : 1);
    });
  }

  Future<void> _openFullscreen() async {
    final c = _controller;
    if (c == null) return;

    await c.pause();
    await c.setVolume(0);
    if (!mounted) return;

    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => SimpleFullscreenVideoViewer(
          controller: c,
        ),
      ),
    );

    if (!mounted) return;

    // بعد الرجوع: نزامن حالة الكتم مع الـ controller
    final isCurrentlyMuted = c.value.volume == 0;

    await c.seekTo(Duration.zero);
    await c.pause();
    await c.setVolume(0);

    setState(() {
      _finished = true;
      _muted = isCurrentlyMuted; // ← المهم
    });
  }
  @override
  void dispose() {
    _controller?.removeListener(_onControllerUpdate);
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // FIX: VisibilityDetector دابا كيلف حتى حالة "قبل التحميل" (_loading==true بلا _hasStartedLoading)
    // باش يقدر يكتشف الظهور ويبدا التحميل بمجرد ما يوصل للشاشة
    return ClipRRect(
      borderRadius: BorderRadius.circular(12),
      child: VisibilityDetector(
        key: _visibilityKey,
        onVisibilityChanged: _handleVisibilityChanged,
        child: Container(
          color: Colors.black,
          width: double.infinity,
          height: 250,
          child: _loading
              ? const Center(child: CircularProgressIndicator(color: Colors.white))
              : _error != null || _controller == null
              ? Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Icon(Icons.video_library_outlined, color: Colors.white70, size: 42),
                const SizedBox(height: 8),
                Text(_error ?? 'تعذر تحميل الفيديو',
                    style: const TextStyle(color: Colors.white70, fontSize: 12)),
              ],
            ),
          )
              : Stack(
            fit: StackFit.expand,
            children: [
              FittedBox(
                fit: BoxFit.cover,
                child: SizedBox(
                  width: _controller!.value.size.width,
                  height: _controller!.value.size.height,
                  child: VideoPlayer(_controller!),
                ),
              ),
              Positioned.fill(
                child: GestureDetector(behavior: HitTestBehavior.opaque, onTap: _openFullscreen),
              ),
              Positioned(
                top: 10,
                right: 10,
                child: GestureDetector(
                  onTap: _toggleMute,
                  child: Container(
                    padding: const EdgeInsets.all(7),
                    decoration: BoxDecoration(color: Colors.black.withValues(alpha: 0.55), shape: BoxShape.circle),
                    child: Icon(_muted ? Icons.volume_off_rounded : Icons.volume_up_rounded, color: Colors.white, size: 18),
                  ),
                ),
              ),
              if (_finished)
                Positioned.fill(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: _openFullscreen,
                    child: Container(
                      color: Colors.black45,
                      alignment: Alignment.center,
                      child: Container(
                        width: 64,
                        height: 64,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: Colors.white.withValues(alpha: 0.18),
                          border: Border.all(color: Colors.white.withValues(alpha: 0.6), width: 1.5),
                          boxShadow: [
                            BoxShadow(color: Colors.black.withValues(alpha: 0.35), blurRadius: 16, offset: const Offset(0, 6)),
                          ],
                        ),
                        child: const Icon(Icons.replay_rounded, color: Colors.white, size: 32),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class SimpleFullscreenVideoViewer extends StatefulWidget {
  final VideoPlayerController controller;

  const SimpleFullscreenVideoViewer({
    super.key,
    required this.controller,
  });

  @override
  State<SimpleFullscreenVideoViewer> createState() =>
      _SimpleFullscreenVideoViewerState();
}

class _SimpleFullscreenVideoViewerState
    extends State<SimpleFullscreenVideoViewer> {
  bool _controlsVisible = true;
  double _dragOffset = 0;
  final TransformationController _zoomController = TransformationController();
  bool _muted = false;

  Offset? _dragStart;
  bool _isDragGesture = false;
  int _activePointers = 0;
  bool _isPinching = false;
  double _currentScale = 1.0;

  @override
  void initState() {
    super.initState();
    final c = widget.controller;
    c.setLooping(false);
    c.addListener(_tick);

    // نحافظ على حالة الصوت الحالية أو نبدأ غير مكتوم
    _muted = c.value.volume == 0;

    _zoomController.addListener(() {
      setState(() => _currentScale = _zoomController.value.getMaxScaleOnAxis());
    });

    WidgetsBinding.instance.addPostFrameCallback((_) async {
      await c.seekTo(Duration.zero);
      await c.play();
      if (mounted) setState(() {});
    });
  }

  void _tick() {
    if (mounted) setState(() {});
  }

  void _resetZoom() {
    _zoomController.value = Matrix4.identity();
    if (mounted) setState(() => _currentScale = 1.0);
  }

  bool get _isZoomed => (_currentScale - 1.0).abs() > 0.05;

  bool get _isEnded {
    final c = widget.controller;
    return c.value.isInitialized &&
        c.value.duration > Duration.zero &&
        c.value.position >= c.value.duration - const Duration(milliseconds: 300);
  }

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
  }

  void _togglePlay() {
    final c = widget.controller;
    if (_isEnded) {
      c.seekTo(Duration.zero);
      c.play();
    } else {
      c.value.isPlaying ? c.pause() : c.play();
    }
    setState(() {});
  }

  void _toggleMute() {
    final c = widget.controller;
    setState(() {
      _muted = !_muted;
      c.setVolume(_muted ? 0 : 1);
    });
  }

  void _onPointerDown(PointerDownEvent event) {
    _activePointers++;
    if (_activePointers > 1) {
      _dragStart = null;
      setState(() => _isPinching = true);
      if (_isDragGesture) {
        _isDragGesture = false;
        setState(() => _dragOffset = 0);
      }
      return;
    }
    _dragStart = event.position;
    _isDragGesture = false;
  }

  void _onPointerMove(PointerMoveEvent event) {
    if (_activePointers != 1 || _dragStart == null || _isZoomed) return;

    final delta = event.position - _dragStart!;

    if (!_isDragGesture) {
      if (delta.dy.abs() > 8 && delta.dy.abs() > delta.dx.abs() * 1.5) {
        _isDragGesture = true;
      } else if (delta.dx.abs() > 8) {
        _dragStart = null;
        return;
      }
    }

    if (_isDragGesture) {
      setState(() => _dragOffset = delta.dy);
    }
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);

    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }

    if (_isDragGesture && _activePointers == 0) {
      if (_dragOffset.abs() > 120) {
        Navigator.of(context).pop();
      } else {
        setState(() => _dragOffset = 0);
      }
      _isDragGesture = false;
    }
    _dragStart = null;
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }
    _dragStart = null;
    _isDragGesture = false;
    if (_dragOffset != 0) setState(() => _dragOffset = 0);
  }

  Future<void> _saveVideo() async {
    try {
      // منطق الحفظ عندك
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم الحفظ للمعرض')),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حفظ الفيديو')),
      );
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_tick);
    _zoomController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final c = widget.controller;
    final ratio = c.value.isInitialized && c.value.aspectRatio > 0
        ? c.value.aspectRatio
        : 16 / 9;
    final bgOpacity = (1 - (_dragOffset.abs() / 350)).clamp(0.35, 1.0);

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: Listener(
        onPointerDown: _onPointerDown,
        onPointerMove: _onPointerMove,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
          onTap: _toggleControls,
          behavior: HitTestBehavior.translucent,
          child: Container(
            color: Colors.black.withValues(alpha: bgOpacity),
            child: Stack(
              children: [
                // ===== الفيديو =====
                Transform.translate(
                  offset: Offset(0, _dragOffset),
                  child: Center(
                    child: AspectRatio(
                      aspectRatio: ratio,
                      child: InteractiveViewer(
                        transformationController: _zoomController,
                        maxScale: 8.0,
                        minScale: 1.0,
                        panEnabled: false,
                        scaleEnabled: true,
                        boundaryMargin: const EdgeInsets.all(double.infinity),
                        onInteractionEnd: (_) {
                          if (_activePointers < 2) {
                            _resetZoom();
                          }
                        },
                        child: VideoPlayer(c),
                      ),
                    ),
                  ),
                ),

                // ===== الشريط العلوي (إغلاق + تحميل) =====
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [
                            Colors.black.withValues(alpha: 0.55),
                            Colors.transparent,
                          ],
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4),
                          child: Row(
                            children: [
                              _ViewerIconButton(
                                icon: Icons.close_rounded,
                                onTap: () => Navigator.of(context).pop(),
                              ),
                              const Spacer(),
                              _ViewerIconButton(
                                icon: Icons.download_rounded,
                                onTap: _saveVideo,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),

                // ===== الشريط السفلي =====
                Positioned(
                  left: 0,
                  right: 0,
                  bottom: 0,
                  child: AnimatedOpacity(
                    opacity: _controlsVisible ? 1 : 0,
                    duration: const Duration(milliseconds: 200),
                    child: IgnorePointer(
                      ignoring: !_controlsVisible,
                      child: Container(
                        width: double.infinity,
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.bottomCenter,
                            end: Alignment.topCenter,
                            colors: [
                              Colors.black.withValues(alpha: 0.90),
                              Colors.black.withValues(alpha: 0.45),
                              Colors.transparent,
                            ],
                            stops: const [0.0, 0.55, 1.0],
                          ),
                        ),
                        child: SafeArea(
                          top: false,
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(12, 24, 12, 10),
                            child: _SimpleVideoControls(
                              controller: widget.controller,
                              muted: _muted,
                              onToggleMute: _toggleMute,
                              onTogglePlay: _togglePlay,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
class _SimpleVideoControls extends StatelessWidget {
  const _SimpleVideoControls({
    required this.controller,
    required this.muted,
    required this.onToggleMute,
    required this.onTogglePlay,
  });

  final VideoPlayerController controller;
  final bool muted;
  final VoidCallback onToggleMute;
  final VoidCallback onTogglePlay;

  String _format(Duration d) {
    final m = d.inMinutes.remainder(60).toString().padLeft(1, '0');
    final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<VideoPlayerValue>(
      valueListenable: controller,
      builder: (context, value, _) {
        final duration = value.duration;
        final position = value.position;
        final ratio = duration.inMilliseconds == 0
            ? 0.0
            : (position.inMilliseconds / duration.inMilliseconds).clamp(0.0, 1.0);

        final isEnded = duration > Duration.zero &&
            position >= duration - const Duration(milliseconds: 300);

        return Row(
          children: [
            // زر تشغيل / إيقاف
            GestureDetector(
              onTap: onTogglePlay,
              child: Container(
                padding: const EdgeInsets.all(6),
                child: Icon(
                  isEnded
                      ? Icons.replay_rounded
                      : (value.isPlaying
                      ? Icons.pause_rounded
                      : Icons.play_arrow_rounded),
                  color: Colors.white,
                  size: 26,
                ),
              ),
            ),

            const SizedBox(width: 6),

            // الوقت الحالي
            Text(
              _format(position),
              style: const TextStyle(
                color: Colors.white,
                fontSize: 12,
                fontWeight: FontWeight.w600,
              ),
            ),

            const SizedBox(width: 8),

            // شريط التقدم
            Expanded(
              child: SliderTheme(
                data: SliderTheme.of(context).copyWith(
                  trackHeight: 3,
                  thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),
                  overlayShape: const RoundSliderOverlayShape(overlayRadius: 12),
                  activeTrackColor: Colors.white,
                  inactiveTrackColor: Colors.white24,
                  thumbColor: Colors.white,
                ),
                child: Slider(
                  value: ratio,
                  onChanged: (v) {
                    final target = duration * v;
                    controller.seekTo(target);
                  },
                ),
              ),
            ),

            const SizedBox(width: 8),

            // الوقت الكلي
            Text(
              _format(duration),
              style: const TextStyle(
                color: Colors.white70,
                fontSize: 12,
                fontWeight: FontWeight.w600,
              ),
            ),

            const SizedBox(width: 4),

            // زر كتم الصوت
            GestureDetector(
              onTap: onToggleMute,
              child: Container(
                padding: const EdgeInsets.all(6),
                child: Icon(
                  muted ? Icons.volume_off_rounded : Icons.volume_up_rounded,
                  color: Colors.white,
                  size: 22,
                ),
              ),
            ),
          ],
        );
      },
    );
  }
}
//==============================================================
class PostImagesSlider extends StatefulWidget {
  final List<String> images;
  const PostImagesSlider({super.key, required this.images});

  @override
  State<PostImagesSlider> createState() => _PostImagesSliderState();
}

class _PostImagesSliderState extends State<PostImagesSlider> {
  int _currentIndex = 0;
  late PageController _pageController;

  @override
  void initState() {
    super.initState();
    _pageController = PageController();
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  // ✅ يدعم assets وfile paths وnetwork
  Widget _buildImage(String path) {
    if (path.startsWith('assets/')) {
      return Image.asset(path, fit: BoxFit.cover, width: double.infinity);
    }
    if (path.startsWith('http://') || path.startsWith('https://')) {
      return Image.network(
        path,
        fit: BoxFit.cover,
        width: double.infinity,
        errorBuilder: (_, __, ___) => Container(
          color: Colors.grey[300],
          child: const Center(child: Icon(Icons.broken_image)),
        ),
      );
    }
    final file = File(path);
    if (file.existsSync()) {
      return Image.file(file, fit: BoxFit.cover, width: double.infinity);
    }
    return Container(
      color: Colors.grey[300],
      child: const Center(child: Icon(Icons.broken_image)),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        SizedBox(
          height: 300,
          child: PageView.builder(
            controller: _pageController,
            itemCount: widget.images.length,
            onPageChanged: (i) => setState(() => _currentIndex = i),
            itemBuilder: (context, index) {
              final path = widget.images[index];
              return GestureDetector(
                onTap: () {
                  // عارض بسيط مخصص لصور البول (إغلاق + تحميل فقط)
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => SimpleFullscreenImageViewer(
                        images: widget.images,
                        initialIndex: index,
                      ),
                    ),
                  );
                },
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 4),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(12),
                    child: _buildImage(path),
                  ),
                ),
              );
            },
          ),
        ),
        const SizedBox(height: 8),
        if (widget.images.length > 1)
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: List.generate(widget.images.length, (index) {
              return AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                margin: const EdgeInsets.symmetric(horizontal: 2),
                width: _currentIndex == index ? 14 : 8,
                height: _currentIndex == index ? 6 : 4,
                decoration: BoxDecoration(
                  color: _currentIndex == index
                      ? AppTeal.main
                      : Colors.grey[400],
                  borderRadius: BorderRadius.circular(4),
                ),
              );
            }),
          ),
      ],
    );
  }
}

class SimpleFullscreenImageViewer extends StatefulWidget {
  final List<String> images;
  final int initialIndex;

  const SimpleFullscreenImageViewer({
    super.key,
    required this.images,
    this.initialIndex = 0,
  });

  @override
  State<SimpleFullscreenImageViewer> createState() =>
      _SimpleFullscreenImageViewerState();
}

class _SimpleFullscreenImageViewerState
    extends State<SimpleFullscreenImageViewer> {
  late final PageController _pageController;
  late int currentIndex;
  bool _controlsVisible = true;
  double _dragOffset = 0;

  final Map<int, TransformationController> _zoomControllers = {};
  final Map<int, double> _currentScale = {};

  Offset? _dragStart;
  bool _isDragGesture = false;
  int _activePointers = 0;
  bool _isPinching = false;

  @override
  void initState() {
    super.initState();
    currentIndex = widget.initialIndex;
    _pageController = PageController(initialPage: currentIndex);
  }

  @override
  void dispose() {
    _pageController.dispose();
    for (final c in _zoomControllers.values) {
      c.dispose();
    }
    super.dispose();
  }

  TransformationController _zoomFor(int index) {
    return _zoomControllers.putIfAbsent(index, () {
      final c = TransformationController();
      c.addListener(() {
        if (!mounted) return;
        setState(() {
          _currentScale[index] = c.value.getMaxScaleOnAxis();
        });
      });
      return c;
    });
  }

  void _resetZoom([int? index]) {
    final i = index ?? currentIndex;
    final c = _zoomControllers[i];
    if (c != null) c.value = Matrix4.identity();
    setState(() => _currentScale[i] = 1.0);
  }

  bool get _isCurrentImageZoomed =>
      ((_currentScale[currentIndex] ?? 1.0) - 1.0).abs() > 0.05;

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
  }

  void _onPointerDown(PointerDownEvent event) {
    _activePointers++;
    if (_activePointers > 1) {
      _dragStart = null;
      setState(() => _isPinching = true);
      if (_isDragGesture) {
        _isDragGesture = false;
        setState(() => _dragOffset = 0);
      }
      return;
    }
    _dragStart = event.position;
    _isDragGesture = false;
  }

  void _onPointerMove(PointerMoveEvent event) {
    if (_activePointers != 1 || _dragStart == null || _isCurrentImageZoomed) {
      return;
    }

    final delta = event.position - _dragStart!;

    if (!_isDragGesture) {
      if (delta.dy.abs() > 8 && delta.dy.abs() > delta.dx.abs() * 1.5) {
        _isDragGesture = true;
      } else if (delta.dx.abs() > 8) {
        _dragStart = null;
        return;
      }
    }

    if (_isDragGesture) {
      setState(() => _dragOffset = delta.dy);
    }
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);

    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }

    if (_isDragGesture && _activePointers == 0) {
      if (_dragOffset.abs() > 120) {
        Navigator.of(context).pop();
      } else {
        setState(() => _dragOffset = 0);
      }
      _isDragGesture = false;
    }
    _dragStart = null;
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }
    _dragStart = null;
    _isDragGesture = false;
    if (_dragOffset != 0) setState(() => _dragOffset = 0);
  }

  Future<void> _saveImage(String path) async {
    try {
      // ضع هنا منطق الحفظ الحقيقي عندك
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم الحفظ للمعرض')),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حفظ الصورة')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final bgOpacity = (1 - (_dragOffset.abs() / 350)).clamp(0.35, 1.0);

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: Listener(
        onPointerDown: _onPointerDown,
        onPointerMove: _onPointerMove,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
          onTap: _toggleControls,
          behavior: HitTestBehavior.translucent,
          child: Container(
            color: Colors.black.withValues(alpha: bgOpacity),
            child: Stack(
              children: [
                // ===== الصورة =====
                Transform.translate(
                  offset: Offset(0, _dragOffset),
                  child: Transform.scale(
                    scale: (1 - (_dragOffset.abs() / 2000)).clamp(0.85, 1.0),
                    child: PageView.builder(
                      controller: _pageController,
                      physics: _isDragGesture
                          ? const NeverScrollableScrollPhysics()
                          : const PageScrollPhysics(),
                      itemCount: widget.images.length,
                      onPageChanged: (index) {
                        _resetZoom(currentIndex);
                        setState(() => currentIndex = index);
                      },
                      itemBuilder: (context, index) {
                        final path = widget.images[index];
                        final isNetwork = path.startsWith('http://') ||
                            path.startsWith('https://');

                        final Widget imageWidget = path.startsWith('assets/')
                            ? Image.asset(path, fit: BoxFit.contain)
                            : isNetwork
                            ? Image.network(
                          path,
                          fit: BoxFit.contain,
                          loadingBuilder: (context, child, progress) {
                            if (progress == null) return child;
                            return const Center(
                              child: CircularProgressIndicator(
                                color: Colors.white54,
                              ),
                            );
                          },
                          errorBuilder: (_, __, ___) =>
                          const Center(
                            child: Icon(
                              Icons.broken_image_rounded,
                              color: Colors.white38,
                              size: 48,
                            ),
                          ),
                        )
                            : Image.file(File(path), fit: BoxFit.contain);

                        return InteractiveViewer(
                          transformationController: _zoomFor(index),
                          maxScale: 10.0,
                          minScale: 1.0,
                          panEnabled: false,
                          scaleEnabled: true,
                          boundaryMargin:
                          const EdgeInsets.all(double.infinity),
                          onInteractionEnd: (_) {
                            if (_activePointers < 2) {
                              _resetZoom(index);
                            }
                          },
                          child: Center(child: imageWidget),
                        );
                      },
                    ),
                  ),
                ),

                // ===== الشريط العلوي (إغلاق + تحميل فقط) =====
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [
                            Colors.black.withValues(alpha: 0.55),
                            Colors.transparent,
                          ],
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4),
                          child: Row(
                            children: [
                              // زر الإغلاق
                              _ViewerIconButton(
                                icon: Icons.close_rounded,
                                onTap: () => Navigator.of(context).pop(),
                              ),
                              const Spacer(),
                              // زر التحميل فقط
                              _ViewerIconButton(
                                icon: Icons.download_rounded,
                                onTap: () =>
                                    _saveImage(widget.images[currentIndex]),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),

                // ===== مؤشر الصفحات =====
                if (widget.images.length > 1)
                  Positioned(
                    left: 0,
                    right: 0,
                    bottom: 32,
                    child: Center(
                      child: _DotsIndicator(
                        count: widget.images.length,
                        activeIndex: currentIndex,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
enum _MediaKind { image, video }

class _PostMediaItem {
  final _MediaKind kind;
  final String path;
  const _PostMediaItem.image(this.path) : kind = _MediaKind.image;
  const _PostMediaItem.video(this.path) : kind = _MediaKind.video;
}

class FullscreenMediaViewer extends StatefulWidget {
  final List<_PostMediaItem> items;
  final int initialIndex;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody;
  final Widget? menuButton;
  final int? votes;
  final bool isLiked;
  final bool isDisliked;
  final int? commentsCount;
  final int? tagsCount;
  final VoidCallback? onLike;
  final VoidCallback? onDislike;
  final Future<int?> Function()? onComment;
  final VoidCallback? onTags;

  const FullscreenMediaViewer({
    super.key,
    required this.items,
    this.initialIndex = 0,
    this.authorName,
    this.authorPhotoUrl,
    this.postTitle,
    this.postBody,
    this.menuButton,
    this.votes,
    this.isLiked = false,
    this.isDisliked = false,
    this.commentsCount,
    this.tagsCount,
    this.onLike,
    this.onDislike,
    this.onComment,
    this.onTags,
  });

  @override
  State<FullscreenMediaViewer> createState() => _FullscreenMediaViewerState();
}

class _FullscreenMediaViewerState extends State<FullscreenMediaViewer> {
  late final PageController _pageController;
  late int currentIndex;
  bool _controlsVisible = true;
  double _dragOffset = 0;

  final Map<int, TransformationController> _zoomControllers = {};
  final Map<int, double> _currentScale = {};
  final Map<int, VideoPlayerController> _videoControllers = {};

  Offset? _dragStart;
  bool _isDragGesture = false;
  int _activePointers = 0;
  bool _isPinching = false;
  bool _pointerInBottomPanel = false;

  late int _votes;
  late bool _isLiked;
  late bool _isDisliked;
  late int _commentsCount;

  String _formatVotes(int votes) {
    if (votes >= 1000000) return '${(votes / 1000000).toStringAsFixed(1)}M';
    if (votes >= 1000) return '${(votes / 1000).toStringAsFixed(1)}k';
    return votes.toString();
  }

  @override
  void initState() {
    super.initState();
    currentIndex = widget.initialIndex.clamp(0, widget.items.length - 1);
    _pageController = PageController(initialPage: currentIndex);
    _votes = widget.votes ?? 0;
    _isLiked = widget.isLiked;
    _isDisliked = widget.isDisliked;
    _commentsCount = widget.commentsCount ?? 0;
    _initVideoAt(currentIndex);
  }

  Future<void> _initVideoAt(int index) async {
    if (index < 0 || index >= widget.items.length) return;
    final item = widget.items[index];
    if (item.kind != _MediaKind.video) return;
    if (_videoControllers.containsKey(index)) return;

    final path = item.path.trim();
    if (path.isEmpty) return;

    final isNetwork =
        path.startsWith('http://') || path.startsWith('https://');

    VideoPlayerController c;

    try {
      if (isNetwork) {
        // تنزيل/قراءة من الكاش ثم تشغيل محلي
        final file = await DefaultCacheManager().getSingleFile(path);
        if (!mounted) return;
        c = VideoPlayerController.file(
          file,
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else {
        c = VideoPlayerController.file(
          File(path),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      }

      await c.initialize();
      await c.setLooping(true);
      await c.setVolume(1);

      if (!mounted) {
        await c.dispose();
        return;
      }

      _videoControllers[index] = c;


      if (index == currentIndex) {
        await c.play();
      }

      if (mounted) setState(() {});
    } catch (e, st) {
      debugPrint('Fullscreen media video init failed: $e');
      debugPrintStack(stackTrace: st);
      // إن فشل الكاش، محاولة أخيرة من الشبكة
      if (isNetwork) {
        try {
          final fallback = VideoPlayerController.networkUrl(
            Uri.parse(path),
            videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
          );
          await fallback.initialize();
          await fallback.setLooping(true);
          if (!mounted) {
            await fallback.dispose();
            return;
          }
          _videoControllers[index] = fallback;
          if (index == currentIndex) await fallback.play();
          if (mounted) setState(() {});
        } catch (e2) {
          debugPrint('Fullscreen fallback also failed: $e2');
        }
      }
    }
  }

  void _pauseAllVideosExcept(int keep) {
    _videoControllers.forEach((i, c) {
      if (i != keep && c.value.isPlaying) c.pause();
    });
  }

  TransformationController _zoomFor(int index) {
    return _zoomControllers.putIfAbsent(index, () {
      final c = TransformationController();
      c.addListener(() {
        if (!mounted) return;
        setState(() {
          _currentScale[index] = c.value.getMaxScaleOnAxis();
        });
      });
      return c;
    });
  }

  void _resetZoom([int? index]) {
    final i = index ?? currentIndex;
    final c = _zoomControllers[i];
    if (c != null) c.value = Matrix4.identity();
    setState(() => _currentScale[i] = 1.0);
  }

  bool get _isCurrentZoomed =>
      ((_currentScale[currentIndex] ?? 1.0) - 1.0).abs() > 0.05;

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
  }

  void _handleLike() {
    setState(() {
      if (_isLiked) {
        _isLiked = false;
        _votes = (_votes - 1).clamp(0, 1 << 30);
      } else {
        if (_isDisliked) {
          _isDisliked = false;
          _votes += 1;
        }
        _isLiked = true;
        _votes += 1;
      }
    });
    widget.onLike?.call();
  }

  void _handleDislike() {
    setState(() {
      if (_isDisliked) {
        _isDisliked = false;
        _votes += 1;
      } else {
        if (_isLiked) {
          _isLiked = false;
          _votes -= 1;
        }
        _isDisliked = true;
        _votes -= 1;
      }
    });
    widget.onDislike?.call();
  }

  void _onPointerDown(PointerDownEvent event) {
    if (_pointerInBottomPanel) return;
    _activePointers++;
    if (_activePointers > 1) {
      _dragStart = null;
      setState(() => _isPinching = true);
      if (_isDragGesture) {
        _isDragGesture = false;
        setState(() => _dragOffset = 0);
      }
      return;
    }
    _dragStart = event.position;
    _isDragGesture = false;
  }

  void _onPointerMove(PointerMoveEvent event) {
    if (_pointerInBottomPanel) return;
    if (_activePointers != 1 || _dragStart == null || _isCurrentZoomed) return;

    final delta = event.position - _dragStart!;
    if (!_isDragGesture) {
      if (delta.dy.abs() > 8 && delta.dy.abs() > delta.dx.abs() * 1.5) {
        _isDragGesture = true;
      } else if (delta.dx.abs() > 8) {
        _dragStart = null;
        return;
      }
    }
    if (_isDragGesture) setState(() => _dragOffset = delta.dy);
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }
    if (_isDragGesture && _activePointers == 0) {
      if (_dragOffset.abs() > 120) {
        Navigator.of(context).pop();
      } else {
        setState(() => _dragOffset = 0);
      }
      _isDragGesture = false;
    }
    _dragStart = null;
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }
    _dragStart = null;
    _isDragGesture = false;
    if (_dragOffset != 0) setState(() => _dragOffset = 0);
  }

  Widget _buildImagePage(int index, String path) {
    final isNetwork =
        path.startsWith('http://') || path.startsWith('https://');
    final imageWidget = path.startsWith('assets/')
        ? Image.asset(path, fit: BoxFit.contain)
        : isNetwork
        ? Image.network(
      path,
      fit: BoxFit.contain,
      errorBuilder: (_, __, ___) => const Icon(
        Icons.broken_image_rounded,
        color: Colors.white38,
        size: 48,
      ),
    )
        : Image.file(File(path), fit: BoxFit.contain);

    return InteractiveViewer(
      transformationController: _zoomFor(index),
      maxScale: 10,
      minScale: 1,
      panEnabled: false,
      scaleEnabled: true,
      boundaryMargin: const EdgeInsets.all(double.infinity),
      onInteractionEnd: (_) {
        if (_activePointers < 2) _resetZoom(index);
      },
      child: Center(child: imageWidget),
    );
  }

  Widget _buildVideoPage(int index) {
    final c = _videoControllers[index];
    if (c == null || !c.value.isInitialized) {
      return const Center(
        child: CircularProgressIndicator(color: Colors.white54),
      );
    }

    final ratio = c.value.aspectRatio > 0 ? c.value.aspectRatio : 16 / 9;

    return Center(
      child: AspectRatio(
        aspectRatio: ratio,
        child: InteractiveViewer(
          transformationController: _zoomFor(index),
          maxScale: 8.0,
          minScale: 1.0,
          panEnabled: false,
          scaleEnabled: true,
          boundaryMargin: const EdgeInsets.all(double.infinity),
          onInteractionEnd: (_) {
            if (_activePointers < 2) _resetZoom(index);
          },
          child: VideoPlayer(c),
        ),
      ),
    );
  }

  @override
  void dispose() {
    _pageController.dispose();
    for (final c in _zoomControllers.values) {
      c.dispose();
    }
    for (final c in _videoControllers.values) {
      c.dispose();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bgOpacity = (1 - (_dragOffset.abs() / 350)).clamp(0.35, 1.0);

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: Listener(
        onPointerDown: _onPointerDown,
        onPointerMove: _onPointerMove,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
          onTap: _toggleControls,
          behavior: HitTestBehavior.translucent,
          child: Container(
            color: Colors.black.withValues(alpha: bgOpacity),
            child: Stack(
              children: [
                Transform.translate(
                  offset: Offset(0, _dragOffset),
                  child: PageView.builder(
                    controller: _pageController,
                    physics: _isDragGesture
                        ? const NeverScrollableScrollPhysics()
                        : const PageScrollPhysics(),
                    itemCount: widget.items.length,
                    onPageChanged: (index) {          // ← هنا
                      _resetZoom(currentIndex);
                      _pauseAllVideosExcept(index);
                      setState(() => currentIndex = index);
                      _initVideoAt(index).then((_) {
                        final c = _videoControllers[index];
                        if (c != null && c.value.isInitialized) {
                          c.seekTo(Duration.zero);
                          c.play();
                        }
                      });
                    },
                    itemBuilder: (context, index) {
                      final item = widget.items[index];
                      if (item.kind == _MediaKind.image) {
                        return _buildImagePage(index, item.path);
                      }
                      return _buildVideoPage(index);
                    },
                  ),
                ),

                // شريط علوي
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [
                            Colors.black.withValues(alpha: 0.55),
                            Colors.transparent,
                          ],
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4),
                          child: Row(
                            children: [
                              _ViewerIconButton(
                                icon: Icons.close_rounded,
                                onTap: () => Navigator.of(context).pop(),
                              ),
                              const Spacer(),
                              if (widget.menuButton != null) widget.menuButton!,
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),

                // شريط سفلي
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Align(
                      alignment: Alignment.bottomCenter,
                      child: Listener(
                        onPointerDown: (_) => _pointerInBottomPanel = true,
                        onPointerUp: (_) => _pointerInBottomPanel = false,
                        onPointerCancel: (_) =>
                        _pointerInBottomPanel = false,
                        child: Container(
                          width: double.infinity,
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.bottomCenter,
                              end: Alignment.topCenter,
                              colors: [
                                Colors.black.withValues(alpha: 0.92),
                                Colors.black.withValues(alpha: 0.55),
                                Colors.transparent,
                              ],
                              stops: const [0.0, 0.55, 1.0],
                            ),
                          ),
                          child: SafeArea(
                            top: false,
                            child: Padding(
                              padding:
                              const EdgeInsets.fromLTRB(14, 28, 14, 10),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  if (widget.items.length > 1) ...[
                                    Center(
                                      child: _DotsIndicator(
                                        count: widget.items.length,
                                        activeIndex: currentIndex,
                                      ),
                                    ),
                                    const SizedBox(height: 10),
                                  ],
                                  _RedditStyleMeta(
                                    authorName: widget.authorName,
                                    authorPhotoUrl: widget.authorPhotoUrl,
                                    postTitle: widget.postTitle,
                                    postBody: widget.postBody,
                                  ),
                                  if (widget.items[currentIndex].kind == _MediaKind.video) ...[
                                    const SizedBox(height: 12),
                                    if (_videoControllers[currentIndex] != null &&
                                        _videoControllers[currentIndex]!.value.isInitialized)
                                      _InlineVideoControls(
                                        controller: _videoControllers[currentIndex]!,
                                      ),
                                  ],
                                  if (widget.onLike != null) ...[
                                    const SizedBox(height: 12),
                                    _FullscreenActionBar(
                                      likeButtonKey: GlobalKey(),
                                      tagsCount: widget.tagsCount ?? 0,
                                      onTagsTap: widget.onTags ?? () {},
                                      commentLabel: '$_commentsCount',
                                      onCommentTap: () async {
                                        final n =
                                        await widget.onComment?.call();
                                        if (n != null && mounted) {
                                          setState(
                                                  () => _commentsCount = n);
                                        }
                                      },
                                      likeLabel: _formatVotes(_votes),
                                      isLiked: _isLiked,
                                      isDisliked: _isDisliked,
                                      onLikeTap: _handleLike,
                                      onDislike: _handleDislike,
                                    ),
                                  ],
                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _VideoInitGate {
  _VideoInitGate._();
  static final _VideoInitGate instance = _VideoInitGate._();

  static const int maxConcurrent = 1; // بدلها لـ 3 إلا بغيتي تسمح بشوية أكثر

  int _active = 0;
  final List<Completer<void>> _queue = [];

  Future<void> acquire() async {
    if (_active < maxConcurrent) {
      _active++;
      return;
    }
    final c = Completer<void>();
    _queue.add(c);
    await c.future;
    _active++;
  }

  void release() {
    _active = (_active - 1).clamp(0, 1 << 30);
    if (_queue.isNotEmpty) {
      _queue.removeAt(0).complete();
    }
  }
}

