class VideoPreviewTile extends StatefulWidget {
  final VideoPlayerController controller;
  final VoidCallback? onRemove;

  const VideoPreviewTile({
    super.key,
    required this.controller,
    this.onRemove,
  });

  @override
  State<VideoPreviewTile> createState() => _VideoPreviewTileState();
}

class _VideoPreviewTileState extends State<VideoPreviewTile> {
  bool _finished = false;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onUpdate);
    widget.controller.setLooping(false);

    if (!widget.controller.value.isInitialized) {
      widget.controller.initialize().then((_) {
        if (mounted) setState(() {});
      });
    }
  }

  void _onUpdate() {
    if (!mounted) return;
    final c = widget.controller;
    if (!c.value.isInitialized || _finished) return;

    final d = c.value.duration;
    final p = c.value.position;
    if (d > Duration.zero &&
        p >= d - const Duration(milliseconds: 300)) {
      c.pause();
      setState(() => _finished = true);
    } else {
      setState(() {});
    }
  }

  Future<void> _openFullscreenReplay() async {
    final c = widget.controller;
    await c.pause();
    await c.setVolume(0);
    if (!mounted) return;

    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => FullscreenVideoViewer(controller: c),
      ),
    );

    if (!mounted) return;
    await c.seekTo(Duration.zero);
    await c.pause();
    await c.setVolume(0);
    setState(() => _finished = true);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onUpdate);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;

    return Column(
      children: [
        ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Container(
            height: 180,
            width: double.infinity,
            color: Colors.black,
            child: Stack(
              alignment: Alignment.center,
              children: [
                if (controller.value.isInitialized)
                  FittedBox(
                    fit: BoxFit.cover,
                    child: SizedBox(
                      width: controller.value.size.width,
                      height: controller.value.size.height,
                      child: VideoPlayer(controller),
                    ),
                  )
                else
                  const Center(child: CircularProgressIndicator()),

                // قبل الانتهاء: play / pause
                if (!_finished)
                  IconButton(
                    iconSize: 56,
                    color: Colors.white,
                    icon: Icon(
                      controller.value.isPlaying
                          ? Icons.pause_circle
                          : Icons.play_circle_outline,
                    ),
                    onPressed: () {
                      setState(() {
                        controller.value.isPlaying
                            ? controller.pause()
                            : controller.play();
                      });
                    },
                  ),

                // بعد الانتهاء: replay → ملء الشاشة (بدون زر توسّع)
                if (_finished)
                  Positioned.fill(
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: _openFullscreenReplay,
                      child: Container(
                        color: Colors.black38,
                        alignment: Alignment.center,
                        child: Container(
                          padding: const EdgeInsets.all(14),
                          decoration: const BoxDecoration(
                            color: Colors.black54,
                            shape: BoxShape.circle,
                          ),
                          child: const Icon(
                            Icons.replay_rounded,
                            color: Colors.white,
                            size: 40,
                          ),
                        ),
                      ),
                    ),
                  ),

                if (widget.onRemove != null)
                  Positioned(
                    top: 6,
                    right: 6,
                    child: GestureDetector(
                      onTap: widget.onRemove,
                      child: const CircleAvatar(
                        radius: 12,
                        backgroundColor: Colors.black54,
                        child: Icon(
                          Icons.close,
                          size: 16,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
        if (controller.value.isInitialized)
          Padding(
            padding: const EdgeInsets.only(top: 6),
            child: SizedBox(
              height: 4,
              child: VideoProgressIndicator(
                controller,
                allowScrubbing: true,
                colors: const VideoProgressColors(
                  playedColor: Colors.red,
                  bufferedColor: Colors.white38,
                  backgroundColor: Colors.white24,
                ),
              ),
            ),
          ),
      ],
    );
  }
}

class _VideoListWidget extends StatefulWidget {
  final List<String> videoPaths;
  const _VideoListWidget({required this.videoPaths});

  @override
  State<_VideoListWidget> createState() => _VideoListWidgetState();
}

class _VideoListWidgetState extends State<_VideoListWidget> {
  late final List<VideoPlayerController> _controllers;
  late final List<bool> _finished;
  int _currentIndex = 0;
  late final PageController _pageController;

  @override
  void initState() {
    super.initState();
    _pageController = PageController();
    _finished = List.filled(widget.videoPaths.length, false);

    _controllers = widget.videoPaths.map((path) {
      final isNetwork =
          path.startsWith('http://') || path.startsWith('https://');
      final ctrl = isNetwork
          ? VideoPlayerController.networkUrl(Uri.parse(path))
          : VideoPlayerController.file(File(path));

      ctrl.setLooping(false); // مهم
      ctrl.initialize().then((_) {
        if (mounted) setState(() {});
      });
      return ctrl;
    }).toList();

    for (int i = 0; i < _controllers.length; i++) {
      final index = i;
      _controllers[i].addListener(() => _onUpdate(index));
    }
  }

  void _onUpdate(int index) {
    if (!mounted || _finished[index]) return;
    final c = _controllers[index];
    if (!c.value.isInitialized) return;

    final d = c.value.duration;
    final p = c.value.position;
    if (d > Duration.zero &&
        p >= d - const Duration(milliseconds: 300)) {
      c.pause();
      setState(() => _finished[index] = true);
    } else {
      setState(() {});
    }
  }

  Future<void> _openFullscreenReplay(int index) async {
    final c = _controllers[index];
    await c.pause();
    await c.setVolume(0);
    if (!mounted) return;

    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => FullscreenVideoViewer(controller: c),
      ),
    );

    if (!mounted) return;
    await c.seekTo(Duration.zero);
    await c.pause();
    await c.setVolume(0);
    setState(() => _finished[index] = true);
  }

  @override
  void dispose() {
    for (final c in _controllers) {
      c.dispose();
    }
    _pageController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        SizedBox(
          height: 200,
          child: PageView.builder(
            controller: _pageController,
            itemCount: _controllers.length,
            onPageChanged: (i) {

              // أوقف الفيديوهات الأخرى
              for (int j = 0; j < _controllers.length; j++) {
                if (j != i && _controllers[j].value.isPlaying) {
                  _controllers[j].pause();
                }
              }
              setState(() => _currentIndex = i);
            },
            itemBuilder: (context, index) {
              final ctrl = _controllers[index];
              final done = _finished[index];

              return ClipRRect(
                borderRadius: BorderRadius.circular(12),
                child: Container(
                  color: Colors.black,
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      if (ctrl.value.isInitialized)
                        FittedBox(
                          fit: BoxFit.cover,
                          child: SizedBox(
                            width: ctrl.value.size.width,
                            height: ctrl.value.size.height,
                            child: VideoPlayer(ctrl),
                          ),
                        )
                      else
                        const CircularProgressIndicator(color: Colors.white),

                      // لا زر fullscreen منفصل

                      if (!done)
                        GestureDetector(
                          onTap: () => setState(() {
                            ctrl.value.isPlaying
                                ? ctrl.pause()
                                : ctrl.play();
                          }),
                          child: AnimatedOpacity(
                            opacity: !ctrl.value.isPlaying ? 1.0 : 0.0,
                            duration: const Duration(milliseconds: 200),
                            child: Container(
                              width: 52,
                              height: 52,
                              decoration: const BoxDecoration(
                                color: Colors.black45,
                                shape: BoxShape.circle,
                              ),
                              child: const Icon(
                                Icons.play_arrow,
                                color: Colors.white,
                                size: 32,
                              ),
                            ),
                          ),
                        ),

                      if (done)
                        Positioned.fill(
                          child: GestureDetector(
                            behavior: HitTestBehavior.opaque,
                            onTap: () => _openFullscreenReplay(index),
                            child: Container(
                              color: Colors.black38,
                              alignment: Alignment.center,
                              child: Container(
                                padding: const EdgeInsets.all(14),
                                decoration: const BoxDecoration(
                                  color: Colors.black54,
                                  shape: BoxShape.circle,
                                ),
                                child: const Icon(
                                  Icons.replay_rounded,
                                  color: Colors.white,
                                  size: 40,
                                ),
                              ),
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
        if (_controllers.isNotEmpty &&
            _controllers[_currentIndex].value.isInitialized)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 4),
            child: VideoProgressIndicator(
              _controllers[_currentIndex],
              allowScrubbing: true,
              colors: VideoProgressColors(
                playedColor: AppTeal.main,
                bufferedColor: Colors.white38,
                backgroundColor: Colors.white24,
              ),
            ),
          ),
        if (_controllers.length > 1) ...[
          const SizedBox(height: 6),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: List.generate(_controllers.length, (i) {
              return AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                margin: const EdgeInsets.symmetric(horizontal: 3),
                width: _currentIndex == i ? 10 : 6,
                height: 6,
                decoration: BoxDecoration(
                  color: _currentIndex == i
                      ? AppTeal.main
                      : Colors.grey.shade400,
                  borderRadius: BorderRadius.circular(3),
                ),
              );
            }),
          ),
        ],
      ],
    );
  }
}

class FullscreenImageViewer extends StatefulWidget {
  final List<String> images;
  final int initialIndex;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody;
  final Widget? menuButton;
  final Widget Function(BuildContext context)? onMenuBuilder;
// أضف للمعاملات:
  final int? votes;
  final bool? isLiked;
  final bool? isDisliked;
  final int? commentsCount;
  final int? tagsCount;
  final VoidCallback? onLike;
  final VoidCallback? onDislike;
  final Future<int?> Function()? onComment;
  final VoidCallback? onTags;
  const FullscreenImageViewer({
    super.key,
    required this.images,
    this.initialIndex = 0,
    this.authorName,
    this.authorPhotoUrl,
    this.postTitle,
    this.postBody,
    this.menuButton,
    this.onMenuBuilder,
    this.votes,
    this.isLiked = false,
    this.isDisliked = false,
    this.commentsCount,
    this.tagsCount,
    this.onLike,
    this.onDislike,
    this.onComment,
    this.onTags,
  });

  @override
  State<FullscreenImageViewer> createState() => _FullscreenImageViewerState();
}

class _FullscreenImageViewerState extends State<FullscreenImageViewer> {
  late final PageController _pageController;
  late int currentIndex;
  bool _controlsVisible = true;
  double _dragOffset = 0;
  String _formatVotes(int votes) {
    if (votes >= 1000000) return '${(votes / 1000000).toStringAsFixed(1)}M';
    if (votes >= 1000) return '${(votes / 1000).toStringAsFixed(1)}k';
    return votes.toString();
  }
  final Map<int, TransformationController> _zoomControllers = {};
  final Map<int, double> _currentScale = {};

  Offset? _dragStart;
  bool _isDragGesture = false;
  int _activePointers = 0;
  bool _isPinching = false;
  bool _pointerInBottomPanel = false;
  late int _votes;
  late bool _isLiked;
  late bool _isDisliked;
  late int _commentsCount;

  @override
  void initState() {
    super.initState();
    currentIndex = widget.initialIndex;
    _pageController = PageController(initialPage: currentIndex);
    _votes = widget.votes ?? 0;
    _isLiked = widget.isLiked ?? false;      // ← أضف ?? false
    _isDisliked = widget.isDisliked ?? false; // ← أضف ?? false
    _commentsCount = widget.commentsCount ?? 0;
  }
  void _handleLike() {
    setState(() {
      if (_isLiked) {
        _isLiked = false;
        _votes = (_votes - 1).clamp(0, 1 << 30);
      } else {
        if (_isDisliked) {
          _isDisliked = false;
          _votes += 1;
        }
        _isLiked = true;
        _votes += 1;
      }
    });
    widget.onLike?.call(); // يحدث المنشور الأصلي أيضًا
  }

  void _handleDislike() {
    setState(() {
      if (_isDisliked) {
        _isDisliked = false;
        _votes += 1;
      } else {
        if (_isLiked) {
          _isLiked = false;
          _votes -= 1;
        }
        _isDisliked = true;
        _votes -= 1;
      }
    });
    widget.onDislike?.call();
  }

  Future<void> _handleComment() async {
    widget.onComment?.call();
    // إذا كان onComment يفتح CommentsScreen ويرجع،
    // بعد الرجوع نزيد العداد محليًا كتقريب بسيط:
    // (أو اجعل onComment يعيد العدد الجديد إن أمكن)
  }
  @override
  void dispose() {
    _pageController.dispose();
    for (final c in _zoomControllers.values) {
      c.dispose();
    }
    super.dispose();
  }

  TransformationController _zoomFor(int index) {
    return _zoomControllers.putIfAbsent(index, () {
      final c = TransformationController();
      c.addListener(() {
        if (!mounted) return;
        setState(() {
          _currentScale[index] = c.value.getMaxScaleOnAxis();
        });
      });
      return c;
    });
  }

  void _resetZoom([int? index]) {
    final i = index ?? currentIndex;
    final c = _zoomControllers[i];
    if (c != null) {
      c.value = Matrix4.identity();
    }
    setState(() {
      _currentScale[i] = 1.0;
    });
  }

  bool get _isCurrentImageZoomed =>
      ((_currentScale[currentIndex] ?? 1.0) - 1.0).abs() > 0.05;

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
  }

  void _onPointerDown(PointerDownEvent event) {
    if (_pointerInBottomPanel) return;

    _activePointers++;
    if (_activePointers > 1) {
      _dragStart = null;
      setState(() => _isPinching = true);
      if (_isDragGesture) {
        _isDragGesture = false;
        setState(() => _dragOffset = 0);
      }
      return;
    }
    _dragStart = event.position;
    _isDragGesture = false;
  }

  void _onPointerMove(PointerMoveEvent event) {
    if (_pointerInBottomPanel) return;
    if (_activePointers != 1 || _dragStart == null || _isCurrentImageZoomed) {
      return;
    }

    final delta = event.position - _dragStart!;

    if (!_isDragGesture) {
      if (delta.dy.abs() > 8 && delta.dy.abs() > delta.dx.abs() * 1.5) {
        _isDragGesture = true;
      } else if (delta.dx.abs() > 8) {
        _dragStart = null;
        return;
      }
    }

    if (_isDragGesture) {
      setState(() => _dragOffset = delta.dy);
    }
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);

    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }

    if (_isDragGesture && _activePointers == 0) {
      if (_dragOffset.abs() > 120) {
        Navigator.of(context).pop();
      } else {
        setState(() => _dragOffset = 0);
      }
      _isDragGesture = false;
    }
    _dragStart = null;
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      _resetZoom();
    }
    _dragStart = null;
    _isDragGesture = false;
    if (_dragOffset != 0) setState(() => _dragOffset = 0);
  }

  Future<void> _saveImage(String path) async {
    try {
      // منطق الحفظ عندك
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم الحفظ للمعرض')),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حفظ الصورة')),
      );
    }
  }

  void _shareImage(String path) {
    Share.share(path);
  }

  @override
  Widget build(BuildContext context) {
    final bgOpacity = (1 - (_dragOffset.abs() / 350)).clamp(0.35, 1.0);
    final infoVisible =
        _controlsVisible && !_isPinching && !_isCurrentImageZoomed;

    return Scaffold(
      backgroundColor: Colors.transparent,
      extendBodyBehindAppBar: true,
      body: Listener(
        onPointerDown: _onPointerDown,
        onPointerMove: _onPointerMove,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
          onTap: _toggleControls,
          behavior: HitTestBehavior.translucent,
          child: Container(
            color: Colors.black.withValues(alpha: bgOpacity),
            child: Stack(
              children: [
                // ===== الصورة =====
                Transform.translate(
                  offset: Offset(0, _dragOffset),
                  child: Transform.scale(
                    scale: (1 - (_dragOffset.abs() / 2000)).clamp(0.85, 1.0),
                    child: PageView.builder(
                      controller: _pageController,
                      physics: _isDragGesture
                          ? const NeverScrollableScrollPhysics()
                          : const PageScrollPhysics(),
                      itemCount: widget.images.length,
                      onPageChanged: (index) {
                        _resetZoom(currentIndex);
                        setState(() => currentIndex = index);
                      },
                      itemBuilder: (context, index) {
                        final path = widget.images[index];
                        final isNetwork = path.startsWith('http://') ||
                            path.startsWith('https://');

                        final Widget imageWidget = path.startsWith('assets/')
                            ? Image.asset(path, fit: BoxFit.contain)
                            : isNetwork
                            ? Image.network(
                          path,
                          fit: BoxFit.contain,
                          loadingBuilder: (context, child, progress) {
                            if (progress == null) return child;
                            return const Center(
                              child: CircularProgressIndicator(
                                color: Colors.white54,
                              ),
                            );
                          },
                          errorBuilder: (_, __, ___) =>
                          const Center(
                            child: Icon(
                              Icons.broken_image_rounded,
                              color: Colors.white38,
                              size: 48,
                            ),
                          ),
                        )
                            : Image.file(File(path), fit: BoxFit.contain);

                        return InteractiveViewer(
                          transformationController: _zoomFor(index),
                          maxScale: 10.0,
                          minScale: 1.0,
                          panEnabled: false,
                          scaleEnabled: true,
                          boundaryMargin:
                          const EdgeInsets.all(double.infinity),
                          onInteractionEnd: (_) {
                            if (_activePointers < 2) {
                              _resetZoom(index);
                            }
                          },
                          child: Center(child: imageWidget),
                        );
                      },
                    ),
                  ),
                ),

                // ===== الشريط العلوي (مثل الفيديو) =====
                // ===== الشريط العلوي =====
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [
                            Colors.black.withValues(alpha: 0.55),
                            Colors.transparent,
                          ],
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                          child: Row(
                            children: [
                              _ViewerIconButton(
                                icon: Icons.close_rounded,
                                onTap: () => Navigator.of(context).pop(),
                              ),
                              const Spacer(),

                              // ===== زر القائمة (يظهر دائمًا إذا تم تمريره) =====
                              if (widget.onMenuBuilder != null) ...[
                                widget.onMenuBuilder!(context),
                                const SizedBox(width: 6),
                              ] else if (widget.menuButton != null) ...[
                                widget.menuButton!,
                                const SizedBox(width: 6),
                              ],

                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),



                // ===== اللوحة السفلية (نفس أسلوب الفيديو) =====
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Align(
                      alignment: Alignment.bottomCenter,
                      child: Listener(
                        onPointerDown: (_) => _pointerInBottomPanel = true,
                        onPointerUp: (_) => _pointerInBottomPanel = false,
                        onPointerCancel: (_) => _pointerInBottomPanel = false,
                        child: Container(
                          width: double.infinity,
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.bottomCenter,
                              end: Alignment.topCenter,
                              colors: [
                                Colors.black.withValues(alpha: 0.92),
                                Colors.black.withValues(alpha: 0.55),
                                Colors.transparent,
                              ],
                              stops: const [0.0, 0.55, 1.0],
                            ),
                          ),
                          child: SafeArea(
                            top: false,
                            child: Padding(
                              padding:
                              const EdgeInsets.fromLTRB(14, 28, 14, 10),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  // مؤشر الصفحات (Dots) إذا كان هناك أكثر من صورة
                                  if (widget.images.length > 1) ...[
                                    const SizedBox(height: 14),
                                    Center(
                                      child: _DotsIndicator(
                                        count: widget.images.length,
                                        activeIndex: currentIndex,
                                      ),
                                    ),
                                  ],
                                  // نفس الـ Meta المستخدم في الفيديو
                                  _RedditStyleMeta(
                                    authorName: widget.authorName,
                                    authorPhotoUrl: widget.authorPhotoUrl,
                                    postTitle: widget.postTitle,
                                    postBody: widget.postBody,
                                  ),
                                  // بعد _RedditStyleMeta
                                  if (widget.onLike != null) ...[
                                    const SizedBox(height: 12),
                                    _FullscreenActionBar(
                                      likeButtonKey: GlobalKey(),
                                      tagsCount: widget.tagsCount ?? 0,
                                      onTagsTap: widget.onTags ?? () {},
                                      commentLabel: '$_commentsCount',
                                      onCommentTap: () async {
                                        final newCount = await widget.onComment?.call();
                                        if (newCount != null && mounted) {
                                          setState(() => _commentsCount = newCount);
                                        }
                                      },
                                      likeLabel: _formatVotes(_votes),
                                      isLiked: _isLiked,
                                      isDisliked: _isDisliked,
                                      onLikeTap: _handleLike,
                                      onDislike: _handleDislike,
                                    ),
                                  ],

                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

