class _DotsIndicator extends StatelessWidget {
  const _DotsIndicator({required this.count, required this.activeIndex});

  final int count;
  final int activeIndex;

  @override
  Widget build(BuildContext context) {
    final visibleCount = count > 8 ? 8 : count;
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: List.generate(visibleCount, (i) {
        final isActive = i == (activeIndex.clamp(0, visibleCount - 1));
        return AnimatedContainer(
          duration: const Duration(milliseconds: 200),
          margin: const EdgeInsets.symmetric(horizontal: 2.5),
          width: isActive ? 18 : 6,
          height: 6,
          decoration: BoxDecoration(
            color: isActive ? Colors.white : Colors.white.withValues(alpha: 0.4),
            borderRadius: BorderRadius.circular(999),
          ),
        );
      }),
    );
  }
}

class FullscreenVideoViewer extends StatefulWidget {
  final VideoPlayerController controller;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody; // جديد
  final Widget? menuButton; // زر ⋮ جاهز
  final Widget Function(BuildContext context)? onMenuBuilder;
// أضف للمعاملات:
  final int? votes;
  final bool? isLiked;
  final bool? isDisliked;
  final int? commentsCount;
  final int? tagsCount;
  final VoidCallback? onLike;
  final VoidCallback? onDislike;
  final Future<int?> Function()? onComment;
  final VoidCallback? onTags;

  const FullscreenVideoViewer({
    super.key,
    required this.controller,
    this.authorName,
    this.authorPhotoUrl,
    this.postTitle,
    this.postBody,
    this.menuButton,
    this.onMenuBuilder,
    this.votes,
    this.isLiked = false,
    this.isDisliked = false,
    this.commentsCount,
    this.tagsCount,
    this.onLike,
    this.onDislike,
    this.onComment,
    this.onTags,
  });

  @override
  State<FullscreenVideoViewer> createState() => _FullscreenVideoViewerState();
}

class _FullscreenVideoViewerState extends State<FullscreenVideoViewer> {
  bool _controlsVisible = true;
  Timer? _hideTimer;
  double _dragOffset = 0;
  final TransformationController _zoomController = TransformationController();
  String _formatVotes(int votes) {
    if (votes >= 1000000) return '${(votes / 1000000).toStringAsFixed(1)}M';
    if (votes >= 1000) return '${(votes / 1000).toStringAsFixed(1)}k';
    return votes.toString();
  }
  Offset? _dragStart;
  bool _isDragGesture = false;
  int _activePointers = 0;
  bool _isPinching = false; // NE
  double _currentScale = 1.0; // ليس final
  bool _pointerInBottomPanel = false;
  late int _votes;
  late bool _isLiked;
  late bool _isDisliked;
  late int _commentsCount;

  @override
  void initState() {
    super.initState();
    _votes = widget.votes ?? 0;
    _isLiked = widget.isLiked ?? false;      // ← أضف ?? false
    _isDisliked = widget.isDisliked ?? false; // ← أضف ?? false
    _commentsCount = widget.commentsCount ?? 0;
    final c = widget.controller;
    c.setLooping(false);
    c.addListener(_tick);
    _zoomController.addListener(() {
      setState(() => _currentScale = _zoomController.value.getMaxScaleOnAxis());
    });
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      await c.seekTo(Duration.zero);
      await c.play();
      if (mounted) setState(() {});
      _scheduleAutoHide();
    });
  }

  void _handleLike() {
    setState(() {
      if (_isLiked) {
        _isLiked = false;
        _votes = (_votes - 1).clamp(0, 1 << 30);
      } else {
        if (_isDisliked) {
          _isDisliked = false;
          _votes += 1;
        }
        _isLiked = true;
        _votes += 1;
      }
    });
    widget.onLike?.call(); // يحدث المنشور الأصلي أيضًا
  }

  void _handleDislike() {
    setState(() {
      if (_isDisliked) {
        _isDisliked = false;
        _votes += 1;
      } else {
        if (_isLiked) {
          _isLiked = false;
          _votes -= 1;
        }
        _isDisliked = true;
        _votes -= 1;
      }
    });
    widget.onDislike?.call();
  }

  Future<void> _handleComment() async {
    widget.onComment?.call();
    // إذا كان onComment يفتح CommentsScreen ويرجع،
    // بعد الرجوع نزيد العداد محليًا كتقريب بسيط:
    // (أو اجعل onComment يعيد العدد الجديد إن أمكن)
  }
  void _tick() {
    if (mounted) setState(() {});
  }
  void _resetZoom() {
    _zoomController.value = Matrix4.identity();
    if (mounted) {
      setState(() => _currentScale = 1.0);
    }
  }
  bool get _isZoomed => (_currentScale - 1.0).abs() > 0.05;

  bool get _isEnded {
    final c = widget.controller;
    return c.value.isInitialized &&
        c.value.duration > Duration.zero &&
        c.value.position >= c.value.duration;
  }

  void _scheduleAutoHide() {
    _hideTimer?.cancel();
    _hideTimer = Timer(const Duration(seconds: 3), () {
      if (mounted && widget.controller.value.isPlaying) {
        setState(() => _controlsVisible = false);
      }
    });
  }

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
    if (_controlsVisible) _scheduleAutoHide();
  }

  void _togglePlay() {
    final c = widget.controller;
    if (_isEnded) {
      c.seekTo(Duration.zero);
      c.play();
    } else {
      c.value.isPlaying ? c.pause() : c.play();
    }
    setState(() => _controlsVisible = true);
    _scheduleAutoHide();
  }

  void _seekBy(Duration offset) {
    final c = widget.controller;
    final target = c.value.position + offset;
    final clamped = target < Duration.zero
        ? Duration.zero
        : (target > c.value.duration ? c.value.duration : target);
    c.seekTo(clamped);
    _scheduleAutoHide();
  }

  String _formatDuration(Duration d) {
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    final mm = m.toString().padLeft(2, '0');
    final ss = s.toString().padLeft(2, '0');
    return h > 0 ? '$h:$mm:$ss' : '$mm:$ss';
  }

  void _onPointerDown(PointerDownEvent event) {
    if (_pointerInBottomPanel) return; // تجاهل السحب من الشريط السفلي

    _activePointers++;
    if (_activePointers > 1) {
      _dragStart = null;
      setState(() => _isPinching = true); // NEW
      if (_isDragGesture) {
        _isDragGesture = false;
        setState(() => _dragOffset = 0);
      }
      return;
    }
    _dragStart = event.position;
    _isDragGesture = false;
  }

  void _onPointerMove(PointerMoveEvent event) {
    if (_pointerInBottomPanel) return;
    if (_activePointers != 1 || _dragStart == null || _isZoomed) return;

    final delta = event.position - _dragStart!;

    if (!_isDragGesture) {
      if (delta.dy.abs() > 8 && delta.dy.abs() > delta.dx.abs() * 1.5) {
        _isDragGesture = true;
      } else if (delta.dx.abs() > 8) {
        _dragStart = null;
        return;
      }
    }

    if (_isDragGesture) {
      setState(() => _dragOffset = delta.dy);
    }
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false); // NEW
    }

    if (_isDragGesture && _activePointers == 0) {
      if (_dragOffset.abs() > 120) {
        Navigator.of(context).pop();
      } else {
        setState(() => _dragOffset = 0);
      }
      _isDragGesture = false;
    }
    _dragStart = null;
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false); // NEW
    }
    _dragStart = null;
    _isDragGesture = false;
    if (_dragOffset != 0) setState(() => _dragOffset = 0);
  }

  @override
  void dispose() {
    _hideTimer?.cancel();
    widget.controller.removeListener(_tick);
    _zoomController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final c = widget.controller;
    final ratio = c.value.isInitialized && c.value.aspectRatio > 0
        ? c.value.aspectRatio
        : 16 / 9;
    final bgOpacity = (1 - (_dragOffset.abs() / 350)).clamp(0.35, 1.0);
    // NEW
    final infoVisible = _controlsVisible && !_isPinching && !_isZoomed;

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: Listener(
        onPointerDown: _onPointerDown,
        onPointerMove: _onPointerMove,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
          onTap: _toggleControls,

          behavior: HitTestBehavior.translucent,
          child: Container(
            color: Colors.black.withValues(alpha: bgOpacity),
            child: Stack(
              children: [
                Transform.translate(
                  offset: Offset(0, _dragOffset),
                  child: Center(
                    child: AspectRatio(
                      aspectRatio: ratio,
                      child: InteractiveViewer(
                        transformationController: _zoomController,
                        maxScale: 8.0,
                        minScale: 1.0, // FIX: يقدر يصغّر أكثر من الحجم العادي
                        panEnabled: false,
                        scaleEnabled: true,
                        boundaryMargin: const EdgeInsets.all(double.infinity),
                        onInteractionEnd: (_) {
                          // عند رفع الإصبعين بعد التكبير
                          if (_activePointers < 2) {
                            _resetZoom();
                            setState(() {});
                          }
                        },
                        child: VideoPlayer(c),
                      ),
                    ),
                  ),
                ),

                Positioned(
                  top: 90,
                  bottom: 130,
                  left: 0,
                  right: 0,
                  child: Row(
                    children: [
                      Expanded(
                        child: GestureDetector(
                          onDoubleTap: () => _seekBy(const Duration(seconds: -10)),
                          behavior: HitTestBehavior.translucent,
                        ),
                      ),
                      Expanded(
                        child: GestureDetector(
                          onDoubleTap: () => _seekBy(const Duration(seconds: 10)),
                          behavior: HitTestBehavior.translucent,
                        ),
                      ),
                    ],
                  ),
                ),

                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [
                            Colors.black.withValues(alpha: 0.55),
                            Colors.transparent,
                          ],
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                          child: Row(
                            children: [
                              _ViewerIconButton(
                                icon: Icons.close_rounded,
                                onTap: () => Navigator.of(context).pop(),
                              ),
                              const Spacer(),
                              // ===== زر القائمة هنا =====
                              if (widget.onMenuBuilder != null)
                                widget.onMenuBuilder!(context)
                              else if (widget.menuButton != null)
                                widget.menuButton!,
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),

                // ===== أسفل الشاشة =====
                AnimatedOpacity(
                  opacity: _controlsVisible ? 1 : 0,
                  duration: const Duration(milliseconds: 200),
                  child: IgnorePointer(
                    ignoring: !_controlsVisible,
                    child: Align(
                      alignment: Alignment.bottomCenter,
                      child: Listener(
                        onPointerDown: (_) => _pointerInBottomPanel = true,
                        onPointerUp: (_) => _pointerInBottomPanel = false,
                        onPointerCancel: (_) => _pointerInBottomPanel = false,
                        child: Container(
                          width: double.infinity,
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.bottomCenter,
                              end: Alignment.topCenter,
                              colors: [
                                Colors.black.withValues(alpha: 0.92),
                                Colors.black.withValues(alpha: 0.55),
                                Colors.transparent,
                              ],
                              stops: const [0.0, 0.55, 1.0],
                            ),
                          ),
                          child: SafeArea(
                            top: false,
                            child: Padding(
                              padding: const EdgeInsets.fromLTRB(14, 28, 14, 10),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  _RedditStyleMeta(
                                    authorName: widget.authorName,
                                    authorPhotoUrl: widget.authorPhotoUrl,
                                    postTitle: widget.postTitle,
                                    postBody: widget.postBody,
                                  ),
                                  const SizedBox(height: 12),
                                  _InlineVideoControls(controller: c),
                                  // بعد _RedditStyleMeta
                                  if (widget.onLike != null) ...[
                                    const SizedBox(height: 12),
                                    _FullscreenActionBar(
                                      likeButtonKey: GlobalKey(),
                                      tagsCount: widget.tagsCount ?? 0,
                                      onTagsTap: widget.onTags ?? () {},
                                      commentLabel: '$_commentsCount',
                                      onCommentTap: () async {
                                        final newCount = await widget.onComment?.call();
                                        if (newCount != null && mounted) {
                                          setState(() => _commentsCount = newCount);
                                        }
                                      },
                                      likeLabel: _formatVotes(_votes),
                                      isLiked: _isLiked,
                                      isDisliked: _isDisliked,
                                      onLikeTap: _handleLike,
                                      onDislike: _handleDislike,
                                    ),
                                  ],
                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ==================== FullscreenPostPager (TikTok-style vertical swipe) ====================

class FullscreenPostPager extends StatefulWidget {
  const FullscreenPostPager({
    super.key,
    required this.posts,
    required this.initialIndex,
    this.initialMediaIndex = 0,
    this.onChanged,
    this.menuButton,
    this.onNearEnd,
  this.onAuthorBlocked,
  });

  final List<_Post> posts;
  final int initialIndex;
  final int initialMediaIndex;
  final VoidCallback? onChanged;
  final Widget? menuButton;
  final void Function(String authorId)? onAuthorBlocked;

  /// يُستدعى قرب نهاية القائمة، ويعيد كل المنشورات بعد التحميل
  final Future<List<_Post>> Function()? onNearEnd;

  @override
  State<FullscreenPostPager> createState() => _FullscreenPostPagerState();
}

class _FullscreenPostPagerState extends State<FullscreenPostPager> {
  late PageController _verticalController;
  late int _currentIndex;
  late List<_Post> _posts;
  bool _lockVertical = false;
  bool _loadingMore = false;

  @override
  void initState() {
    super.initState();
    _posts = List<_Post>.from(widget.posts);
    current = this;
    _currentIndex =
        widget.initialIndex.clamp(0, (_posts.length - 1).clamp(0, 1 << 30));
    _verticalController = PageController(initialPage: _currentIndex);
  }
  static _FullscreenPostPagerState? current;

  _Post get currentPost =>
      _posts[_currentIndex.clamp(0, _posts.length - 1)];

  void hidePost(String postId) {
    if (postId.isEmpty) return;
    final idx = _posts.indexWhere((p) => p.id == postId);
    if (idx < 0) return;

    final next = List<_Post>.from(_posts)..removeAt(idx);
    if (next.isEmpty) {
      if (Navigator.of(context).canPop()) {
        Navigator.of(context).pop(true);
      }
      return;
    }

    var i = _currentIndex;
    if (idx < i) i -= 1;
    if (i >= next.length) i = next.length - 1;

    setState(() {
      _posts = next;
      _currentIndex = i;
    });

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (_verticalController.hasClients) {
        _verticalController.jumpToPage(i);
      }
    });
  }

  void _onAuthorBlocked(String authorId) {
    final next = _posts
        .where((p) => !isBlockedPost(p, {authorId}))
        .toList();

    if (next.isEmpty) {
      if (Navigator.of(context).canPop()) {
        Navigator.of(context).pop(true);
      }
      return;
    }

    var i = _currentIndex;
    if (i >= next.length) i = next.length - 1;

    setState(() {
      _posts = next;
      _currentIndex = i;
    });

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_verticalController.hasClients) {
        _verticalController.jumpToPage(i);
      }
    });
  }
  @override
  void dispose() {
    _verticalController.dispose();
    if (current == this) current = null;
    super.dispose();
  }

  List<_Post> _filterSwipeable(List<_Post> source) {
    return source.where((p) {
      final hasMedia = p.imagePaths.any((s) => s.trim().isNotEmpty) ||
          p.videoPaths.any((s) => s.trim().isNotEmpty);
      if (p.pollDataList.isNotEmpty && !hasMedia) return false;
      return hasMedia;
    }).toList();
  }

  Future<void> _maybeLoadMore(int i) async {
    if (widget.onNearEnd == null) return;
    if (_loadingMore) return;
    if (_posts.isEmpty) return;
    if (i < _posts.length - 3) return;

    _loadingMore = true;
    try {
      final updated = await widget.onNearEnd!();
      if (!mounted) return;
      final filtered = _filterSwipeable(updated);
      if (filtered.length <= _posts.length) return;
      setState(() => _posts = filtered);
    } catch (e) {
      debugPrint('Pager loadMore failed: $e');
    } finally {
      _loadingMore = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: PageView.builder(
        controller: _verticalController,
        scrollDirection: Axis.vertical,
        physics: _lockVertical
            ? const NeverScrollableScrollPhysics()
            : const PageScrollPhysics(),
        itemCount: _posts.length, // ← القائمة الداخلية
        onPageChanged: (i) {
          setState(() => _currentIndex = i);
          _maybeLoadMore(i);
        },
        itemBuilder: (context, index) {
          final post = _posts[index];
          return _PostPagerPage(
            key: ValueKey(
              post.id ??
                  '${post.author}_${post.createdAt.millisecondsSinceEpoch}',
            ),
            post: post,
            isActive: index == _currentIndex,
            initialMediaIndex:
            index == widget.initialIndex ? widget.initialMediaIndex : 0,
            onChanged: widget.onChanged,
            menuButton: widget.menuButton,
            onAuthorBlocked: _onAuthorBlocked,
            onPostHidden: hidePost,
            onLockScroll: (lock) {
              if (_lockVertical != lock) {
                setState(() => _lockVertical = lock);
              }
            },
          );
        },
      ),
    );
  }
}

// ==================== صفحة منشور واحد داخل الـ Pager ====================

class _PostPagerPage extends StatefulWidget {
  const _PostPagerPage({
    super.key,
    required this.post,
    required this.isActive,
    this.initialMediaIndex = 0,
    this.onChanged,
    this.onLockScroll, // ← جديد
    this.menuButton,
    this.onAuthorBlocked,
    this.onPostHidden,
  });

  final _Post post;
  final bool isActive;
  final int initialMediaIndex;
  final VoidCallback? onChanged;
  final Widget? menuButton;
  final ValueChanged<bool>? onLockScroll;
  final void Function(String authorId)? onAuthorBlocked;
  final void Function(String postId)? onPostHidden;
  @override
  State<_PostPagerPage> createState() => _PostPagerPageState();
}

class _PostPagerPageState extends State<_PostPagerPage> {
  late final PageController _mediaController;
  late int _mediaIndex;

  final Map<int, VideoPlayerController> _videoControllers = {};
  bool _isNavigatingComments = false;
  bool _controlsVisible = true;
  List<_PostMediaItem> _mediaItemsForPost(_Post post) {
    final items = <_PostMediaItem>[];
    for (final p in post.imagePaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.image(p.trim()));
    }
    for (final p in post.videoPaths) {
      if (p.trim().isNotEmpty) items.add(_PostMediaItem.video(p.trim()));
    }
    return items;
  }
  List<_PostMediaItem> get _items => _mediaItemsForPost(widget.post);
  final Map<int, TransformationController> _zoomControllers = {};
  final Map<int, double> _currentScale = {};
  int _activePointers = 0;
  bool _isPinching = false;

  TransformationController _zoomFor(int index) {
    return _zoomControllers.putIfAbsent(index, () {
      final c = TransformationController();
      c.addListener(() {
        if (!mounted) return;

        final s = c.value.getMaxScaleOnAxis();

        // إذا رجع قريباً من الحجم الطبيعي → صفّر الموقع + المقياس
        if (s <= 1.02) {
          final m = c.value.storage;
          final hasTranslation =
              m[12].abs() > 0.5 || m[13].abs() > 0.5; // tx, ty
          if (s < 1.0 || hasTranslation || (s - 1.0).abs() > 0.001) {
            // تجنب حلقة لا نهائية: لا نعيد التعيين إن كان identity فعلاً
            if (hasTranslation || s < 0.999 || s > 1.001) {
              c.value = Matrix4.identity();
              _currentScale[index] = 1.0;
              setState(() {});
              _updateLock();
              return;
            }
          }
        }

        final prev = _currentScale[index] ?? 1.0;
        if ((prev - s).abs() > 0.001) {
          setState(() => _currentScale[index] = s);
          _updateLock();
        }
      });
      return c;
    });
  }

  void _resetZoom([int? index]) {
    final i = index ?? _mediaIndex;
    final c = _zoomControllers[i];
    if (c != null) {
      c.value = Matrix4.identity();
    }
    _currentScale[i] = 1.0;
    if (mounted) setState(() {});
    _updateLock();
  }

  bool get _isCurrentZoomed =>
      ((_currentScale[_mediaIndex] ?? 1.0) - 1.0).abs() > 0.05;

  void _toggleControls() {
    setState(() => _controlsVisible = !_controlsVisible);
  }

  void _updateLock() {
    final lock = _isPinching || _isCurrentZoomed;
    widget.onLockScroll?.call(lock);
  }

  void _onPointerDown(PointerDownEvent event) {
    _activePointers++;
    if (_activePointers > 1) {
      setState(() => _isPinching = true);
      _updateLock();
    }
  }

  void _onPointerUp(PointerUpEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      // تأخير بسيط حتى ينتهي InteractiveViewer من آخر إطار
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _resetZoom();
      });
    }
  }

  void _onPointerCancel(PointerCancelEvent event) {
    _activePointers = (_activePointers - 1).clamp(0, 10);
    if (_activePointers < 2 && _isPinching) {
      setState(() => _isPinching = false);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _resetZoom();
      });
    }
  }

  Widget _buildImagePage(int index, String path) {
    final isNetwork =
        path.startsWith('http://') || path.startsWith('https://');
    final imageWidget = isNetwork
        ? CachedNetworkImage(imageUrl: path, fit: BoxFit.contain)
        : Image.file(File(path), fit: BoxFit.contain);

    final zoomed = ((_currentScale[index] ?? 1.0) - 1.0).abs() > 0.05;

    return InteractiveViewer(
      transformationController: _zoomFor(index),
      maxScale: 10,
      minScale: 1,
      panEnabled: zoomed, // إصبع واحد = تحريك بعد التكبير فقط
      scaleEnabled: true, // إصبعان = تكبير
      boundaryMargin: const EdgeInsets.all(double.infinity),
      onInteractionEnd: (_) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          final s = _currentScale[index] ?? 1.0;
          if (s <= 1.05 || _activePointers < 2) {
            _resetZoom(index);
          }
        });
      },
      child: Center(child: imageWidget),
    );
  }

  Widget _buildVideoPage(int index) {
    final c = _videoControllers[index];
    if (c == null || !c.value.isInitialized) {
      return const Center(
        child: CircularProgressIndicator(color: Colors.white54),
      );
    }

    final zoomed = ((_currentScale[index] ?? 1.0) - 1.0).abs() > 0.05;
    final w = c.value.size.width;
    final h = c.value.size.height;

    return InteractiveViewer(
      transformationController: _zoomFor(index),
      maxScale: 8,
      minScale: 1,
      panEnabled: zoomed,
      scaleEnabled: true,
      boundaryMargin: const EdgeInsets.all(double.infinity),
      onInteractionEnd: (_) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          final s = _currentScale[index] ?? 1.0;
          if (s <= 1.05 || _activePointers < 2) {
            _resetZoom(index);
          }
        });
      },
      child: Center(
        child: FittedBox(
          fit: BoxFit.contain,
          child: SizedBox(
            width: w > 0 ? w : 16,
            height: h > 0 ? h : 9,
            child: VideoPlayer(c),
          ),
        ),
      ),
    );
  }

  Future<void> _warmupAround(int index) async {
    await _initVideoAt(index);
    // السابقة والتالية
    await _initVideoAt(index - 1);
    await _initVideoAt(index + 1);

    // صور مجاورة (إن لم تكن في الكاش)
    for (final i in [index - 1, index, index + 1]) {
      if (i < 0 || i >= _items.length) continue;
      final item = _items[i];
      if (item.kind != _MediaKind.image) continue;
      final p = item.path.trim();
      if (p.startsWith('http') && mounted) {
        precacheImage(CachedNetworkImageProvider(p), context);
      }
    }
  }
  @override
  void initState() {
    super.initState();
    _mediaIndex = widget.initialMediaIndex.clamp(0, (_items.length - 1).clamp(0, 1 << 30));
    _mediaController = PageController(initialPage: _mediaIndex);
    if (widget.isActive) _warmupAround(_mediaIndex);
  }

  @override
  void didUpdateWidget(covariant _PostPagerPage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.isActive != oldWidget.isActive) {
      if (widget.isActive) {
        _initVideoAt(_mediaIndex);
        _playCurrentVideo();
      } else {
        _pauseAllVideos();
      }
    }
  }

  Future<void> _initVideoAt(int index) async {
    if (index < 0 || index >= _items.length) return;
    final item = _items[index];
    if (item.kind != _MediaKind.video) return;
    if (_videoControllers.containsKey(index)) return;

    final path = item.path.trim();
    if (path.isEmpty) return;

    final isNetwork =
        path.startsWith('http://') || path.startsWith('https://');

    VideoPlayerController? c;

    try {
      if (isNetwork) {
        final file = await DefaultCacheManager().getSingleFile(path);
        if (!mounted) return;
        c = VideoPlayerController.file(
          file,
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else {
        c = VideoPlayerController.file(
          File(path),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      }

      await c.initialize();
      await c.setLooping(true);

      if (!mounted) {
        await c.dispose();
        return;
      }

      _videoControllers[index] = c;


      if (widget.isActive && index == _mediaIndex) {
        await c.seekTo(Duration.zero);
        await c.play();
      }

      if (mounted) setState(() {});
    } catch (e, st) {
      debugPrint('Pager video init failed: $e');
      debugPrintStack(stackTrace: st);
      await c?.dispose();

      // احتياطي: الشبكة مباشرة
      if (isNetwork) {
        try {
          final fallback = VideoPlayerController.networkUrl(
            Uri.parse(path),
            videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
          );
          await fallback.initialize();
          await fallback.setLooping(true);
          if (!mounted) {
            await fallback.dispose();
            return;
          }
          _videoControllers[index] = fallback;
          fallback.addListener(() {
            if (mounted) setState(() {});
          });
          if (widget.isActive && index == _mediaIndex) {
            await fallback.seekTo(Duration.zero);
            await fallback.play();
          }
          if (mounted) setState(() {});
        } catch (e2) {
          debugPrint('Pager fallback failed: $e2');
        }
      }
    }
  }

  void _playCurrentVideo() {
    final c = _videoControllers[_mediaIndex];
    if (c != null && c.value.isInitialized) {
      c.seekTo(Duration.zero);
      c.play();
    }
  }

  void _pauseAllVideos() {
    for (final c in _videoControllers.values) {
      if (c.value.isPlaying) c.pause();
    }
  }

  void _onMediaPageChanged(int index) {
    _pauseAllVideos();
    setState(() => _mediaIndex = index);
    _warmupAround(index).then((_) {
      if (widget.isActive) _playCurrentVideo();
    });
  }

  Future<void> _toggleLike() async {
    await _applyVote(widget.post, like: true);
    if (mounted) setState(() {});
    widget.onChanged?.call();
  }

  Future<void> _toggleDislike() async {
    await _applyVote(widget.post, like: false);
    if (mounted) setState(() {});
    widget.onChanged?.call();
  }

  Future<void> _openComments() async {
    if (_isNavigatingComments) return;
    _isNavigatingComments = true;
    await Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => CommentsScreen(post: widget.post)),
    );
    _isNavigatingComments = false;
    if (mounted) setState(() {});
    widget.onChanged?.call();
  }

  @override
  void dispose() {
    for (final c in _zoomControllers.values) {
      c.dispose();
    }
    for (final c in _videoControllers.values) {
      c.dispose();
    }
    _mediaController.dispose();
    super.dispose();
  }

  String _formatVotes(int votes) {
    if (votes >= 1000000) return '${(votes / 1000000).toStringAsFixed(1)}M';
    if (votes >= 1000) return '${(votes / 1000).toStringAsFixed(1)}k';
    return votes.toString();
  }
  @override
  Widget build(BuildContext context) {
    final post = widget.post;
    final items = _items;

    return Listener(
        onPointerDown: _onPointerDown,
        onPointerUp: _onPointerUp,
        onPointerCancel: _onPointerCancel,
        child: GestureDetector(
            onTap: _toggleControls,
            behavior: HitTestBehavior.translucent,
            child: Stack(
              fit: StackFit.expand,
              children: [
                // ===== الميديا =====
                Positioned.fill(
                  child: items.isEmpty
                      ? Container(color: Colors.black)
                      : PageView.builder(
                    controller: _mediaController,
                    physics: (_isPinching || _isCurrentZoomed)
                        ? const NeverScrollableScrollPhysics()
                        : const PageScrollPhysics(),
                    itemCount: items.length,
                    onPageChanged: (i) {
                      _resetZoom(_mediaIndex);
                      _onMediaPageChanged(i);
                    },
                    itemBuilder: (context, index) {
                      final item = items[index];
                      if (item.kind == _MediaKind.image) {
                        return _buildImagePage(index, item.path);
                      }
                      return _buildVideoPage(index);
                    },
                  ),
                ),

        // ===== شريط علوي =====
        Positioned(
          top: 0,
          left: 0,
          right: 0,
          child: AnimatedOpacity(
            opacity: _controlsVisible ? 1 : 0,
            duration: const Duration(milliseconds: 200),
            child: IgnorePointer(
              ignoring: !_controlsVisible,
              child: Container(
                width: double.infinity,
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Colors.black.withValues(alpha: 0.55),
                      Colors.transparent,
                    ],
                  ),
                ),
                child: SafeArea(
                  bottom: false,
                  child: Padding(
                    padding:
                    const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    child: Row(
                      children: [
                        _ViewerIconButton(
                          icon: Icons.close_rounded,
                          onTap: () => Navigator.of(context).pop(),
                        ),
                        const Spacer(),
                        if (widget.menuButton != null) widget.menuButton!,

                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),

        // ===== شريط سفلي (نفس الإخفاء) =====
        Positioned(
          left: 0,
          right: 0,
          bottom: 0,
          child: AnimatedOpacity(
            opacity: _controlsVisible ? 1 : 0,
            duration: const Duration(milliseconds: 200),
            child: IgnorePointer(
              ignoring: !_controlsVisible,
              child: Container(
                width: double.infinity,
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.bottomCenter,
                    end: Alignment.topCenter,
                    colors: [
                      Colors.black.withValues(alpha: 0.92),
                      Colors.black.withValues(alpha: 0.55),
                      Colors.transparent,
                    ],
                    stops: const [0.0, 0.55, 1.0],
                  ),
                ),
                child: SafeArea(
                  top: false,
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(14, 28, 14, 10),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (items.length > 1) ...[
                          Center(
                            child: _DotsIndicator(
                              count: items.length,
                              activeIndex: _mediaIndex,
                            ),
                          ),
                          const SizedBox(height: 10),
