                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 6),
                    decoration: BoxDecoration(
                      color: AppTeal.main.withValues(alpha: 0.08),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                          color: AppTeal.main.withValues(alpha: 0.3)),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                         Icon(Icons.check_circle,
                            color: AppTeal.main, size: 14),
                        const SizedBox(width: 6),
                        Text(
                          'تم الحفظ',
                          style: TextStyle(
                            color: AppTeal.shade700,
                            fontSize: 12,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const Spacer(),
                ] else
                  const Spacer(),
                // ElevatedButton(
                //   onPressed: longCtrl.text.trim().isEmpty
                //       ? null
                //       : () {
                //     setState(() {
                //       _simpleSelections[i] = longCtrl.text.trim();
                //     });
                //     FocusScope.of(context).unfocus();
                //   },
                //   style: ElevatedButton.styleFrom(
                //     backgroundColor: AppTeal.main,
                //     foregroundColor: Colors.white,
                //     disabledBackgroundColor: Colors.grey.shade200,
                //     disabledForegroundColor: Colors.grey.shade400,
                //     elevation: 0,
                //     padding: const EdgeInsets.symmetric(
                //         horizontal: 24, vertical: 10),
                //     shape: RoundedRectangleBorder(
                //       borderRadius: BorderRadius.circular(10),
                //     ),
                //   ),
                //   child: const Text(
                //     'تأكيد',
                //     style: TextStyle(
                //         fontWeight: FontWeight.w600, fontSize: 14),
                //   ),
                // ),
              ],
            ),
          ],
        );

// ===== Checkbox — اختيار واحد فقط =====
      case PollQuestionType.checkbox:
        return SizedBox(
          height: 150,
          child: Scrollbar(
            child: ListView.builder(
              itemCount: poll.options.length,
              itemBuilder: (context, index) {
                final isChecked = _setSelections[i]?.contains(index) ?? false;
                return GestureDetector(
                  onTap: () {
                    setState(() {
                      _setSelections[i] = {index};
                    });
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 180),
                    margin: const EdgeInsets.only(bottom: 8),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 14, vertical: 12),
                    decoration: BoxDecoration(
                      color: isChecked
                          ? AppTeal.main.withValues(alpha: 0.07)
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                        color: isChecked
                            ? AppTeal.main
                            : Colors.grey.shade300,
                        width: isChecked ? 1.5 : 1,
                      ),
                    ),
                    child: Row(
                      children: [
                        // مربع الاختيار
                        AnimatedContainer(
                          duration: const Duration(milliseconds: 180),
                          width: 22,
                          height: 22,
                          decoration: BoxDecoration(
                            color: isChecked ? AppTeal.main : Colors.transparent,
                            borderRadius: BorderRadius.circular(5),
                            border: Border.all(
                              color: isChecked
                                  ? AppTeal.main
                                  : Colors.grey.shade400,
                              width: 2,
                            ),
                          ),
                          child: isChecked
                              ? const Icon(
                            Icons.check,
                            size: 14,
                            color: Colors.white,
                          )
                              : null,
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            poll.options[index],
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: isChecked
                                  ? FontWeight.w600
                                  : FontWeight.normal,
                              color: isChecked
                                  ? AppTeal.shade800
                                  : null,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        );

// ===== Singel optin — اختيار متعدد =====
      case PollQuestionType.singelOptin:
        return SizedBox(
          height: 150,
          child: Scrollbar(
            child: ListView.builder(
              itemCount: poll.options.length,
              itemBuilder: (context, index) {
                final isSelected = _setSelections[i]?.contains(index) ?? false;
                return GestureDetector(
                  onTap: () {
                    setState(() {
                      _setSelections[i] ??= <int>{};
                      if (isSelected) {
                        _setSelections[i]!.remove(index);
                      } else {
                        _setSelections[i]!.add(index);
                      }
                    });
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 180),
                    margin: const EdgeInsets.only(bottom: 8),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 14, vertical: 12),
                    decoration: BoxDecoration(
                      color: isSelected
                          ? AppTeal.main.withValues(alpha: 0.07)
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                        color: isSelected
                            ? AppTeal.main
                            : Colors.grey.shade300,
                        width: isSelected ? 1.5 : 1,
                      ),
                    ),
                    child: Row(
                      children: [
                        // دائرة الاختيار
                        AnimatedContainer(
                          duration: const Duration(milliseconds: 180),
                          width: 22,
                          height: 22,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: isSelected ? AppTeal.main : Colors.transparent,
                            border: Border.all(
                              color: isSelected
                                  ? AppTeal.main
                                  : Colors.grey.shade400,
                              width: 2,
                            ),
                          ),
                          child: Center(
                            child: AnimatedContainer(
                              duration: const Duration(milliseconds: 180),
                              width: isSelected ? 10 : 0,
                              height: isSelected ? 10 : 0,
                              decoration: const BoxDecoration(
                                shape: BoxShape.circle,
                                color: Colors.white,
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            poll.options[index],
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: isSelected
                                  ? FontWeight.w600
                                  : FontWeight.normal,
                              color: isSelected
                                  ? AppTeal.shade800
                                  : null,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        );

    // ===== Dropdown =====
      case PollQuestionType.dropdown:
        final currentVal = _simpleSelections[i] as String?;
        final validVal = poll.options.contains(currentVal) ? currentVal : null;

        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: 30),
            DropdownButtonFormField<String>(
              decoration: InputDecoration(
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide(color: Colors.grey.shade300),
                ),
                enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide(color: Colors.grey.shade300),
                ),
                focusedBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide(color: AppTeal.main, width: 1.5),
                ),
                filled: true,
                fillColor: AppTeal.main.withValues(alpha: 0.04),
                contentPadding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 14,
                ),
                hintText: 'اختر خياراً...',
                hintStyle: TextStyle(color: Colors.grey.shade400, fontSize: 14),
              ),
              value: validVal,
              // مهم: isExpanded يمنع overflow
              isExpanded: true,
              icon:  Icon(Icons.keyboard_arrow_down_rounded,
                  color: AppTeal.main),
              dropdownColor: Theme.of(context).colorScheme.surface,
              borderRadius: BorderRadius.circular(12),
              items: poll.options.map((o) {
                return DropdownMenuItem<String>(
                  value: o,
                  child: Text(
                    o,
                    style: const TextStyle(fontSize: 14),
                  ),
                );
              }).toList(),
              onChanged: (v) {
                setState(() => _simpleSelections[i] = v);
              },
              // عرض القيمة المختارة بشكل مميز
              selectedItemBuilder: (context) {
                return poll.options.map((o) {
                  return Text(
                    o,
                    style:  TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                      color: AppTeal.main,
                    ),
                  );
                }).toList();
              },
            ),
            // مؤشر الاختيار
            if (validVal != null) ...[
              const SizedBox(height: 10),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                decoration: BoxDecoration(
                  color: AppTeal.main.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: AppTeal.main.withValues(alpha: 0.3)),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                     Icon(Icons.check_circle, color: AppTeal.main, size: 14),
                    const SizedBox(width: 6),
                    Text(
                      validVal,
                      style: TextStyle(
                        color: AppTeal.shade700,
                        fontSize: 12,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ],
        );

    // ===== Linear Scale =====
      case PollQuestionType.linearScale:
        return _buildScale(i, poll);

    // ===== Grid =====
      case PollQuestionType.grid:
        return _buildGrid(i, poll, multiSelect: false);

    // ===== Checkbox Grid =====
      case PollQuestionType.checkboxGrid:
        return _buildGrid(i, poll, multiSelect: true);

    // ===== Date =====
      case PollQuestionType.date:
        return _buildDateView(i, poll);

    // ===== Time =====
      case PollQuestionType.time:
        return _buildTimeView(i);
    }
  }

  // ==================== Scale ====================
  Widget _buildScale(int i, PollData poll) {
    final size = poll.scaleSize ?? 5;
    final style = poll.scaleStyle ?? LinearScaleStyle.numbers;
    final selected = _simpleSelections[i] as int?;

    switch (style) {
    // ==================== Numbers ====================
      case LinearScaleStyle.numbers:
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 20),
            Center(
              child: Wrap(
                spacing: 8,
                runSpacing: 6,
                alignment: WrapAlignment.center,
                children: List.generate(size, (j) {
                  final isSelected = selected == j;
                  return GestureDetector(
                    onTap: () => setState(() => _simpleSelections[i] = j),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 200),
                      width: 36,
                      height: 36,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: isSelected
                            ? AppTeal.main
                            : AppTeal.main.withValues(alpha: 0.06),
                        border: Border.all(
                          color: isSelected
                              ? AppTeal.main
                              : AppTeal.main.withValues(alpha: 0.25),
                          width: isSelected ? 2 : 1,
                        ),
                      ),
                      child: Center(
                        child: Text(
                          '${j + 1}',
                          style: TextStyle(
                            fontSize: isSelected ? 15 : 13,
                            fontWeight:
                            isSelected ? FontWeight.bold : FontWeight.normal,
                            color: isSelected
                                ? Colors.white
                                : AppTeal.shade700,
                          ),
                        ),
                      ),
                    ),
                  );
                }),
              ),
            ),
            const SizedBox(height: 16),
            AnimatedOpacity(
              opacity: selected != null ? 1 : 0,
              duration: const Duration(milliseconds: 200),
              child: Container(
                padding:
                const EdgeInsets.symmetric(horizontal: 20, vertical: 6),
                decoration: BoxDecoration(
                  color: AppTeal.main.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: Text(
                  selected != null ? '${selected + 1} / $size' : '-',
                  style:  TextStyle(
                    color: AppTeal.main,
                    fontWeight: FontWeight.w600,
                    fontSize: 13,
                  ),
                ),
              ),
            ),
            const SizedBox(height: 8),
          ],
        );

    // ==================== Line ====================
      case LinearScaleStyle.line:
        final double val = (selected ?? 0)
            .toDouble()
            .clamp(0.0, (size - 1).toDouble())
            .toDouble();
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 16),
            SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 6,
                thumbShape: const RoundSliderThumbShape(
                  enabledThumbRadius: 13,
                  elevation: 2,
                ),
                overlayShape:
                const RoundSliderOverlayShape(overlayRadius: 22),
                activeTrackColor: AppTeal.main,
                inactiveTrackColor: AppTeal.main.withValues(alpha: 0.15),
                thumbColor: Colors.white,
                overlayColor: AppTeal.main.withValues(alpha: 0.12),
              ),
              child: Slider(
                value: val,
                min: 0.0,
                max: (size - 1).toDouble(),
                divisions: size - 1,
                label: '${val.round() + 1}',
                onChanged: (v) =>
                    setState(() => _simpleSelections[i] = v.round()),
              ),
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text('Low',
                      style: TextStyle(
                          fontSize: 11, color: Colors.grey.shade500)),
                  Text(
                    selected != null ? '${selected + 1} / $size' : '- / $size',
                    style:  TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w700,
                      color: AppTeal.main,
                    ),
                  ),
                  Text('High',
                      style: TextStyle(
                          fontSize: 11, color: Colors.grey.shade500)),
                ],
              ),
            ),
            const SizedBox(height: 16),
          ],
        );

    // ==================== Stars ====================
      case LinearScaleStyle.stars:
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 20),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(size, (j) {
                final isFilled = selected != null && j <= selected;
                return GestureDetector(
                  onTap: () => setState(() => _simpleSelections[i] = j),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4),
                    child: Icon(
                      isFilled
                          ? Icons.star_rounded
                          : Icons.star_outline_rounded,
                      size: 34,
                      color: isFilled
                          ? AppTeal.main
                          : Colors.grey.shade400,
                    ),
                  ),
                );
              }),
            ),
            const SizedBox(height: 16),
          ],
        );

    // ==================== Slider ====================
      case LinearScaleStyle.slider:
        final double value = (selected ?? 0)
            .toDouble()
            .clamp(0.0, (size - 1).toDouble())
            .toDouble();
        final percent =
        size > 1 ? ((value / (size - 1)) * 100).round() : 0;

        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 16),
            SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 5,
                activeTrackColor: AppTeal.main,
                inactiveTrackColor: AppTeal.main.withValues(alpha: 0.15),
                thumbColor: AppTeal.main,
                overlayColor: AppTeal.main.withValues(alpha: 0.12),
                thumbShape:
                const RoundSliderThumbShape(enabledThumbRadius: 12),
              ),
              child: Slider(
                value: value,
                min: 0.0,
                max: (size - 1).toDouble(),
                divisions: size - 1,
                onChanged: (v) =>
                    setState(() => _simpleSelections[i] = v.round()),
              ),
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text('0%',
                      style: TextStyle(
                          fontSize: 12, color: Colors.grey.shade500)),
                  Text(
                    '$percent%',
                    style:  TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w800,
                      color: AppTeal.main,
                    ),
                  ),
                  Text('100%',
                      style: TextStyle(
                          fontSize: 12, color: Colors.grey.shade500)),
                ],
              ),
            ),
            const SizedBox(height: 16),
          ],
        );

    // ==================== Emoji ====================
      case LinearScaleStyle.emoji:
        final emojis = ['😡', '😕', '😐', '🙂', '😄'];
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 24),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: List.generate(size, (j) {
                final isSelected = selected == j;
                return GestureDetector(
                  onTap: () => setState(() => _simpleSelections[i] = j),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 200),
                        padding: const EdgeInsets.all(6),
                        decoration: BoxDecoration(
                          color: isSelected
                              ? AppTeal.main.withValues(alpha: 0.12)
                              : Colors.transparent,
                          shape: BoxShape.circle,
                        ),
                        child: AnimatedScale(
                          scale: isSelected ? 1.25 : 1.0,
                          duration: const Duration(milliseconds: 200),
                          child: Text(
                            emojis[j % emojis.length],
                            style: const TextStyle(fontSize: 28),
                          ),
                        ),
                      ),
                      const SizedBox(height: 6),
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 200),
                        width: isSelected ? 6 : 0,
                        height: 6,
                        decoration:  BoxDecoration(
                          color: AppTeal.main,
                          shape: BoxShape.circle,
                        ),
                      ),
                    ],
                  ),
                );
              }),
            ),
            const SizedBox(height: 24),
          ],
        );

    // ==================== Emoji 1 ====================
      case LinearScaleStyle.emoji1:
        final emojis = ['😭', '😢', '😐', '🙂', '😍'];
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 24),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: List.generate(size, (j) {
                final isSelected = selected == j;
                return GestureDetector(
                  onTap: () => setState(() => _simpleSelections[i] = j),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 200),
                        padding: const EdgeInsets.all(6),
                        decoration: BoxDecoration(
                          color: isSelected
                              ? AppTeal.main.withValues(alpha: 0.12)
                              : Colors.transparent,
                          shape: BoxShape.circle,
                        ),
                        child: AnimatedScale(
                          scale: isSelected ? 1.25 : 1.0,
                          duration: const Duration(milliseconds: 200),
                          child: Text(
                            emojis[j % emojis.length],
                            style: const TextStyle(fontSize: 28),
                          ),
                        ),
                      ),
                      const SizedBox(height: 6),
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 200),
                        width: isSelected ? 6 : 0,
                        height: 6,
                        decoration:  BoxDecoration(
                          color: AppTeal.main,
                          shape: BoxShape.circle,
                        ),
                      ),
                    ],
                  ),
                );
              }),
            ),
            const SizedBox(height: 24),
          ],
        );
    }
  }
  // ==================== Grid ====================
  Widget _buildGrid(int i, PollData poll, {required bool multiSelect}) {
    if (poll.gridRows.isEmpty || poll.gridColumns.isEmpty) {
      return const Center(child: Text('لا توجد بيانات للشبكة'));
    }

    // تأكد من تهيئة صحيحة الأبعاد
    final existing = _gridSelections[i];
    if (existing == null ||
        existing.length != poll.gridRows.length ||
        existing[0].length != poll.gridColumns.length) {
      _gridSelections[i] = List.generate(
        poll.gridRows.length,
            (_) => List<bool>.filled(poll.gridColumns.length, false),
      );
    }

    final sel = _gridSelections[i]!;

    if (!multiSelect) {
      // ===== Grid — يطابق PollGridWidget تماماً =====
      return SizedBox(
        height: 200,
        child: Scrollbar(
          thumbVisibility: true,
          child: SingleChildScrollView(
            scrollDirection: Axis.vertical,
            child: Scrollbar(
              thumbVisibility: true,
              notificationPredicate: (n) => n.depth == 1,
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: SizedBox(
                  width: (poll.gridColumns.length + 1) * 110.0,
                  child: DataTable(
                    columnSpacing: 24,
                    headingRowColor: WidgetStateProperty.all(
                      Theme.of(context).colorScheme.surfaceVariant,
                    ),
                    columns: [
                      const DataColumn(label: Text('')),
                      ...poll.gridColumns.map(
                            (c) => DataColumn(
                          label: Text(
                            c,
                            style: Theme.of(context).textTheme.bodyMedium,
                          ),
                        ),
                      ),
                    ],
                    rows: List.generate(poll.gridRows.length, (ri) {
                      return DataRow(
                        cells: [
                          DataCell(Text(
                            poll.gridRows[ri],
                            style: Theme.of(context).textTheme.bodyMedium,
                          )),
                          ...List.generate(poll.gridColumns.length, (ci) {
                            final isSelected = sel[ri][ci];
                            return DataCell(
                              GestureDetector(
                                onTap: () {
                                  setState(() {
                                    // ✅ grid: toggle حر — يمكن اختيار أكثر من عمود
                                    sel[ri][ci] = !sel[ri][ci];
                                  });
                                },
                                child: AnimatedScale(
                                  scale: isSelected ? 1.12 : 1.0,
                                  duration:
                                  const Duration(milliseconds: 180),
                                  curve: Curves.easeOut,
                                  child: AnimatedContainer(
                                    duration:
                                    const Duration(milliseconds: 220),
                                    width: 25,
                                    height: 25,
                                    decoration: BoxDecoration(
                                      shape: BoxShape.circle,
                                      color: isSelected
                                          ? AppTeal.main.withValues(alpha: 0.10)
                                          : Colors.transparent,
                                      border: Border.all(
                                        color: isSelected
                                            ? AppTeal.shade900
                                            : Theme.of(context)
                                            .colorScheme
                                            .outline
                                            .withValues(alpha: 0.6),
                                        width: isSelected ? 2.2 : 1.5,
                                      ),
                                    ),
                                    alignment: Alignment.center,
                                    child: AnimatedContainer(
                                      duration:
                                      const Duration(milliseconds: 180),
                                      width: isSelected ? 10 : 0,
                                      height: isSelected ? 10 : 0,
                                      decoration: BoxDecoration(
                                        shape: BoxShape.circle,
                                        color: AppTeal.shade700,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            );
                          }),
                        ],
                      );
                    }),
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    } else {
      // ===== Checkbox Grid — يطابق PollCheckboxGridWidget تماماً =====
      return LayoutBuilder(
        builder: (context, constraints) {
          final minTableWidth = constraints.maxWidth;
          final columnWidth =
          (minTableWidth / (poll.gridColumns.length + 1))
              .clamp(90, 140)
              .toDouble();

          return SizedBox(
            height: 180,
            child: Scrollbar(
              thumbVisibility: true,
              child: SingleChildScrollView(
                scrollDirection: Axis.vertical,
                child: SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: ConstrainedBox(
                    constraints: BoxConstraints(minWidth: minTableWidth),
                    child: DataTable(
                      columnSpacing: 0,
                      headingRowHeight: 44,
                      dataRowHeight: 52,
                      headingRowColor: WidgetStateProperty.all(
                        Theme.of(context).colorScheme.surfaceVariant,
                      ),
                      columns: [
                        DataColumn(
                          label: SizedBox(
                              width: columnWidth, child: const Text('')),
                        ),
                        ...poll.gridColumns.map(
                              (c) => DataColumn(
                            label: SizedBox(
                              width: columnWidth,
                              child: Center(
                                child: Text(
                                  c,
                                  textAlign: TextAlign.center,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ],
                      rows: List.generate(poll.gridRows.length, (ri) {
                        return DataRow(cells: [
                          DataCell(SizedBox(
                            width: columnWidth,
                            child: Text(poll.gridRows[ri]),
                          )),
                          ...List.generate(poll.gridColumns.length, (ci) {
                            final isSelected = sel[ri][ci];
                            return DataCell(
                              SizedBox(
                                width: columnWidth,
                                child: Center(
                                  child: InkWell(
                                    borderRadius: BorderRadius.circular(8),
                                    onTap: () {
                                      setState(() {
                                        // ✅ checkboxGrid: صف واحد → عمود واحد فقط
                                        for (int c = 0; c < sel[ri].length; c++) {
                                          sel[ri][c] = false;
                                        }
                                        sel[ri][ci] = true;
                                      });
                                    },
                                    child: AnimatedContainer(
                                      duration:
                                      const Duration(milliseconds: 200),
                                      width: 22,
                                      height: 22,
                                      alignment: Alignment.center,
                                      decoration: BoxDecoration(
                                        borderRadius:
                                        BorderRadius.circular(6),
                                        border: Border.all(
                                          color: isSelected
                                              ? AppTeal.shade900
                                              : Theme.of(context)
                                              .colorScheme
                                              .outline,
                                          width: 2,
                                        ),
                                      ),
                                      child: AnimatedScale(
                                        scale: isSelected ? 1.0 : 0.0,
                                        duration:  Duration(
                                            milliseconds: 150),
                                        curve: Curves.easeInOut,
                                        child: Icon(
                                          Icons.check,
                                          size: 18,
                                          color: AppTeal.main,
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            );
                          }),
                        ]);
                      }),
                    ),
                  ),
                ),
              ),
            ),
          );
        },
      );
    }
  }

  // ==================== Date ====================
  Widget _buildDateView(int i, PollData poll) {
    if (poll.dateConfig == null) {
      return const Center(child: Text('لم يُحدَّد تاريخ'));
    }

    final config = poll.dateConfig!;
    final monthNames = [
      'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
      'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر',
    ];

    // تأكد من وجود Map للتاريخ
    _dateSelections[i] ??= <int, Set<int>>{};
    for (final m in config.months) {
      _dateSelections[i]!.putIfAbsent(m, () => <int>{});
    }

    final monthsList = List<int>.from(config.months)..sort();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Text(
          ' ${config.year}',
          style: const TextStyle(
            fontWeight: FontWeight.bold,
            fontSize: 13,
            //color: AppTeal.main,
          ),
        ),
        const SizedBox(height: 0),
        ...monthsList.map((m) {
          final days = _dateSelections[i]![m]!;
          final daysInMonth = DateTime(config.year, m + 1, 0).day;

          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                monthNames[m - 1],
                style: const TextStyle(
                  fontWeight: FontWeight.w600,
                  fontSize: 13,
                  //color: AppTeal.main,
                ),
              ),
              const SizedBox(height: 8),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: List.generate(daysInMonth, (d) {
                  final day = d + 1;
                  final isSelected = days.contains(day);
                  return GestureDetector(
                    onTap: () {
                      setState(() {
                        if (isSelected) {
                          days.remove(day);
                        } else {
                          days.add(day);
                        }
                      });
                    },
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 150),
                      width: 36,
                      height: 36,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: isSelected ? AppTeal.main : Colors.grey.shade100,
                        border: Border.all(
                          color: isSelected
                              ? AppTeal.main
                              : Colors.grey.shade300,
                        ),
                      ),
                      child: Center(
                        child: Text(
                          '$day',
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: isSelected
                                ? FontWeight.bold
                                : FontWeight.normal,
                            color:
                            isSelected ? Colors.white : Colors.black87,
                          ),
                        ),
                      ),
                    ),
                  );
                }),
              ),
              const SizedBox(height: 14),
            ],
          );
        }),
      ],
    );
  }

  // ==================== Time ====================
  Widget _buildTimeView(int i) {
    final selected = _timeSelections[i];

    return Column(

      children: [
        const SizedBox(height: 0),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 0),
          decoration: BoxDecoration(
            //color: AppTeal.main.withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: AppTeal.main.withValues(alpha: 0.3)),
          ),
          child: Text(
            selected != null
                ? '${selected.hour.toString().padLeft(2, '0')}:${selected.minute.toString().padLeft(2, '0')}'
                : '--:--',
            style: TextStyle(
              fontSize: 25,
              fontWeight: FontWeight.bold,
              letterSpacing: 4,
              color: AppTeal.main,
            ),
          ),
        ),
        const SizedBox(height: 24),
        Row(

            children: [
              SizedBox(width:180 ,),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  //backgroundColor: AppTeal.main,
                  //foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 0),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                onPressed: () async {
                  final picked = await showTimePicker(
                    context: context,
                    initialTime: selected ?? TimeOfDay.now(),
                  );
                  if (picked != null) {
                    setState(() => _timeSelections[i] = picked);
                  }
                },
                icon: const Icon(Icons.access_time),
                label: Text(selected != null ? 'تغيير الوقت' : 'اختيار وقت'),
              )]),
