  Future<void> _saveEditedComment(_Comment comment) async {
    final newText = _commentController.text.trim();
    if (newText.isEmpty) return;

    try {
      await _updatePostComments((comments) {
        _mutateCommentMap(comments, comment.id, (node) {
          node['text'] = newText;
          node['isEdited'] = true;
        });
      });
      if (!mounted) return;
      setState(() {
        _findCommentLocal(widget.post.comments, comment.id, (c) {
          c.text = newText;
          c.isEdited = true;
        });
        _editingComment = null;
        _commentController.clear();
      });
      FocusScope.of(context).unfocus();
      final uid = FirebaseAuth.instance.currentUser?.uid;
      if (uid != null) {
        unawaited(FirebaseFirestore.instance
            .collection('users')
            .doc(uid)
            .collection('authored_comments')
            .doc(comment.id)
            .set({'text': newText, 'isEdited': true}, SetOptions(merge: true)));
      }
    } catch (e) {
      debugPrint('Edit comment failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تعديل التعليق، حاول مجددًا')),
      );
    }
  }

  Future<void> _deleteComment(_Comment comment) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => Directionality(
        textDirection: TextDirection.ltr,
        child: AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
          title: const Text('حذف التعليق؟'),
          content: const Text('سيتم حذف التعليق وكل الردود عليه نهائيًا.'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFDC2626),
                foregroundColor: Colors.white,
              ),
              onPressed: () => Navigator.pop(context, true),
              child: const Text('حذف'),
            ),
          ],
        ),
      ),
    );

    if (confirmed != true) return;

    try {
      await _updatePostComments((comments) {
        _removeCommentMap(comments, comment.id);
      });
      if (!mounted) return;
      setState(() {
        _removeCommentLocal(widget.post.comments, comment.id);
      });
      final uid = comment.authorId?.trim();
      if (uid != null && uid.isNotEmpty) {
        unawaited(FirebaseFirestore.instance
            .collection('users')
            .doc(uid)
            .collection('authored_comments')
            .doc(comment.id)
            .delete());
      }
    } catch (e) {
      debugPrint('Delete comment failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حذف التعليق، حاول مجددًا')),
      );
    }
  }

  Future<void> _reportComment(_Comment comment) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final postId = widget.post.id?.trim();
    if (postId == null || postId.isEmpty) return;

    final ownerId = comment.authorId?.trim();
    if (ownerId != null && ownerId.isNotEmpty && ownerId == user.uid) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('لا يمكنك تبليغ محتواك')),
      );
      return;
    }

    final already = await hasCommunityReport(
      type: CommunityReportType.comment,
      targetId: comment.id,
    );
    if (!mounted) return;

    if (already) {
      setState(() => _hiddenCommentIds.add(comment.id));
      await showReportSubmittedSheet(
        context,
        type: CommunityReportType.comment,
        ownerId: ownerId,
        ownerName: comment.author,
        ownerPhotoUrl: comment.authorPhotoUrl,
        alreadyReported: true,
      );
      return;
    }

    final result = await showCommunityReportSheet(
      context,
      type: CommunityReportType.comment,
    );
    if (result == null || !mounted) return;

    try {
      await submitCommunityReport(
        type: CommunityReportType.comment,
        targetId: comment.id,
        parentId: postId,
        ownerId: ownerId,
        ownerName: comment.author,
        reason: result.reasonId,
        details: result.details,
        snapshot: communityReportSnapshotFromComment(comment),
      );

      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('hidden_comments')
          .doc(comment.id)
          .set({
        'commentId': comment.id,
        'postId': postId,
        'source': 'report',
        'hiddenAt': FieldValue.serverTimestamp(),
      });

      if (!mounted) return;
      setState(() => _hiddenCommentIds.add(comment.id));
      await showReportSubmittedSheet(
        context,
        type: CommunityReportType.comment,
        ownerId: ownerId,
        ownerName: comment.author,
        ownerPhotoUrl: comment.authorPhotoUrl,
      );
    } catch (e) {
      debugPrint('Report comment failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(messageForCommunityReportError(e))),
      );
    }
  }

