  Future<void> _repostComment(_Comment comment) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final original = widget.post;
    final originalId = original.id?.trim();
    if (originalId == null || originalId.isEmpty) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إعادة نشر هذا التعليق')),
      );
      return;
    }

    await Future<void>.delayed(const Duration(milliseconds: 120));
    if (!mounted) return;

    final draft = await Navigator.of(context, rootNavigator: true).push<_RepostDraft>(
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (_) => _RepostComposePage(
          original: original,
          comment: comment,
        ),
      ),
    );
    if (!mounted || draft == null) return;

    String? authorPhotoUrl;
    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      authorPhotoUrl = userDoc.data()?['profileImageUrl']?.toString();
    } catch (_) {}
    if (!mounted) return;

    final authorName = (user.displayName ?? '').trim().isNotEmpty
        ? user.displayName!.trim()
        : 'طالب UniSpace';

    final bodyPreview = comment.text.trim();
    final shortBody = bodyPreview.length > 180
        ? '${bodyPreview.substring(0, 180)}…'
        : bodyPreview;

    try {
      await FirebaseFirestore.instance.collection('community_posts').add({
        'authorId': user.uid,
        'authorName': authorName,
        'authorPhotoUrl': authorPhotoUrl,
        'title': draft.title,
        'body': draft.body,
        'searchKeywords': buildSearchKeywords(
          title: draft.title,
          body: draft.body,
          author: authorName,
        ),
        'status': 'published',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
        'isRepost': true,
        'repostOf': {
          'postId': originalId,
          'authorId': original.authorId,
          'authorName': original.author,
          'authorPhotoUrl': original.authorPhotoUrl,
          'title': original.title.trim(),
          'body': shortBody,
          'kind': 'comment',
          'commentId': comment.id,
          'commentAuthor': comment.author,
          'commentAuthorId': comment.authorId,
          'commentAuthorPhotoUrl': comment.authorPhotoUrl,
          'commentText': comment.text,
          'commentMediaUrl': comment.mediaUrl,
          'commentMediaType': comment.mediaType,
        },
        'imageUrls': <String>[],
        'videoUrls': <String>[],
        'pollSlides': <Map<String, dynamic>>[],
        'polls': <Map<String, dynamic>>[],
        'tags': <String>[],
        'votes': 0,
        'upvotedBy': <String>[],
        'downvotedBy': <String>[],
        'commentsCount': 0,
        'version': 1,
      });

      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تمت إعادة نشر التعليق')),
      );
    } catch (e) {
      debugPrint('Repost comment failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إعادة النشر، حاول مجددًا')),
      );
    }
  }

  Future<void> _toggleCommentLike(_Comment comment) async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;

    try {
      await _updatePostComments((comments) {
        _mutateCommentMap(comments, comment.id, (node) {
          final upvotedBy = _stringList(node['upvotedBy']);
          final downvotedBy = _stringList(node['downvotedBy']);
          int votes = (node['votes'] as num?)?.toInt() ?? 0;
          if (upvotedBy.contains(uid)) {
            upvotedBy.remove(uid);
            votes -= 1;
          } else {
            upvotedBy.add(uid);
            votes += 1;
            if (downvotedBy.contains(uid)) {
              downvotedBy.remove(uid);
              votes += 1;
            }
          }
          node['upvotedBy'] = upvotedBy;
          node['downvotedBy'] = downvotedBy;
          node['votes'] = votes;
        });
      });
      if (!mounted) return;

      var likedNow = false;
      setState(() {
        _findCommentLocal(widget.post.comments, comment.id, (c) {
          if (c.upvoted) {
            c.upvoted = false;
            c.votes -= 1;
          } else {
            likedNow = true;
            c.upvoted = true;
            c.votes += 1;
            if (c.downvoted) {
              c.downvoted = false;
              c.votes += 1;
            }
          }
        });
      });
      HapticFeedback.lightImpact();
      if (likedNow) {
        unawaited(pushNotificationFromMe(
          toUid: comment.authorId ?? '',
          type: 'like_comment',
          message: 'أعجب بتعليقك',
          postId: widget.post.id,
          commentId: comment.id,
          docId: 'like_c_${comment.id}_$uid',
        ));
      }
    } catch (e) {
      debugPrint('Toggle comment like failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('فشل الإعجاب: $e')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final allComments = _withoutBlocked(widget.post.comments);
    final filteredComments = _searchQuery.isEmpty
        ? allComments
        : allComments
        .where((c) => _commentMatchesQuery(c, _searchQuery))
        .toList();



    return Directionality(
      textDirection: TextDirection.ltr,
      child: Scaffold(
        resizeToAvoidBottomInset: true,
        backgroundColor: Theme.of(context).colorScheme.surface,
        appBar: PreferredSize(
          preferredSize: const Size.fromHeight(kToolbarHeight),
          child: AnimatedBuilder(
            animation: _searchAnim,
            builder: (context, _) {
              final t = _CommentTheme.of(context);
              final progress = _searchAnim.value; // 0 → 1

              return Container(
                color: t.pageBg,
                padding: const EdgeInsets.symmetric(horizontal: 8),
                child: SafeArea(
                  bottom: false,
                  child: SizedBox(
                    height: kToolbarHeight,
                    child: Stack(
                      alignment: Alignment.center,
                      children: [
                        // ===== الوضع العادي (عنوان + أزرار) =====
                        Opacity(
                          opacity: (1 - progress).clamp(0.0, 1.0),
                          child: IgnorePointer(
                            ignoring: progress > 0.05,
                            child: Row(
                              children: [
                                // زر الرجوع
                                InkWell(
                                  onTap: () => Navigator.maybePop(context),
                                  borderRadius: BorderRadius.circular(14),
                                  child: Container(
                                    width: 38,
                                    height: 38,
                                    decoration: BoxDecoration(
                                      color: t.cardBg,
                                      borderRadius: BorderRadius.circular(14),
                                      border: Border.all(color: t.cardBorder),
                                    ),
                                    child: Icon(
                                      Icons.arrow_back_ios_new_rounded,
                                      size: 17,
                                      color: t.textPrimary,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: Text(
                                    'Comments',
                                    style: TextStyle(
                                      color: t.textPrimary,
                                      fontSize: 18,
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                ),
                                // أيقونة البحث (نقطة الانطلاق)
                                IconButton(
                                  icon: Icon(Icons.search_rounded, color: t.textPrimary),
                                  onPressed: () {
                                    setState(() => _isSearching = true);
                                    _searchAnimController.forward();
                                  },
                                ),
                              ],
                            ),
                          ),
                        ),

                        // ===== حقل البحث المتمدد من الأيقونة =====
                        if (progress > 0.01)
                          Positioned.fill(
                            child: Padding(
                              padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
                              child: LayoutBuilder(
                                builder: (context, constraints) {
                                  final fullWidth = constraints.maxWidth;
                                  final w = (fullWidth * progress).clamp(0.0, fullWidth);

                                  return Align(
                                    alignment: Alignment.centerRight,
                                    child: SizedBox(
                                      width: w,
                                      height: 42,
                                      child: ClipRect(
                                        child: OverflowBox(
                                          alignment: Alignment.centerRight,
                                          minWidth: fullWidth,
                                          maxWidth: fullWidth,
                                          minHeight: 42,
                                          maxHeight: 42,
                                          child: SizedBox(
                                            width: fullWidth,
                                            height: 42,
                                            child: Material(
                                              color: Colors.transparent, // ← لا خلفية إضافية
                                              child: TextField(
                                                controller: _searchController,
                                                autofocus: progress > 0.9,
                                                style: TextStyle(
                                                  color: t.textPrimary,
                                                  fontSize: 15,
                                                ),
                                                decoration: InputDecoration(
                                                  hintText: 'Search comments...',
                                                  hintStyle: TextStyle(color: t.textMuted, fontSize: 15),
                                                  filled: true,
                                                  fillColor: t.inputBg, // الخلفية الوحيدة
                                                  contentPadding: const EdgeInsets.symmetric(horizontal: 4, vertical: 10),
                                                  border: OutlineInputBorder(
                                                    borderRadius: BorderRadius.circular(21),
                                                    borderSide: BorderSide.none,
                                                  ),
                                                  enabledBorder: OutlineInputBorder(
                                                    borderRadius: BorderRadius.circular(21),
                                                    borderSide: BorderSide.none,
                                                  ),
                                                  focusedBorder: OutlineInputBorder(
                                                    borderRadius: BorderRadius.circular(21),
                                                    borderSide: BorderSide.none,
                                                  ),
                                                  prefixIcon: Icon(Icons.search_rounded, size: 20, color: t.textMuted),
                                                  suffixIcon: IconButton(
                                                    visualDensity: VisualDensity.compact,
                                                    icon: Icon(Icons.close_rounded, size: 20, color: t.textMuted),
                                                    onPressed: () async {
                                                      FocusScope.of(context).unfocus();
                                                      await _searchAnimController.reverse();
                                                      if (!mounted) return;
                                                      setState(() {
                                                        _isSearching = false;
                                                        _searchQuery = '';
                                                        _searchController.clear();
                                                      });
                                                    },
                                                  ),
                                                ),
                                                onChanged: _onSearchChanged,
                                              ),
                                            ),
                                          ),
                                        ),
                                      ),
                                    ),
                                  );
                                },
                              ),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        body: CustomScrollView(
          controller: _scrollController,
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(2, 8, 2, 10),
                child: _PostCard(
                  post: widget.post,
                  onChanged: () => setState(() {}),
                  onDelete: _deletePostAndPop,
                  isInsideComments: true,
                  onHidden: () {
                    Navigator.of(context).pop(true);
                  },
                ),
              ),
            ),
            if (filteredComments.isEmpty)
              SliverToBoxAdapter(
                child: _EmptyCommentsState(isSearching: _searchQuery.isNotEmpty),
              )
            else
              SliverPadding(
                padding: const EdgeInsets.fromLTRB(2, 4, 2, 0),
                sliver: SliverList(
                  delegate: SliverChildBuilderDelegate(
                        (context, index) {
                      final comment = filteredComments[index];
                      return Padding(
                        padding: EdgeInsets.only(
                          bottom: index == filteredComments.length - 1 ? 0 : 12,
                        ),
                        child: _CommentThreadCard(
                          comment: comment,
                          actions: _CommentActionsCallbacks(
                            onReply: (c) {
                              setState(() {
                                _replyTo = c;
                                _commentController.clear();
                              });
                              _composerFocusNode.requestFocus();
                            },
                            onEdit: _editComment,
                            onDelete: _deleteComment,
                            onReport: _reportComment,
                            onBlock: _blockCommentAuthor,
                            onRepost: _repostComment,
                            onToggleLike: _toggleCommentLike,
                            onToggleDownvote: _toggleCommentDownvote,
                            isCollapsed: _isCommentCollapsed,
                            onToggleCollapse: _toggleCommentCollapse,
                            keyFor: _keyForComment,
                            onJumpToParent: _scrollToComment,
                            onOpenThread: _openThread, // NEW
                            onSave: _toggleSaveComment,
                            isCommentSaved: (id) => _savedCommentIds.contains(id),

                          ),
                        ),
                      );
                    },
                    childCount: filteredComments.length,
                  ),
                ),
              ),
            const SliverToBoxAdapter(child: SizedBox(height: 116)),
          ],
        ),
        bottomNavigationBar: SafeArea(
          top: false,
          child: AnimatedPadding(
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOut,
            padding: EdgeInsets.only(bottom: MediaQuery.of(context).viewInsets.bottom),
            child:_canComment
                ? _CommentComposer(
              controller: _commentController,
              replyTo: _replyTo,
              onCancelReply: () => setState(() => _replyTo = null),
              onSubmit: _submitComment,
              attachment: _attachment,           // NEW
              onPickImage: _pickCommentImage,    // NEW
              onPickVideo: _pickCommentVideo,    // NEW
              onMediaInserted: _onMediaInserted,    // NEW
              onRemoveAttachment: _removeAttachment, // NEW
              focusNode: _composerFocusNode,
              editingComment: _editingComment,
              onCancelEdit: _cancelEdit,

            )
                  : Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
          child: Text(
            'التعليق على منشورات هذا الحساب مقيّد.',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: Theme.of(context).hintColor,
              fontWeight: FontWeight.w600,
            ),
          ),
        ),
          ),
        ),
      ),
    );
  }

  Future<void> _submitComment() async {
    final postId = widget.post.id;
    if (postId == null || postId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تحديد المنشور')),
      );
      return;
    }

    if (_editingComment != null) {
      await _saveEditedComment(_editingComment!);
      return;
    }

    final replyTo = _replyTo;
    final attachment = _attachment; // NEW
    if (!_canComment) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('التعليق غير مسموح على هذا المنشور')),
      );
      return;
    }
    await _postComment(
      context: context,
      postId: postId,
      text: _commentController.text,
      replyTo: replyTo,
      attachment: attachment,
      onSuccess: (newComment, isReply) {
        if (!mounted) return;
        setState(() {
          if (isReply) {
            _findCommentLocal(widget.post.comments, replyTo!.id, (c) {
              c.replies.insert(0, newComment);
            });
          } else {
            widget.post.comments.insert(0, newComment);
          }
          _replyTo = null;
          _attachment = null; // NEW
          _commentController.clear();
        });
        FocusScope.of(context).unfocus();
      },
    );
  }
}
class _EmptyCommentsState extends StatelessWidget {
  const _EmptyCommentsState({required this.isSearching});
  final bool isSearching;

  @override
  Widget build(BuildContext context) {
    final t = _CommentTheme.of(context);
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 48, horizontal: 24),
      child: Column(
        children: [
          Icon(
            isSearching ? Icons.search_off_rounded : Icons.mode_comment_outlined,
            size: 38,
            color: t.textFaint,
          ),
          const SizedBox(height: 10),
          Text(
            isSearching ? 'لا توجد نتائج مطابقة' : 'لا توجد تعليقات بعد',
            style: TextStyle(color: t.textMuted, fontSize: 13.5, fontWeight: FontWeight.w700),
          ),
          if (!isSearching) ...[
            const SizedBox(height: 4),
            Text(
              'كن أول من يعلّق على هذا المنشور',
              style: TextStyle(color: t.textFaint, fontSize: 12, fontWeight: FontWeight.w500),
            ),
          ],
        ],
      ),
    );
  }
}

class _CommentComposer extends StatefulWidget {
  final TextEditingController controller;
  final _Comment? replyTo;
  final VoidCallback onCancelReply;
  final Future<void> Function() onSubmit; // FIX: بقات Future بدل VoidCallback باش نقدرو نستناو نهايتها
  final CommentAttachment? attachment;
  final VoidCallback onPickImage;
  final VoidCallback onPickVideo;
  final void Function(KeyboardInsertedContent) onMediaInserted;
  final VoidCallback onRemoveAttachment;
  final FocusNode focusNode;
  final _Comment? editingComment;
  final VoidCallback? onCancelEdit;

  const _CommentComposer({
    required this.controller,
    required this.replyTo,
    required this.onCancelReply,
    required this.onSubmit,
    required this.attachment,
    required this.onPickImage,
    required this.onPickVideo,
    required this.onMediaInserted,
    required this.onRemoveAttachment,
    required this.focusNode,
    this.editingComment,
    this.onCancelEdit,
  });

  @override
  State<_CommentComposer> createState() => _CommentComposerState();
}

class _CommentComposerState extends State<_CommentComposer> {
  String? _avatarUrl;
  bool _isSubmitting = false;

  @override
  void initState() {
    super.initState();
    _loadAvatar();
  }
  Future<void> _handleSubmit() async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      await widget.onSubmit();
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }
  Future<void> _loadAvatar() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    String? url;

    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final saved = doc.data()?['profileImageUrl']?.toString().trim();
      if (saved != null && saved.isNotEmpty) {
        url = saved;
      }
    } catch (e) {
      debugPrint('Load comment avatar failed: $e');
    }

    // صورة حساب Google / الإيميل
    url ??= user.photoURL?.trim();
    if (url != null && url.isEmpty) url = null;

    if (mounted && url != null) {
      setState(() => _avatarUrl = url);
    }
  }

  @override
  Widget build(BuildContext context) {
    final t = _CommentTheme.of(context);
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final hasPhoto = _avatarUrl != null && _avatarUrl!.trim().isNotEmpty;

    final sendActiveColor =
    isDark ? const Color(0xFF3B82F6) : const Color(0xFF2563EB);
    final sendDisabledColor =
    isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0);

    return Container(
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      decoration: BoxDecoration(
        color: t.cardBg,
        border: Border(
          top: BorderSide(
            color: t.cardBorder.withValues(alpha: isDark ? 0.5 : 0.7),
            width: 0.6,
          ),
        ),
        boxShadow: isDark
            ? []
            : [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.04),
            blurRadius: 14,
            offset: const Offset(0, -4),
          ),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (widget.editingComment != null) ...[
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: t.inputBg,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: t.inputBorder),
              ),
              child: Row(
                children: [
                  Icon(Icons.edit_rounded, size: 16, color: t.textMuted),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      'تعديل التعليق',
                      style: TextStyle(
                        color: t.textPrimary,
                        fontWeight: FontWeight.w800,
                        fontSize: 12.5,
                      ),
                    ),
                  ),
                  InkWell(
                    onTap: widget.onCancelEdit,
                    child: Icon(Icons.close_rounded, size: 18, color: t.textMuted),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 8),
          ] else if (widget.replyTo != null) ...[
            _ReplyBanner(
              replyTo: widget.replyTo!,
              onCancel: widget.onCancelReply,
              t: t,
            ),
            const SizedBox(height: 8),
          ],
          if (widget.attachment != null) ...[
            _AttachmentPreview(
              attachment: widget.attachment!,
              onRemove: widget.onRemoveAttachment,
            ),
            const SizedBox(height: 8),
          ],
          Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              // ===== أفاتار البروفايل =====
              Padding(
                padding: const EdgeInsets.only(bottom: 3),
                child: Container(
                  width: 34,
                  height: 34,
                  clipBehavior: Clip.antiAlias,
                  decoration: BoxDecoration(
                    color: t.avatarBg,
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: isDark
                          ? Colors.white.withValues(alpha: 0.08)
                          : Colors.black.withValues(alpha: 0.06),
                      width: 1,
                    ),
                  ),
                  child: hasPhoto
                      ? Image.network(
                    _avatarUrl!,
                    fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Icon(
                      Icons.person_rounded,
                      size: 18,
                      color: t.textMuted,
                    ),
                    loadingBuilder: (context, child, progress) {
                      if (progress == null) return child;
                      return Center(
                        child: SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(
                            strokeWidth: 1.5,
                            color: t.textMuted,
                          ),
                        ),
                      );
                    },
                  )
                      : Icon(
                    Icons.person_rounded,
                    size: 18,
                    color: t.textMuted,
                  ),
                ),
              ),

              const SizedBox(width: 10),

              // ===== حقل الكتابة =====
              Expanded(
                child: AnimatedBuilder(
                  animation: widget.focusNode,
                  builder: (context, _) {
                    final focused = widget.focusNode.hasFocus;
                    return AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      constraints: const BoxConstraints(
                        minHeight: 44,
                        maxHeight: 130,
                      ),
                      decoration: BoxDecoration(
                        color: t.inputBg,
                        borderRadius: BorderRadius.circular(22),
                        border: Border.all(
                          color: focused
                              ? sendActiveColor.withValues(alpha: 0.45)
                              : t.inputBorder,
                          width: focused ? 1.3 : 1,
                        ),
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          Expanded(
                            child: TextField(
                              controller: widget.controller,
                              focusNode: widget.focusNode,
                              keyboardType: TextInputType.multiline,
                              textInputAction: TextInputAction.newline,
                              maxLines: null,
                              minLines: 1,
                              textAlignVertical: TextAlignVertical.center,
                              contentInsertionConfiguration:
                              ContentInsertionConfiguration(
                                onContentInserted: widget.onMediaInserted,
                                allowedMimeTypes: const [
                                  'image/gif',
                                  'image/png',
                                  'image/jpeg',
                                  'image/webp',
                                ],
                              ),
                              decoration: InputDecoration(
                                hintText: widget.editingComment != null
                                    ? 'عدّل التعليق...'
                                    : widget.replyTo == null
                                    ? 'أضف تعليقاً...'
                                    : 'أضف رداً...',
                                hintStyle: TextStyle(
                                  color: t.textMuted,
                                  fontSize: 13.5,
                                ),
                                border: InputBorder.none,
                                isDense: true,
                                contentPadding: const EdgeInsets.symmetric(
                                  horizontal: 16,
                                  vertical: 12,
                                ),
                              ),
                              style: TextStyle(
                                fontSize: 13.5,
                                color: t.textPrimary,
                                height: 1.35,
                              ),
                            ),
                          ),
                          _InlineMediaIcon(
                            icon: Icons.image_outlined,
                            onTap: widget.onPickImage,
                            t: t,
                          ),
                          _InlineMediaIcon(
                            icon: Icons.videocam_outlined,
                            onTap: widget.onPickVideo,
                            t: t,
                          ),
                          const SizedBox(width: 6),
                        ],
                      ),
                    );
                  },
                ),
              ),

              const SizedBox(width: 8),

              // ===== زر الإرسال =====
              // ===== زر الإرسال =====
              ValueListenableBuilder<TextEditingValue>(
                valueListenable: widget.controller,
                builder: (context, value, _) {
                  // FIX: الزر معطل أثناء النشر، حتى لو النص مازال موجود
                  final canSend = !_isSubmitting &&
                      (value.text.trim().isNotEmpty || widget.attachment != null);

                  return Padding(
                    padding: const EdgeInsets.only(bottom: 1),
                    child: AnimatedScale(
                      scale: canSend ? 1.0 : 0.92,
                      duration: const Duration(milliseconds: 160),
                      curve: Curves.easeOut,
                      child: Material(
                        color: Colors.transparent,
                        child: InkWell(
                          onTap: canSend ? _handleSubmit : null, // FIX: _handleSubmit بدل widget.onSubmit مباشرة
                          borderRadius: BorderRadius.circular(22),
                          child: AnimatedContainer(
                            duration: const Duration(milliseconds: 160),
                            width: 42,
                            height: 42,
                            decoration: BoxDecoration(
                              color: canSend
                                  ? sendActiveColor
                                  : sendDisabledColor,
                              shape: BoxShape.circle,
                            ),
                            // NEW: مؤشر تحميل صغير بدل السهم أثناء النشر
                            child: _isSubmitting
                                ? const Padding(
                              padding: EdgeInsets.all(11),
                              child: CircularProgressIndicator(
                                strokeWidth: 2,
                                color: Colors.white,
                              ),
                            )
                                : Icon(
                              Icons.arrow_upward_rounded,
                              size: 20,
                              color: canSend
                                  ? Colors.white
                                  : const Color(0xFF94A3B8),
                            ),
                          ),
                        ),
                      ),
                    ),
                  );
                },
              ),
            ],
          ),
        ],
      ),
    );
  }
}

class CommentTile extends StatefulWidget {
  final _Comment comment;
  final int depth;
  final _CommentActionsCallbacks actions;


  const CommentTile({
    super.key,
    required this.comment,
    required this.depth,
    required this.actions,

  });

  @override
  State<CommentTile> createState() => _CommentTileState();
}

class _CommentTileState extends State<CommentTile> {
  bool get _isReply => widget.depth > 0;
  bool _pressed = false;
  bool _textSelectable = false;

  bool get _isOwner {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final authorId = widget.comment.authorId;
    return uid != null && authorId != null && uid == authorId;
  }

  @override
  void initState() {
    super.initState();
    final id = widget.comment.authorId?.trim() ?? '';
    if (id.isNotEmpty) AuthorProfiles.ensure(id);
  }

  PopupMenuItem<String> _menuItem({
    required String value,
    required IconData icon,
    required String label,
    required Color color,
  }) {
    return PopupMenuItem<String>(
      value: value,
      child: Row(
        textDirection: TextDirection.ltr,
        children: [
          Icon(icon, size: 19, color: color),
          const SizedBox(width: 10),
          Text(
            label,
            style: TextStyle(color: color, fontSize: 13.5, fontWeight: FontWeight.w700),
          ),
        ],
      ),
    );
  }

  Future<void> _showCommentMenu(BuildContext context, Offset globalPosition) async {
    final t = _CommentTheme.of(context);

    final overlayObject = Overlay.of(context).context.findRenderObject();
    if (overlayObject is! RenderBox) return;
    final overlay = overlayObject;

    final position = RelativeRect.fromLTRB(
      globalPosition.dx,
      globalPosition.dy,
      overlay.size.width - globalPosition.dx,
      overlay.size.height - globalPosition.dy,
    );

    final selected = await showMenu<String>(
      context: context,
      position: position,
      color: t.sheetBg,
      elevation: 8,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: BorderSide(color: t.cardBorder),
      ),
      constraints: const BoxConstraints(minWidth: 180),
      items: [
        _menuItem(value: 'reply', icon: Icons.reply_rounded, label: 'رد', color: t.textPrimary),
        _menuItem(
          value: 'save',
          icon: (widget.actions.isCommentSaved?.call(widget.comment.id) ?? false)
              ? Icons.bookmark_rounded
              : Icons.bookmark_border,
          label: (widget.actions.isCommentSaved?.call(widget.comment.id) ?? false)
              ? 'إلغاء الحفظ'
              : 'حفظ',
          color: t.textPrimary,
        ),
        if (_isOwner)
          _menuItem(value: 'edit', icon: Icons.edit_rounded, label: 'تعديل', color: t.textPrimary),
        _menuItem(value: 'repost', icon: Icons.repeat_rounded, label: 'إعادة نشر', color: t.textPrimary),
        _menuItem(value: 'share', icon: Icons.ios_share_rounded, label: 'مشاركة', color: t.textPrimary),
        _menuItem(value: 'copy', icon: Icons.copy_rounded, label: 'نسخ النص', color: t.textPrimary),
        if (!_isOwner)
          _menuItem(value: 'report', icon: Icons.flag_outlined, label: 'تبليغ', color: t.textPrimary),
        const PopupMenuDivider(height: 1),
        if (_isOwner)
          _menuItem(value: 'delete', icon: Icons.delete_outline_rounded, label: 'حذف', color: t.danger),
        if (!_isOwner)
          _menuItem(value: 'block', icon: Icons.block_rounded, label: 'حظر الحساب', color: t.danger),
      ],
    );

    if (!mounted || selected == null) return;

    switch (selected) {
      case 'reply':
        widget.actions.onReply(widget.comment);
        break;
      case 'save':
        await widget.actions.onSave?.call(widget.comment);
        break;
      case 'edit':
        widget.actions.onEdit(widget.comment);
        break;
      case 'delete':
        widget.actions.onDelete(widget.comment);
        break;
      case 'repost':
        widget.actions.onRepost(widget.comment);
        break;
      case 'share':
        await Share.share(widget.comment.text);
        break;
      case 'copy':
        setState(() => _textSelectable = true);
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          const SnackBar(content: Text('حدد النص ثم انسخه')),
        );
        break;
      case 'report':
        widget.actions.onReport(widget.comment);
        break;
      case 'block':
        widget.actions.onBlock(widget.comment);
        break;
    }
  }

  // NEW: يبدأ أثر "الرفع" بمجرد لمس الإصبع للشاشة (قبل ما نعرفو واش راح يكون long press)
  // NEW: يبدأ أثر "الرفع" بمجرد لمس الإصبع للشاشة (قبل ما نعرفو واش راح يكون long press)
  void _onTapDown(TapDownDetails details) {
    setState(() => _pressed = true);
  }

  // NEW: تاب قصير عادي (بلا سحب) — يتصفّر الأثر، بلا فتح قائمة
  void _onTapUp(TapUpDetails details) {
    if (!mounted) return;
    setState(() => _pressed = false);
  }

  // NEW: كيتفعّل إما إذا خرج الإصبع برا الودجة، أو إذا الـ long press ربح الـ arena
  void _onTapCancel() {
    if (!mounted) return;
    setState(() => _pressed = false);
  }

  // NEW: هنا الضغط اتأكد أنه فعلاً مطوّل — نفتحو القائمة بمكان الإصبع
  Future<void> _onLongPressStart(LongPressStartDetails details) async {
    if (!mounted) return;
    setState(() => _pressed = true);
    HapticFeedback.mediumImpact();
    await _showCommentMenu(context, details.globalPosition);
    if (!mounted) return;
    setState(() => _pressed = false);
  }


  @override
  Widget build(BuildContext context) {
    final t = _CommentTheme.of(context);
    final comment = widget.comment;

    return KeyedSubtree(
      key: widget.actions.keyFor(comment.id),
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: _onTapDown,
        onTapUp: _onTapUp,
        onTapCancel: _onTapCancel,
