      MaterialPageRoute(builder: (_) => const AccountSettingsScreen()),
    );
  }
  Widget _coverFallback() {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            AppTeal.main.withValues(alpha: 0.85),
            const Color(0xFF1565C0),
          ],
        ),
      ),
    );
  }
  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    final topInset = MediaQuery.paddingOf(context).top;
    final coverH = _coverHeight + topInset;
    final iconColor =
    Color.lerp(Colors.white, t.textPrimary, _appBarOpacity)!;
    final btnBg = Color.lerp(
      Colors.black.withValues(alpha: 0.35),
      Colors.transparent,
      _appBarOpacity,
    )!;

    return Scaffold(
      backgroundColor: t.pageBg,
      body: Stack(
        children: [
          StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: _userPostsStream,
            builder: (context, snap) {
              final waiting =
                  snap.connectionState == ConnectionState.waiting &&
                      !snap.hasData;
              final all = (snap.data?.docs ?? [])
                  .map((d) => _Post.fromFirestore(d))
                  .toList();
              final originals = all.where((p) => !p.isRepost).toList();
              final reposts = all.where((p) => p.isRepost).toList();

              _Post? pinned;
              if (pinnedPostId != null && pinnedPostId!.isNotEmpty) {
                for (final p in originals) {
                  if (p.id == pinnedPostId) {
                    pinned = p;
                    break;
                  }
                }
              }
              final mediaItems = _mediaFromPosts(originals);


              return NestedScrollView(
                controller: _scrollController,
                headerSliverBuilder: (context, inner) => [
                  SliverToBoxAdapter(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        SizedBox(
                          height: coverH + _avatarRadius + 8,
                          child: Stack(
                            clipBehavior: Clip.none,
                            children: [
                              Positioned(
                                top: 0,
                                left: 0,
                                right: 0,
                                height: coverH,
                                child: GestureDetector(
                                  onTap: _pickCoverImage,
                                  child: ClipRRect(
                                    borderRadius:
                                    const BorderRadius.vertical(
                                      bottom: Radius.circular(4),
                                    ),
                                    child: Stack(
                                      fit: StackFit.expand,
                                      children: [
                                        if (coverImage != null)
                                          Image.file(
                                            coverImage!,
                                            fit: BoxFit.cover,
                                          )
                                        else if (coverImageUrl != null)
                                          Image.network(
                                            coverImageUrl!,
                                            fit: BoxFit.cover,
                                            frameBuilder: (context, child, frame, wasSynchronouslyLoaded) {
                                              if (wasSynchronouslyLoaded || frame != null) return child;
                                              return _ShimmerBlock(t: t); // ممتد كامل
                                            },
                                            errorBuilder: (_, __, ___) => _coverFallback(),
                                          )
                                        else
                                          Container(
                                            decoration: BoxDecoration(
                                              gradient: LinearGradient(
                                                begin: Alignment.topLeft,
                                                end: Alignment.bottomRight,
                                                colors: [
                                                  AppTeal.main,
                                                  const Color(0xFF1565C0),
                                                  const Color(0xFF1A237E),
                                                ],
                                              ),
                                            ),
                                            child: Center(
                                              child: Icon(
                                                Icons.add_a_photo_outlined,
                                                size: 32,
                                                color: Colors.white
                                                    .withValues(alpha: 0.7),
                                              ),
                                            ),
                                          ),
                                        Positioned(
                                          left: 0,
                                          right: 0,
                                          bottom: 0,
                                          height: 48,
                                          child: DecoratedBox(
                                            decoration: BoxDecoration(
                                              gradient: LinearGradient(
                                                begin: Alignment.topCenter,
                                                end: Alignment.bottomCenter,
                                                colors: [
                                                  Colors.transparent,
                                                  Colors.black.withValues(
                                                    alpha: 0.25,
                                                  ),
                                                ],
                                              ),
                                            ),
                                          ),
                                        ),
                                        if (_uploadingCover)
                                          const ColoredBox(
                                            color: Colors.black38,
                                            child: Center(
                                              child:
                                              CircularProgressIndicator(
                                                color: Colors.white,
                                              ),
                                            ),
                                          ),
                                      ],
                                    ),
                                  ),
                                ),
                              ),
                              Positioned(
                                left: 18,
                                top: coverH - _avatarRadius,
                                child: GestureDetector(
                                  onTap: _pickProfileImage,
                                  child: Container(
                                    decoration: BoxDecoration(
                                      shape: BoxShape.circle,
                                      border: Border.all(
                                        color: t.pageBg,
                                        width: 4,
                                      ),
                                      boxShadow: [
                                        BoxShadow(
                                          color: Colors.black
                                              .withValues(alpha: 0.18),
                                          blurRadius: 12,
                                          offset: const Offset(0, 4),
                                        ),
                                      ],
                                    ),
                                    child: CircleAvatar(
                                      radius: _avatarRadius,
                                      backgroundColor: t.cardBorder,
                                      backgroundImage: profileImage != null
                                          ? FileImage(profileImage!)
                                      as ImageProvider
                                          : (profileImageUrl != null
                                          ? NetworkImage(
                                        profileImageUrl!,
                                      )
                                          : null),
                                      child: (profileImage == null &&
                                          profileImageUrl == null)
                                          ? Icon(
                                        Icons.person,
                                        size: _avatarRadius,
                                        color: t.textMuted,
                                      )
                                          : null,
                                    ),
                                  ),
                                ),
                              ),
                              Positioned(
                                left: 18 + _avatarRadius * 2 - 6,
                                top: coverH + _avatarRadius - 28,
                                child: GestureDetector(
                                  onTap: _pickProfileImage,
                                  child: Container(
                                    width: 28,
                                    height: 28,
                                    decoration: BoxDecoration(
                                      color: AppTeal.main,
                                      shape: BoxShape.circle,
                                      border: Border.all(
                                        color: t.pageBg,
                                        width: 2,
                                      ),
                                    ),
                                    child: const Icon(
                                      Icons.camera_alt_rounded,
                                      size: 14,
                                      color: Colors.white,
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(18, 4, 18, 0),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                userName,
                                style: TextStyle(
                                  color: t.textPrimary,
                                  fontSize: 22,
                                  fontWeight: FontWeight.w800,
                                  height: 1.2,
                                ),
                              ),
                              const SizedBox(height: 2),
                              Text(
                                '@$userName',
                                style: TextStyle(color: t.textFaint, fontSize: 15),
                              ),
                              const SizedBox(height: 2),

                              _metaRow(t),
                              const SizedBox(height: 8),
                              InkWell(
                                onTap: _editMood,
                                borderRadius: BorderRadius.circular(20),
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 12,
                                    vertical: 7,
                                  ),
                                  decoration: BoxDecoration(
                                    color: t.isDark
                                        ? Colors.white.withValues(alpha: 0.06)
                                        : const Color(0xFFF0F4F5),
                                    borderRadius: BorderRadius.circular(20),
                                  ),
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Flexible(
                                        child: Text(
                                          mood.trim().isEmpty
                                              ? 'أضف شعوراً...'
                                              : mood,
                                          style: TextStyle(
                                            color: mood.trim().isEmpty
