    _major.dispose();
    _work.dispose();
    _phone.dispose();
    _gender.dispose();
    _other.dispose();
    _studyLevel.dispose();
    _github.dispose();
    _linkedin.dispose();
    _portfolio.dispose();
    super.dispose();
  }

  Future<void> _pickBirthDate() async {
    final now = DateTime.now();
    final initial = DateTime.tryParse(_birthDate.text) ??
        DateTime(now.year - 20, now.month, now.day);
    final picked = await showDatePicker(
      context: context,
      initialDate: initial,
      firstDate: DateTime(1950),
      lastDate: now,
    );
    if (picked != null) {
      _birthDate.text =
      '${picked.year.toString().padLeft(4, '0')}-${picked.month.toString().padLeft(2, '0')}-${picked.day.toString().padLeft(2, '0')}';
      setState(() {});
    }
  }

  Future<void> _save() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;

    setState(() => _saving = true);
    final values = _AccountInfoValues(
      firstName: _firstName.text.trim(),
      lastName: _lastName.text.trim(),
      birthDate: _birthDate.text.trim(),
      residence: _residence.text.trim(),
      uni: _uni.text.trim(),
      fac: _fac.text.trim(),
      major: _major.text.trim(),
      work: _work.text.trim(),
      phone: _phone.text.trim(),
      email: widget.email,
      gender: _gender.text.trim(),
      otherInfo: _other.text.trim(),
      studyLevel: _studyLevel.text.trim(),
      github: _github.text.trim(),
      linkedin: _linkedin.text.trim(),
      portfolio: _portfolio.text.trim(),
    );

    try {
      await FirebaseFirestore.instance.collection('users').doc(uid).set({
        'firstName': values.firstName,
        'lastName': values.lastName,
        'birthDate': values.birthDate,
        'residence': values.residence,
        'university': values.uni,
        'faculty': values.fac,
        'major': values.major,
        'work': values.work,
        'phone': values.phone,
        'gender': values.gender,
        'otherInfo': values.otherInfo,
        'studyLevel': values.studyLevel,
        'github': values.github,
        'linkedin': values.linkedin,
        'portfolio': values.portfolio,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      widget.onSaved(values);
      if (!mounted) return;
      setState(() {
        _editing = false;
        _saving = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم الحفظ')),
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _saving = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذر الحفظ: $e')),
      );
    }
  }

  InputDecoration _dec(_ProfileTheme t, String label, {Widget? suffix}) {
    return InputDecoration(
      labelText: label,
      filled: true,
      fillColor: t.isDark
          ? Colors.white.withValues(alpha: 0.06)
          : Colors.black.withValues(alpha: 0.04),
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(14),
        borderSide: BorderSide.none,
      ),
      contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      suffixIcon: suffix,
    );
  }

  @override
  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    final bottomInset = MediaQuery.of(context).viewInsets.bottom;

    return DraggableScrollableSheet(
      initialChildSize: 0.82,
      minChildSize: 0.45,
      maxChildSize: 0.95,
      expand: false,
      builder: (context, scrollController) {
        return Container(
          decoration: BoxDecoration(
            color: t.cardBg,
            borderRadius: const BorderRadius.vertical(top: Radius.circular(24)),
          ),
          child: Column(
            children: [
              const SizedBox(height: 10),
              // مقبض
              Container(
                width: 36,
                height: 4,
                decoration: BoxDecoration(
                  color: t.cardBorder,
                  borderRadius: BorderRadius.circular(999),
                ),
              ),
              // رأس: عنوان + أزرار (ثابت، خارج القائمة)
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 8, 8),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        'Profile info',
                        style: TextStyle(
                          color: t.textPrimary,
                          fontSize: 17,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ),
                    if (_editing) ...[
                      TextButton(
                        onPressed: _saving
                            ? null
                            : () => setState(() => _editing = false),
                        child: Text(
                          'cancel',
                          style: TextStyle(color: t.textMuted),
                        ),
                      ),
                      FilledButton(
                        onPressed: _saving ? null : _save,
                        style: FilledButton.styleFrom(
                          padding: const EdgeInsets.symmetric(horizontal: 16),
                          minimumSize: const Size(0, 36),
                        ),
                        child: _saving
                            ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: Colors.white,
                          ),
                        )
                            : const Text('save'),
                      ),
                    ] else
                      TextButton.icon(
                        onPressed: () => setState(() => _editing = true),
                        icon: const Icon(Icons.edit_outlined, size: 18),
                        label: const Text('edit'),
                      ),
                  ],
                ),
              ),
              Divider(height: 1, color: t.cardBorder),
              // المحتوى فقط — مع مساحة للكيبورد
              Expanded(
                child: ListView(
                  controller: scrollController,
                  padding: EdgeInsets.fromLTRB(
                    16,
                    12,
                    16,
                    32 + bottomInset,
                  ),
                  children: [
                    _AccountSection(
                      title: 'شخصية',
                      t: t,
                      children: [
                        _field(t, 'الاسم', _firstName),
                        _field(t, 'اللقب', _lastName),
                        _birthField(t),
                        _genderField(t),
                        _field(t, 'مكان الإقامة', _residence),
                      ],
                    ),
                    const SizedBox(height: 14),
                    _AccountSection(
                      title: 'تواصل',
                      t: t,
                      children: [
                        _readOnly(t, 'البريد', widget.email),
                        _field(t, 'رقم الهاتف', _phone,
                            keyboard: TextInputType.phone),
                      ],
                    ),
                    const SizedBox(height: 14),
                    _AccountSection(
                      title: 'دراسة',
                      t: t,
                      children: [
                        _field(t, 'الجامعة', _uni),
                        _field(t, 'الكلية', _fac),
                        _field(t, 'التخصص', _major),
                        _field(t, 'المستوى / السنة', _studyLevel),
                      ],
                    ),
                    const SizedBox(height: 14),
                    _AccountSection(
                      title: 'عمل وروابط',
                      t: t,
                      children: [
                        _field(t, 'العمل / الوظيفة', _work),
                        _field(t, 'GitHub', _github,
                            keyboard: TextInputType.url),
                        _field(t, 'LinkedIn', _linkedin,
                            keyboard: TextInputType.url),
                        _field(t, 'Portfolio', _portfolio,
                            keyboard: TextInputType.url),
                      ],
                    ),
                    const SizedBox(height: 14),
                    _AccountSection(
                      title: 'أخرى',
                      t: t,
                      children: [
                        _field(t, 'معلومات إضافية', _other, maxLines: 3),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _field(
      _ProfileTheme t,
      String label,
      TextEditingController c, {
        TextInputType keyboard = TextInputType.text,
        int maxLines = 1,
      }) {
    if (!_editing) {
      return _AccountFieldTile(
        label: label,
        value: c.text.trim().isEmpty ? '—' : c.text.trim(),
        t: t,
      );
    }
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: c,
        keyboardType: keyboard,
        maxLines: maxLines,
        style: TextStyle(color: t.textPrimary, fontSize: 14),
        decoration: _dec(t, label),
      ),
    );
  }

  Widget _readOnly(_ProfileTheme t, String label, String value) {
    return _AccountFieldTile(
      label: label,
      value: value.trim().isEmpty ? '—' : value,
      t: t,
    );
  }

  Widget _birthField(_ProfileTheme t) {
    if (!_editing) {
      return _AccountFieldTile(
        label: 'تاريخ الميلاد',
        value: _birthDate.text.trim().isEmpty ? '—' : _birthDate.text.trim(),
        t: t,
      );
    }
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: _birthDate,
        readOnly: true,
        onTap: _pickBirthDate,
        style: TextStyle(color: t.textPrimary, fontSize: 14),
        decoration: _dec(
          t,
          'تاريخ الميلاد',
          suffix: const Icon(Icons.calendar_today_outlined, size: 18),
        ),
      ),
    );
  }

  Widget _genderField(_ProfileTheme t) {
    if (!_editing) {
      return _AccountFieldTile(
        label: 'الجنس',
        value: _gender.text.trim().isEmpty ? '—' : _gender.text.trim(),
        t: t,
      );
    }
    const options = ['ذكر', 'أنثى', 'أفضل عدم القول'];
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: DropdownButtonFormField<String>(
        value: options.contains(_gender.text) ? _gender.text : null,
        items: options
            .map((e) => DropdownMenuItem(value: e, child: Text(e)))
            .toList(),
        onChanged: (v) {
          if (v == null) return;
          setState(() => _gender.text = v);
        },
        decoration: _dec(t, 'الجنس'),
      ),
    );
  }
}

