class AccountSettingsScreen extends StatelessWidget {
  const AccountSettingsScreen({super.key});

  Future<void> _deactivateAccount(BuildContext context) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('تعطيل الحساب'),
        content: const Text(
          'سيتم إخفاء حسابك مؤقتاً. يمكنك طلب إعادة التفعيل لاحقاً عبر الدعم أو بتسجيل الدخول إن سمحت بذلك لاحقاً.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('إلغاء'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('تعطيل'),
          ),
        ],
      ),
    );
    if (ok != true || !context.mounted) return;

    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    try {
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'accountStatus': 'disabled',
        'disabledAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      await SessionService.instance.revokeCurrentSession(user.uid);
      await AuthSessionService.signOutFully();

      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم تعطيل الحساب')),
      );
      Navigator.of(context).popUntil((r) => r.isFirst);
    } catch (e) {
      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذر التعطيل: $e')),
      );
    }
  }

  Future<void> _deleteAccount(BuildContext context) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('حذف الحساب نهائياً'),
        content: const Text(
          'سيتم حذف حسابك من التطبيق. المنشورات القديمة قد تبقى إلى أن تُنظَّف لاحقاً من الخادم.\n\n'
              'لا يمكن التراجع عن هذا الإجراء.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('إلغاء'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('متابعة'),
          ),
        ],
      ),
    );
    if (ok != true || !context.mounted) return;

    // إعادة مصادقة قبل الحذف
    final reauthed = await _reauthForDelete(context, user);
    if (!reauthed || !context.mounted) return;

    final uid = user.uid;

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => const Center(
        child: Card(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: CircularProgressIndicator(),
          ),
        ),
      ),
    );

    try {
      // 1) تأكيد أن المستخدم ما زال مسجّلاً بعد إعادة المصادقة
      final current = FirebaseAuth.instance.currentUser;
      if (current == null || current.uid != uid) {
        throw FirebaseAuthException(
          code: 'user-not-found',
          message: 'انتهت الجلسة. سجّل الدخول ثم أعد المحاولة.',
        );
      }

      // 2) حذف Auth أولاً — هذا يحرّر الإيميل
      // لا تستخدم ?. حتى لا يُتخطى الحذف بصمت
      await current.delete();

      // 3) بعد نجاح الحذف فقط: تنظيف اختياري لـ Firestore
      // قد يفشل لأن المستخدم لم يعد مصادقاً — هذا مقبول
      try {
        await FirebaseFirestore.instance.collection('users').doc(uid).set({
          'accountStatus': 'deleted',
          'deletedAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      } catch (e) {
        debugPrint('Firestore cleanup after auth delete (optional): $e');
      }

      // 4) خروج محلي (Auth غالباً أصبح null بعد delete)
      try {
        await AuthSessionService.signOutFully();
      } catch (_) {}

      if (!context.mounted) return;
      Navigator.of(context).pop(); // إغلاق التحميل
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'تم حذف الحساب. يمكنك إنشاء حساب جديد بنفس البريد.',
          ),
        ),
      );
      Navigator.of(context).popUntil((r) => r.isFirst);
    } on FirebaseAuthException catch (e) {
      debugPrint('DELETE AUTH FAILED: ${e.code} ${e.message}');
      if (context.mounted) Navigator.of(context).pop();
      if (!context.mounted) return;

      // لا نوسُم الحساب deleted هنا — Auth ما زال موجوداً
      final msg = switch (e.code) {
        'requires-recent-login' =>
        'انتهت صلاحية الجلسة. سجّل الدخول من جديد ثم احذف الحساب مباشرة.',
        'user-not-found' =>
        'انتهت الجلسة. سجّل الدخول ثم أعد محاولة الحذف.',
        _ => e.message ?? 'تعذر حذف الحساب (${e.code})',
      };
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(msg)));
    } catch (e, st) {
      debugPrint('DELETE ACCOUNT FAILED: $e');
      debugPrintStack(stackTrace: st);
      if (context.mounted) Navigator.of(context).pop();
      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذر حذف الحساب: $e')),
      );
    }
  }
  Future<bool> _reauthForDelete(BuildContext context, User user) async {
    final isPassword =
    user.providerData.any((p) => p.providerId == 'password');
    final isGoogle =
    user.providerData.any((p) => p.providerId == 'google.com');

    // ----- بريد + كلمة مرور -----
    if (isPassword && user.email != null) {
      final ctrl = TextEditingController();
      final confirmed = await showModalBottomSheet<bool>(
        context: context,
        isScrollControlled: true,
        showDragHandle: true,
        builder: (ctx) {
          return Padding(
            padding: EdgeInsets.fromLTRB(
              16,
              8,
              16,
              MediaQuery.of(ctx).viewInsets.bottom + 20,
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const Text(
                  'أكد هويتك قبل الحذف',
                  style: TextStyle(fontSize: 18, fontWeight: FontWeight.w800),
                ),
                const SizedBox(height: 8),
                Text(
                  'أدخل كلمة مرور ${user.email}',
                  style: TextStyle(color: Theme.of(ctx).hintColor),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: ctrl,
                  obscureText: true,
                  autofocus: true,
                  decoration: const InputDecoration(
                    labelText: 'كلمة المرور',
                  ),
                ),
                const SizedBox(height: 16),
                FilledButton(
                  style: FilledButton.styleFrom(backgroundColor: Colors.red),
                  onPressed: () => Navigator.pop(ctx, true),
                  child: const Text('تأكيد والحذف'),
                ),
                TextButton(
                  onPressed: () => Navigator.pop(ctx, false),
                  child: const Text('إلغاء'),
                ),
              ],
            ),
          );
        },
      );

      if (confirmed != true) {
        ctrl.dispose();
        return false;
      }

      try {
        final cred = EmailAuthProvider.credential(
          email: user.email!,
          password: ctrl.text.trim(),
        );
        await FirebaseAuth.instance.currentUser!
            .reauthenticateWithCredential(cred);
        ctrl.dispose();
        return true;
      } on FirebaseAuthException catch (e) {
        ctrl.dispose();
        if (!context.mounted) return false;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              e.code == 'wrong-password' || e.code == 'invalid-credential'
                  ? 'كلمة المرور غير صحيحة'
                  : (e.message ?? 'فشلت إعادة المصادقة'),
            ),
          ),
        );
        return false;
      } catch (_) {
        ctrl.dispose();
        return false;
      }
    }

    // ----- Google -----
    if (isGoogle) {
      try {
        final googleUser = await AuthSessionService.googleSignIn.signIn();
        if (googleUser == null) return false;
        final googleAuth = await googleUser.authentication;
        final cred = GoogleAuthProvider.credential(
          accessToken: googleAuth.accessToken,
          idToken: googleAuth.idToken,
        );
        await FirebaseAuth.instance.currentUser!
            .reauthenticateWithCredential(cred);
        return true;
      } catch (e) {
        if (!context.mounted) return false;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('تعذر تأكيد Google: $e')),
        );
        return false;
      }
    }

    if (!context.mounted) return false;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('لا يمكن حذف هذا النوع من الحساب من التطبيق حالياً'),
      ),
    );
    return false;
  }


  Future<void> _rateApp(BuildContext context) async {
    final launched = await launchUrl(
      Uri.parse(AppLinks.storeUrl),
      mode: LaunchMode.externalApplication,
    );
    if (!launched && context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر فتح المتجر')),
      );
    }
  }

  Future<void> _logout(BuildContext context) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('تسجيل الخروج'),
        content: const Text('هل تريد تسجيل الخروج من الحساب؟'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('إلغاء'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('خروج'),
          ),
        ],
      ),
    );
    if (ok != true || !context.mounted) return;

    final user = FirebaseAuth.instance.currentUser;
    if (user != null) {
      await SessionService.instance.revokeCurrentSession(user.uid);
    }
    await AuthSessionService.signOutFully();
    if (!context.mounted) return;
    // AuthGate يتكفّل بإظهار SignIn
    Navigator.of(context).popUntil((r) => r.isFirst);
  }

