class _ProfileMediaPane extends StatelessWidget {
  const _ProfileMediaPane({
    required this.items,
    required this.t,
  });

  final List<_ProfileMediaItem> items;
  final _ProfileTheme t;

  @override
  Widget build(BuildContext context) {
    if (items.isEmpty) {
      return _ProfileEmptyPane(
        icon: Icons.photo_library_outlined,
        label: 'لا توجد وسائط',
        t: t,
      );
    }

    return GridView.builder(
      padding: const EdgeInsets.fromLTRB(2, 2, 2, 80),
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 3,
        mainAxisSpacing: 2,
        crossAxisSpacing: 2,
      ),
      itemCount: items.length,
      itemBuilder: (context, i) {
        final item = items[i];
        final isNet =
            item.path.startsWith('http://') || item.path.startsWith('https://');

        return GestureDetector(
          onTap: () {
            Navigator.of(context).push(
              MaterialPageRoute(
                builder: (_) => CommentsScreen(post: item.post),
              ),
            );
          },
          child: Stack(
            fit: StackFit.expand,
            children: [
              if (!item.isVideo)
                isNet
                    ? Image.network(
                  item.path,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => ColoredBox(
                    color: t.cardBorder,
                    child: Icon(Icons.broken_image_outlined,
                        color: t.textFaint),
                  ),
                )
                    : Image.file(
                  File(item.path),
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => ColoredBox(
                    color: t.cardBorder,
                    child: Icon(Icons.broken_image_outlined,
                        color: t.textFaint),
                  ),
                )
              else
                ColoredBox(
                  color: Colors.black87,
                  child: Icon(
                    Icons.play_circle_outline,
                    color: Colors.white.withValues(alpha: 0.9),
                    size: 36,
                  ),
                ),
              if (item.isVideo)
                const Positioned(
                  right: 6,
                  bottom: 6,
                  child: Icon(Icons.videocam, color: Colors.white, size: 16),
                ),
            ],
          ),
        );
      },
    );
  }
}

class _ProfilePostsPane extends StatelessWidget {
  const _ProfilePostsPane({
    required this.posts,
    required this.emptyLabel,
    required this.emptyIcon,
    required this.t,
    required this.onChanged,
    this.pinnedPost,
    this.actionLabel,
    this.onAction,
    this.onSetPinned,
    this.currentPinnedId,
  });

  final List<_Post> posts;
  final String emptyLabel;
  final IconData emptyIcon;
  final _ProfileTheme t;
  final VoidCallback onChanged;
  final _Post? pinnedPost;
  final String? actionLabel;
  final VoidCallback? onAction;
  final Future<void> Function(String? postId)? onSetPinned;
  final String? currentPinnedId;

  @override
  Widget build(BuildContext context) {
    final feed = pinnedPost == null
        ? posts
        : posts.where((p) => p.id != pinnedPost!.id).toList();

    if (feed.isEmpty && pinnedPost == null) {
      return _ProfileEmptyPane(
        icon: emptyIcon,
        label: emptyLabel,
        t: t,
        actionLabel: actionLabel,
        onAction: onAction,
      );
    }

    final extra = pinnedPost != null ? 2 : 0; // عنوان + بطاقة

    return CustomScrollView(
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.only(bottom: 80),
          sliver: SliverList(
            delegate: SliverChildBuilderDelegate(
                  (context, index) {
                if (pinnedPost != null) {
                  if (index == 0) {
                    return _PostCard(
                      post: pinnedPost!,
                      showAuthorHeader: false,
                      compact: true,
                      onChanged: onChanged,
                      onDelete: () async {},
                      onHidden: () {},
                      allowPin: onSetPinned != null,
                      isPinned: true,
                      onSetPinned: onSetPinned,
                    );
                  }
                  final post = feed[index - 1];
                  return _PostCard(
                    post: post,
                    showAuthorHeader: false,
                    compact: true,
                    onChanged: onChanged,
                    onDelete: () async {},
                    onHidden: () {},
                    allowPin: onSetPinned != null,
                    isPinned: false,
                    onSetPinned: onSetPinned,
                  );
                }

                final post = feed[index];
                return _PostCard(
                  post: post,
                  showAuthorHeader: false,
                  compact: true,
                  onChanged: onChanged,
                  onDelete: () async {},
                  onHidden: () {},
                  allowPin: onSetPinned != null,
                  isPinned: currentPinnedId != null &&
                      currentPinnedId == post.id,
                  onSetPinned: onSetPinned,
                );
              },
              childCount: feed.length + (pinnedPost != null ? 1 : 0),
            ),
          ),
        ),
      ],
    );
  }
}

