class UserProfileScreen extends StatefulWidget {
  const UserProfileScreen({
    super.key,
    required this.userId,
    this.initialName,
    this.initialPhotoUrl,
  });

  final String userId;
  final String? initialName;
  final String? initialPhotoUrl;

  @override
  State<UserProfileScreen> createState() => _UserProfileScreenState();
}

class _UserProfileScreenState extends State<UserProfileScreen>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;
  List<_ProfileCommentHit> _userComments = [];
  bool _loadingComments = true;
  late final Stream<QuerySnapshot<Map<String, dynamic>>> _postsStream;
  final ScrollController _scrollController = ScrollController();

  bool _loadingProfile = true;
  String _displayName = '';
  String _username = '';
  String? _photoUrl;
  String? _coverUrl;
  String _mood = '';
  String _uni = '';
  String _fac = '';
  String _major = '';
  String _studyLevel = '';
  String _github = '';
  String _linkedin = '';
  String _portfolio = '';
  String _otherInfo = '';
  String _work = '';
  String _residence = '';
  int _followersCount = 0;
  int _followingCount = 0;
  int _postsCount = 0;
  bool _isFollowing = false;
  bool _followBusy = false;
  double _appBarOpacity = 0;
  bool _targetIsPrivate = false;
  bool _requestPending = false;

  bool _showAcademicInfo = true;
  bool _showSocialLinks = true;
  String _email = '';
  bool _showEmailOnProfile = false;
  String _followersVisibility = 'everyone';
  String _followingVisibility = 'everyone';

  static const double _coverHeight = 140;
  static const double _avatarSize = 72;
  bool _unavailable = false;
  bool _checkingAccess = true;
  bool _iBlockThem = false;
  bool _theyBlockMe = false;
  bool _blockStateReady = false;
  bool get _isSelf {
    final me = FirebaseAuth.instance.currentUser?.uid;
    return me != null && me == widget.userId;
  }

  @override
  void initState() {
    super.initState();
    _displayName = (widget.initialName ?? '').trim();
    _photoUrl = widget.initialPhotoUrl;
    _postsStream = FirebaseFirestore.instance
        .collection('community_posts')
        .where('authorId', isEqualTo: widget.userId)
        .orderBy('createdAt', descending: true)
        .snapshots();
    _tabController = TabController(length: 3, vsync: this);
    _loadUserComments();
    _scrollController.addListener(_onScroll);
    _loadProfile();
    _loadBlockState();
    _checkAccess();
    _checkFollowing();
    _loadCounts();
    _loadBlockState();
    blockedListRevision.addListener(_loadBlockState);

  }
  Future<void> _blockFromProfile() async {
    if (_isSelf) return;
    try {
      await blockAccount(
        targetId: widget.userId,
        targetName: _displayName,
        targetPhotoUrl: _photoUrl,
      );
      if (!mounted) return;
      Navigator.of(context).pop();
    } catch (e) {
      debugPrint('block from profile failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حظر الحساب')),
      );
    }
  }
  @override
  void dispose() {
    _scrollController.removeListener(_onScroll);
    _scrollController.dispose();
    _tabController.dispose();

    blockedListRevision.removeListener(_loadBlockState);
    super.dispose();
  }
  Future<void> _checkAccess() async {
    if (_isSelf) {
      if (mounted) setState(() => _checkingAccess = false);
      return;
    }
    try {
      final hidden = await isBlockedByAccount(widget.userId) ||
          await isAccountBlocked(widget.userId);
      if (!mounted) return;
      setState(() {
        _unavailable = hidden;
        _checkingAccess = false;
      });
    } catch (e) {
      debugPrint('profile access check failed: $e');
      if (mounted) setState(() => _checkingAccess = false);
    }
  }
  Future<void> _loadBlockState() async {
    if (_isSelf) {
      if (!mounted) return;
      setState(() {
        _iBlockThem = false;
        _theyBlockMe = false;
        _blockStateReady = true;
        _checkingAccess = false;
      });
      return;
    }

    final iBlock = await isAccountBlocked(widget.userId);
    final theyBlock = await isBlockedByAccount(widget.userId);

    if (!mounted) return;
    setState(() {
      _iBlockThem = iBlock;
      _theyBlockMe = theyBlock;
      _blockStateReady = true;
      _checkingAccess = false;
    });
  }

  Future<void> _confirmBlock() async {
    final me = FirebaseAuth.instance.currentUser;
    if (me == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
          title: const Text('حظر الحساب؟'),
          content: Text(
            'لن تظهر منشورات $_displayName في فيدك بعد الآن. يمكنك إلغاء الحظر لاحقًا من الإعدادات.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFDC2626),
                foregroundColor: Colors.white,
              ),
              child: const Text('حظر'),
            ),
          ],
        ),
      ),
    );
    if (confirmed != true) return;

    try {
      await blockAccount(
        targetId: widget.userId,
        targetName: _displayName,
        targetPhotoUrl: _photoUrl,
      );
    } catch (e) {
      debugPrint('blockAccount failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذر الحظر: $e')),
      );
      return;
    }
    if (!mounted) return;
    setState(() {
      _iBlockThem = true;
      _isFollowing = false;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('تم حظر $_displayName')),
    );
  }

  Future<void> _unblock() async {
    await unblockAccount(widget.userId);
    if (!mounted) return;
    setState(() => _iBlockThem = false);
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('تم إلغاء الحظر')),
    );
  }

  Future<void> _reportAccount() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب تسجيل الدخول أولاً')),
      );
      return;
    }

    final targetId = widget.userId.trim();
    if (targetId.isEmpty) return;
    if (targetId == user.uid) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('لا يمكنك تبليغ محتواك')),
      );
      return;
    }

    final already = await hasCommunityReport(
      type: CommunityReportType.user,
      targetId: targetId,
    );
    if (!mounted) return;

    if (already) {
      await showReportSubmittedSheet(
        context,
        type: CommunityReportType.user,
        ownerId: targetId,
        ownerName: _displayName,
        ownerPhotoUrl: _photoUrl,
        alreadyReported: true,
        onBlocked: () {
          if (!mounted) return;
          setState(() {
            _iBlockThem = true;
            _isFollowing = false;
          });
        },
        onUnfollowed: () {
          if (!mounted) return;
          setState(() => _isFollowing = false);
        },
      );
      return;
    }

    final result = await showCommunityReportSheet(
      context,
      type: CommunityReportType.user,
    );
    if (result == null || !mounted) return;

    try {
      await submitCommunityReport(
        type: CommunityReportType.user,
        targetId: targetId,
        ownerId: targetId,
        ownerName: _displayName,
        reason: result.reasonId,
        details: result.details,
        snapshot: {
          'displayName': _displayName,
          'username': _username,
          'photoUrl': _photoUrl,
          'mood': _mood,
        },
      );
      if (!mounted) return;
      await showReportSubmittedSheet(
        context,
        type: CommunityReportType.user,
        ownerId: targetId,
        ownerName: _displayName,
        ownerPhotoUrl: _photoUrl,
        onBlocked: () {
          if (!mounted) return;
          setState(() {
            _iBlockThem = true;
            _isFollowing = false;
          });
        },
        onUnfollowed: () {
          if (!mounted) return;
          setState(() => _isFollowing = false);
        },
      );
    } catch (e) {
      debugPrint('account report failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(messageForCommunityReportError(e))),
      );
    }
  }

  void _onScroll() {
    final topInset = MediaQuery.paddingOf(context).top;
    final coverH = _coverHeight + topInset;
    final opacity =
    (_scrollController.offset / (coverH - kToolbarHeight)).clamp(0.0, 1.0);
    if ((opacity - _appBarOpacity).abs() > 0.01) {
      setState(() => _appBarOpacity = opacity);
    }
  }

  void _openProfileSearch(_ProfileTheme t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _ProfileSearchSheet(
        t: t,
        authorId: widget.userId ,
        authorName: _displayName ,
      ),
    );
  }
  Future<void> _loadUserComments() async {
    setState(() => _loadingComments = true);
    try {
      final hits = await loadCommentsByAuthor(widget.userId);
      if (!mounted) return;
      setState(() {
        _userComments = hits;
        _loadingComments = false;
      });
    } catch (e) {
      debugPrint('load user comments failed: $e');
      if (mounted) setState(() => _loadingComments = false);
    }
  }

  Future<void> _loadProfile() async {
    setState(() => _loadingProfile = true);
    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.userId)
          .get();
      final data = doc.data() ?? <String, dynamic>{};
      final fn = (data['firstName'] ?? '').toString().trim();
      final ln = (data['lastName'] ?? '').toString().trim();
      final fromNames = [fn, ln].where((e) => e.isNotEmpty).join(' ');
      final display =
      (data['displayName'] ?? data['username'] ?? '').toString().trim();
      final uname = (data['username'] ?? '').toString().trim();
      final priv = data['privacy'];
      final pmap = priv is Map ? Map<String, dynamic>.from(priv) : null;
      _targetIsPrivate = pmap?['privateAccount'] == true;
      _showAcademicInfo = pmap?['showAcademicInfo'] != false;
      _showSocialLinks = pmap?['showSocialLinks'] != false;
      _followersVisibility =
          (pmap?['followersVisibility'] ?? 'everyone').toString();
      _followingVisibility =
          (pmap?['followingVisibility'] ?? 'everyone').toString();

      if (!mounted) return;
      setState(() {
        _targetIsPrivate = (data['privacy'] is Map) &&
            (data['privacy'] as Map)['privateAccount'] == true;
        _displayName = fromNames.isNotEmpty
            ? fromNames
            : (display.isNotEmpty
            ? display
            : (_displayName.isNotEmpty ? _displayName : 'طالب UniSpace'));
        _username = uname.isNotEmpty
            ? uname
            : _displayName.toLowerCase().replaceAll(RegExp(r'\s+'), '_');
        _photoUrl =
        (data['profileImageUrl']?.toString().trim().isNotEmpty == true)
            ? data['profileImageUrl'].toString()
            : _photoUrl;
        _coverUrl = data['coverImageUrl']?.toString();
        _mood = (data['mood'] ?? '').toString();
        _uni = (data['university'] ?? '').toString();
        _fac = (data['faculty'] ?? '').toString();
        _major = (data['major'] ?? '').toString();
        _studyLevel = (data['studyLevel'] ?? '').toString();
        _github = (data['github'] ?? '').toString().trim();
        _linkedin = (data['linkedin'] ?? '').toString().trim();
        _portfolio = (data['portfolio'] ?? '').toString().trim();
        _otherInfo = (data['otherInfo'] ?? '').toString().trim();
        _work = (data['work'] ?? '').toString().trim();
        _residence = (data['residence'] ?? '').toString().trim();
        _followersCount =
            (data['followersCount'] as num?)?.toInt() ?? _followersCount;
        _followingCount =
            (data['followingCount'] as num?)?.toInt() ?? _followingCount;
        _loadingProfile = false;
        _email = (data['email'] ?? '').toString().trim();
        _showEmailOnProfile = pmap?['showEmailOnProfile'] == true;
      });
      if (_photoUrl != null && _photoUrl!.isNotEmpty) {
        AuthorProfiles.put(widget.userId, _photoUrl);
      }
    } catch (e) {
      debugPrint('UserProfile load failed: $e');
      if (!mounted) return;
      setState(() {
        _loadingProfile = false;
        if (_displayName.isEmpty) _displayName = 'طالب UniSpace';
      });
    }
  }

  Future<void> _loadCounts() async {
    try {
      final userRef =
      FirebaseFirestore.instance.collection('users').doc(widget.userId);
      final followers = await userRef.collection('followers').count().get();
      final following = await userRef.collection('following').count().get();
      final posts = await FirebaseFirestore.instance
          .collection('community_posts')
          .where('authorId', isEqualTo: widget.userId)
          .count()
          .get();

      if (!mounted) return;
      setState(() {
        _followersCount = followers.count ?? _followersCount;
        _followingCount = following.count ?? _followingCount;
        _postsCount = posts.count ?? _postsCount;
      });
    } catch (e) {
      debugPrint('load counts failed: $e');
    }
  }

  bool get _canSeePrivateContent =>
      _isSelf || !_targetIsPrivate || _isFollowing;

  Future<void> _checkFollowing() async {
    final me = FirebaseAuth.instance.currentUser?.uid;
    if (me == null || _isSelf) return;
    try {
      final following = await FirebaseFirestore.instance
          .collection('users')
          .doc(me)
          .collection('following')
          .doc(widget.userId)
          .get();
      final requested =
      await _followRequestRef(widget.userId, me).get();
      if (!mounted) return;
      setState(() {
        _isFollowing = following.exists;
        _requestPending = !_isFollowing && requested.exists;
      });
    } catch (_) {}
  }

  Future<void> _toggleFollow() async {
    final me = FirebaseAuth.instance.currentUser;
    final myUid = me?.uid;
    if (myUid == null || _isSelf || _followBusy) return;

    setState(() => _followBusy = true);
    HapticFeedback.lightImpact();

    try {
      String myName = (me?.displayName ?? '').trim();
      String? myPhoto = me?.photoURL;
      try {
        final myDoc = await FirebaseFirestore.instance
            .collection('users')
            .doc(myUid)
            .get();
        final d = myDoc.data();
        final fn = (d?['firstName'] ?? '').toString().trim();
        final ln = (d?['lastName'] ?? '').toString().trim();
        final fromNames = [fn, ln].where((e) => e.isNotEmpty).join(' ');
        if (fromNames.isNotEmpty) myName = fromNames;
        final p = d?['profileImageUrl']?.toString();
        if (p != null && p.isNotEmpty) myPhoto = p;
      } catch (_) {}
      if (myName.isEmpty) myName = 'طالب UniSpace';

      if (_isFollowing) {
        await setFollowing(
          me: myUid,
          targetId: widget.userId,
          targetName: _displayName,
          targetPhotoUrl: _photoUrl,
          myName: myName,
          myPhotoUrl: myPhoto,
          follow: false,
        );
      } else if (_requestPending) {
        await cancelFollowRequest(widget.userId);
      } else {
        await setFollowing(
          me: myUid,
          targetId: widget.userId,
          targetName: _displayName,
          targetPhotoUrl: _photoUrl,
          myName: myName,
          myPhotoUrl: myPhoto,
          follow: true,
        );
      }
      await _checkFollowing();
      await _loadCounts();
    } catch (e) {
      debugPrint('toggle follow failed: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('تعذر تحديث المتابعة')),
        );
      }
    } finally {
      if (mounted) setState(() => _followBusy = false);
    }
  }

  Widget _followButton(_ProfileTheme t, bool isDark) {
    final requested = _requestPending && !_isFollowing;
    final filled = !_isFollowing && !requested;
    final label = _isFollowing
        ? 'Following'
        : (requested ? 'Requested' : 'Follow');

    return Material(
      color: filled
          ? (isDark ? Colors.white : Colors.black)
          : Colors.transparent,
      borderRadius: BorderRadius.circular(20),
      child: InkWell(
        onTap: _followBusy ? null : _toggleFollow,
        borderRadius: BorderRadius.circular(20),
        child: Container(
          height: 36,
          padding: const EdgeInsets.symmetric(horizontal: 16),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(20),
            border: filled ? null : Border.all(color: t.cardBorder, width: 1.2),
          ),
          child: _followBusy
              ? SizedBox(
            width: 16,
            height: 16,
            child: CircularProgressIndicator(
              strokeWidth: 2,
              color: filled
                  ? (isDark ? Colors.black : Colors.white)
                  : t.textPrimary,
            ),
          )
              : Text(
            label,
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w800,
              color: filled
                  ? (isDark ? Colors.black : Colors.white)
                  : t.textPrimary,
            ),
          ),
        ),
      ),
    );
  }



  Future<void> _openLink(String url) async {
    var u = url.trim();
    if (u.isEmpty) return;
    if (!u.startsWith('http')) u = 'https://$u';
    final uri = Uri.tryParse(u);
    if (uri == null) return;
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  String _formatCount(int n) {
    if (n >= 1000000) {
      final v = n / 1000000;
      return v >= 10 ? '${v.toStringAsFixed(0)}M' : '${v.toStringAsFixed(1)}M';
    }
    if (n >= 1000) {
      final v = n / 1000;
      return v >= 10 ? '${v.toStringAsFixed(0)}K' : '${v.toStringAsFixed(1)}K';
    }
    return '$n';
  }

  @override

  Widget _blockedProfileScaffold({
    required _ProfileTheme t,
    required String title,
    required String subtitle,
    Widget? action,
  }) {
    return Scaffold(
      backgroundColor: t.pageBg,
      appBar: AppBar(
        backgroundColor: t.pageBg,
        elevation: 0,
        leading: IconButton(
          icon: Icon(Icons.arrow_back, color: t.textPrimary),
          onPressed: () => Navigator.maybePop(context),
        ),
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              LiveAuthorPhoto(
                userId: widget.userId,
                fallbackUrl: _photoUrl,
                size: 72,
                radius: 36,
                iconSize: 32,
              ),
              const SizedBox(height: 16),
              Text(
                _displayName,
                style: TextStyle(
                  color: t.textPrimary,
                  fontSize: 20,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 20),
              Icon(Icons.block_rounded, size: 40, color: t.textFaint),
              const SizedBox(height: 12),
              Text(
                title,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: t.textPrimary,
                  fontSize: 17,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                subtitle,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: t.textMuted,
                  fontSize: 14,
                  height: 1.4,
                ),
              ),
              if (action != null) ...[
                const SizedBox(height: 24),
                action,
              ],
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    final iconColor =
    Color.lerp(Colors.white, t.textPrimary, _appBarOpacity)!;
    final btnBg = Color.lerp(
      Colors.black.withValues(alpha: 0.35),
      Colors.transparent,
      _appBarOpacity,
    )!;

    if (_checkingAccess || (!_isSelf && !_blockStateReady)) {
      return Scaffold(
        backgroundColor: t.pageBg,
        appBar: AppBar(
          backgroundColor: t.pageBg,
          surfaceTintColor: Colors.transparent,
          leading: IconButton(
            icon: Icon(Icons.arrow_back, color: t.textPrimary),
            onPressed: () => Navigator.maybePop(context),
          ),
        ),
        body: const Center(
          child: SizedBox(
            width: 28,
            height: 28,
            child: CircularProgressIndicator(strokeWidth: 2.5),
          ),
        ),
      );
    }

    if (!_isSelf && _theyBlockMe) {
      return _blockedProfileScaffold(
        t: t,
        title: 'لقد حظرك هذا الحساب',
        subtitle: 'لن تتمكن من مشاهدة منشوراته أو التفاعل معه.',
        action: TextButton(
          onPressed: _reportAccount,
          child: const Text(
            'تبليغ',
            style: TextStyle(fontWeight: FontWeight.w800),
          ),
        ),
      );
    }

    if (!_isSelf && _iBlockThem) {
      return _blockedProfileScaffold(
        t: t,
        title: 'لقد حظرت هذا الحساب',
        subtitle: 'لن تظهر منشوراته في فيدك. يمكنك إلغاء الحظر في أي وقت.',
        action: OutlinedButton(
          onPressed: _unblock,
          style: OutlinedButton.styleFrom(
            foregroundColor: t.textPrimary,
            side: BorderSide(color: t.cardBorder),
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
          ),
          child: const Text(
            'إلغاء الحظر',
            style: TextStyle(fontWeight: FontWeight.w800),
          ),
        ),
      );
    }
    return Scaffold(
      backgroundColor: t.pageBg,
      body: Stack(
        children: [
          StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: _postsStream,
            builder: (context, snap) {
              final t = _ProfileTheme.of(context);
              final waiting = snap.connectionState == ConnectionState.waiting &&
                  !snap.hasData;

              final all = (snap.data?.docs ?? [])
                  .map((d) => _Post.fromFirestore(d))
                  .toList();
              final originals = all.where((p) => !p.isRepost).toList();
              final reposts = all.where((p) => p.isRepost).toList();

              final n = originals.length;
              if (n != _postsCount) {
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (mounted) setState(() => _postsCount = n);
                });
              }

              return NestedScrollView(
                controller: _scrollController,
                headerSliverBuilder: (context, inner) => [
                  SliverToBoxAdapter(child: _buildXHeader(t, t.isDark)),
                  if (_canSeePrivateContent)
                    SliverPersistentHeader(
                      pinned: true,
                      delegate: _ProfileTabsDelegate(
                        tabBar: _postsTab(t),
                        background: t.pageBg,
                      ),
                    ),
                ],
                body: !_canSeePrivateContent
                    ? ListView(
                  padding: const EdgeInsets.fromLTRB(32, 48, 32, 32),
                  children: [
                    Icon(Icons.lock_outline_rounded, size: 42, color: t.textFaint),
                    const SizedBox(height: 12),
                    Text(
                      'هذا الحساب خاص',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: t.textPrimary,
                        fontWeight: FontWeight.w800,
                        fontSize: 16,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      'تابع هذا الحساب لرؤية منشوراته.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: t.textFaint),
                    ),
                  ],
                )

                    : TabBarView(
                  controller: _tabController,
                  children: [
                    waiting
                        ? const _ProfileTabLoading()
                        : _ProfilePostsPane(
                      posts: originals,
                      emptyLabel: 'لا توجد منشورات بعد',
                      emptyIcon: Icons.article_outlined,
                      t: t,
                      actionLabel: 'أنشئ أول منشور',
                      onAction: () {
                        Navigator.of(context).push(
                          MaterialPageRoute(
                            builder: (_) => const CreatePostScreen(),
                          ),
                        );
                      },
                      onChanged: () {
                        if (mounted) setState(() {});
                      },
                    ),
                    waiting
                        ? const _ProfileTabLoading()
                        : _ProfilePostsPane(
                      posts: reposts,
                      emptyLabel: 'لا توجد إعادة نشر',
                      emptyIcon: Icons.repeat_rounded,
                      t: t,
                      onChanged: () {
                        if (mounted) setState(() {});
                      },
                    ),
                    _ProfileCommentsPane(
                      loading: _loadingComments,
                      comments: _userComments,
                      t: t,
                    ),
                  ],
                ),
              );
            },
          ),
          Positioned(
            top: 0,
            left: 0,
            right: 0,
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 120),
              color: t.pageBg.withValues(alpha: _appBarOpacity),
              child: SafeArea(
                bottom: false,
                child: SizedBox(
                  height: kToolbarHeight,
                  child: Row(
                    children: [
                      _appBarCircleButton(
                        icon: Icons.arrow_back,
                        color: iconColor,
                        bg: btnBg,
                        onTap: () => Navigator.of(context).maybePop(),
                      ),
                      Expanded(
                        child: Opacity(
                          opacity: _appBarOpacity,
                          child: Text(
                            _displayName,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: t.textPrimary,
                              fontWeight: FontWeight.w800,
                              fontSize: 16,
                            ),
                          ),
                        ),
                      ),
                      _appBarCircleButton(
                        icon: Icons.search_rounded,
                        color: iconColor,
                        bg: btnBg,
                        onTap: () => _openProfileSearch(t),
                      ),
                      if (!_isSelf)
                        _appBarCircleButton(
                          icon: Icons.more_horiz,
                          color: iconColor,
                          bg: btnBg,
                          onTap: () => _showMoreSheet(t),
                        ),
                      const SizedBox(width: 6),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _appBarCircleButton({
    required IconData icon,
    required Color color,
    required Color bg,
    required VoidCallback onTap,
  }) {
    return Padding(
      padding: const EdgeInsets.all(6),
      child: Material(
        color: bg,
        shape: const CircleBorder(),
        child: InkWell(
          customBorder: const CircleBorder(),
          onTap: onTap,
          child: Padding(
            padding: const EdgeInsets.all(7),
            child: Icon(icon, size: 19, color: color),
          ),
        ),
      ),
    );
  }


  Widget _buildXHeader(_ProfileTheme t, bool isDark) {
    final topInset = MediaQuery.paddingOf(context).top;
    final coverH = _coverHeight + topInset;
    final bio = _mood.trim().isNotEmpty
        ? _mood.trim()
        : (_otherInfo.trim().isNotEmpty ? _otherInfo.trim() : '');

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SizedBox(
          height: coverH + _avatarSize / 2 + 8,
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              Positioned(
                top: 0,
                left: 0,
                right: 0,
                height: coverH,
                child: _coverUrl != null && _coverUrl!.trim().isNotEmpty
                    ? Image.network(
                  _coverUrl!,
                  fit: BoxFit.cover,
                  width: double.infinity,
                  height: coverH,
                  errorBuilder: (_, __, ___) => _coverFallback(),
                )
                    : _coverFallback(),
              ),
              Positioned(
                left: 16,
                top: coverH - _avatarSize / 2,
                child: Container(
                  width: _avatarSize,
                  height: _avatarSize,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: t.pageBg,
                    border: Border.all(color: t.pageBg, width: 4),
                  ),
                  child: ClipOval(
                    child: LiveAuthorPhoto(
                      userId: widget.userId,
                      fallbackUrl: _photoUrl,
                      size: _avatarSize - 8,
                      radius: (_avatarSize - 8) / 2,
                      iconSize: 30,
                    ),
                  ),
                ),
              ),
              Positioned(
                right: 16,
                top: coverH + 8,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (!_isSelf) ...[
                      _circleIconButton(
                        t,
                        FaIcon(
                          FontAwesomeIcons.commentDots,
                          size: 16,
                          color: t.textPrimary,
                        ),
                            () async {
                          if (await isAccountBlocked(widget.userId) ||
                              await isBlockedByAccount(widget.userId)) {
                            if (!mounted) return;
                            ScaffoldMessenger.of(context).showSnackBar(
                              const SnackBar(content: Text('لا يمكن المراسلة بسبب الحظر')),
                            );
                            return;
                          }
                          if (!mounted) return;
                          await openDirectChat(
                            context,
                            peerId: widget.userId,
                            peerName: _displayName,
                            peerPhotoUrl: _photoUrl,
                          );
                        },
                      ),
                      const SizedBox(width: 8),
                      _followButton(t, isDark),
                    ] else
                      _outlineChip(t, 'Edit profile', () {
                        Navigator.of(context).maybePop();
                      }),
                  ],
                ),
              ),
            ],
          ),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (_loadingProfile) ...[
                _ShimmerLine(width: 140, height: 18, t: t),
                const SizedBox(height: 8),
                _ShimmerLine(width: 90, height: 13, t: t),
              ] else ...[
                Text(
                  _displayName,
                  style: TextStyle(
                    color: t.textPrimary,
                    fontSize: 20,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  '@$_username',
                  style: TextStyle(color: t.textFaint, fontSize: 15),
                ),
                if (_email.isNotEmpty &&
                    (_isSelf || _showEmailOnProfile)) ...[
                  const SizedBox(height: 4),
                  Text(
                    _email,
                    style: TextStyle(color: t.textFaint, fontSize: 13.5),
                  ),
                ],
              ],
              if (bio.isNotEmpty) ...[
                const SizedBox(height: 12),
                Text(
                  bio,
                  style: TextStyle(
                    color: t.textPrimary,
                    fontSize: 15,
                    height: 1.35,
                  ),
                ),
              ],
              const SizedBox(height: 12),
              _metaRow(t),
              const SizedBox(height: 12),
              _statsRow(t),
              const SizedBox(height: 8),

            ],
          ),
        ),
      ],
    );
  }

  Widget _metaRow(_ProfileTheme t) {
    // ===== المعلومات النصية العادية (إقامة/جامعة/عمل) =====
    final meta = <(IconData, String, VoidCallback?)>[];
    if (_isSelf || _showAcademicInfo) {
    if (_uni.isNotEmpty || _fac.isNotEmpty) {
      final line = [_uni, _fac, if (_studyLevel.isNotEmpty) _studyLevel]
          .where((e) =>
      e
          .trim()
          .isNotEmpty)
          .join(' · ');
      if (line.isNotEmpty) {
        meta.add((Icons.school_outlined, line, null));
      }
    }
    if (_work.isNotEmpty) {
      meta.add((Icons.work_outline_rounded, _work, null));
    }
  }

    final linkPills = <Widget>[
      if ((_isSelf || _showSocialLinks) &&_github.isNotEmpty)
        _SocialLinkPill(
          t: t,
          icon: Icons.code_rounded,
          label: 'GitHub',
          onTap: () => _openLink(_github),
        ),
      if ((_isSelf || _showSocialLinks) &&_linkedin.isNotEmpty)
        _SocialLinkPill(
          t: t,
          icon: Icons.work_outline_rounded,
          label: 'LinkedIn',
          onTap: () => _openLink(_linkedin),
        ),
      if ((_isSelf || _showSocialLinks) &&_portfolio.isNotEmpty)
        _SocialLinkPill(
          t: t,
          icon: Icons.language_rounded,
          label: 'Portfolio',
          onTap: () => _openLink(_portfolio),
        ),
    ];

    if (meta.isEmpty && linkPills.isEmpty) return const SizedBox.shrink();

    final metaWidgets = meta.map((m) {
      final (icon, text, onTap) = m;
      final child = Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 15, color: t.textFaint),
          const SizedBox(width: 4),
          Flexible(
            child: Text(
              text,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: onTap != null ? AppTeal.main : t.textFaint,
                fontSize: 13.5,
                fontWeight: onTap != null ? FontWeight.w600 : FontWeight.w500,
              ),
            ),
          ),
        ],
      );
      if (onTap == null) return child;
      return GestureDetector(onTap: onTap, child: child);
    }).toList();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (metaWidgets.isNotEmpty)
          Wrap(spacing: 14, runSpacing: 8, children: metaWidgets),
        if (linkPills.isNotEmpty) ...[
          if (metaWidgets.isNotEmpty) const SizedBox(height: 8),
          Wrap(spacing: 8, runSpacing: 8, children: linkPills),
        ],
      ],
    );
  }


  Widget _statsRow(_ProfileTheme t) {
    Widget chip({
      required String value,
      required String label,
      VoidCallback? onTap,
    }) {
      return Expanded(
        child: Material(
          color: t.isDark
              ? Colors.white.withValues(alpha: 0.08)
              : Colors.black.withValues(alpha: 0.055),
          borderRadius: BorderRadius.circular(8),
          child: InkWell(
            onTap: onTap,
            borderRadius: BorderRadius.circular(8),
            child: SizedBox(
              height: 34,
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 6),
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        value,
                        style: TextStyle(
                          color: t.textPrimary,
                          fontWeight: FontWeight.w800,
                          fontSize: 14,
                          height: 1,
                        ),
                      ),
                      const SizedBox(width: 5),
                      Text(
                        label,
                        style: TextStyle(
                          color: t.textFaint,
                          fontWeight: FontWeight.w600,
                          fontSize: 11.5,
                          height: 1,
                        ),
                      ),
                      if (onTap != null) ...[
                        const SizedBox(width: 1),
                        Icon(
                          Icons.keyboard_arrow_down_rounded,
                          size: 14,
                          color: t.textFaint,
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(0, 8, 0, 12),
      child: Row(
        children: [
          chip(value: _formatCount(_postsCount), label: 'منشورات'),
          const SizedBox(width: 6),
          chip(
            value: _formatCount(_followersCount),
            label: 'متابعون',
            onTap: () => _openFollowList(isFollowers: true),
          ),
          const SizedBox(width: 6),
          chip(
            value: _formatCount(_followingCount),
            label: 'يتابع',
            onTap: () => _openFollowList(isFollowers: false),
          ),
        ],
      ),
    );
  }

