  Widget _coverFallback() {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            AppTeal.main.withValues(alpha: 0.85),
            const Color(0xFF1565C0),
          ],
        ),
      ),
    );
  }

  void _showMoreSheet(_ProfileTheme t) {
    final link = 'unispace://user/${widget.userId}';

    Future<void> copyLink() async {
      await Clipboard.setData(ClipboardData(text: link));
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تم نسخ الرابط')),
      );
    }

    Future<void> shareProfile() async {
      await Share.share(
        '$_displayName  (@$_username)\n$link',
        subject: _displayName,
      );
    }

    showModalBottomSheet(
      context: context,

      isScrollControlled: true,
      builder: (ctx) {
        final sheetBg = t.isDark ? const Color(0xFF1C1C1E) : const Color(0xFFF2F2F7);
        final groupBg = t.isDark ? const Color(0xFF2C2C2E) : Colors.white;
        final danger = t.isDark ? const Color(0xFFFF453A) : const Color(0xFFD70015);
        final divider = t.isDark
            ? Colors.white.withValues(alpha: 0.10)
            : Colors.black.withValues(alpha: 0.08);
        final handleColor = t.isDark
            ? Colors.white.withValues(alpha: 0.28)
            : Colors.black.withValues(alpha: 0.18);

        Widget handle() => Center(
          child: Container(
            width: 36,
            height: 5,
            margin: const EdgeInsets.only(top: 10, bottom: 14),
            // decoration: BoxDecoration(
            //   color: handleColor,
            //   borderRadius: BorderRadius.circular(99),
            // ),
          ),
        );

        Widget row({
          required String label,
          required IconData icon,
          required VoidCallback onTap,
          bool destructive = false,
        }) {
          final color = destructive ? danger : t.textPrimary;
          return InkWell(
            onTap: onTap,
            child: SizedBox(
              height: 52,
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        label,
                        style: TextStyle(
                          color: color,
                          fontSize: 16.5,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                    ),
                    Icon(icon, size: 22, color: color),
                  ],
                ),
              ),
            ),
          );
        }

        Widget group(List<Widget> rows) {
          return ClipRRect(
            borderRadius: BorderRadius.circular(16),
            child: ColoredBox(
              color: groupBg,
              child: Column(
                children: [
                  for (var i = 0; i < rows.length; i++) ...[
                    if (i > 0)
                      Divider(
                        height: 0.5,
                        thickness: 0.5,
                        indent: 16,
                        endIndent: 16,
                        color: divider,
                      ),
                    rows[i],
                  ],
                ],
              ),
            ),
          );
        }

        return Directionality(
          textDirection: TextDirection.ltr,
          child: Material(
            color: sheetBg,
            borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
            child: SafeArea(
              top: false,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(12, 0, 12, 10),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    handle(),
                    group([
                      row(
                        label: 'Copy link',
                        icon: Icons.link_rounded,
                        onTap: () {
                          Navigator.pop(ctx);
                          copyLink();
                        },
                      ),
                      row(
                        label: 'Share to',
                        icon: Icons.ios_share_rounded,
                        onTap: () {
                          Navigator.pop(ctx);
                          shareProfile();
                        },
                      ),
                    ]),
                    const SizedBox(height: 8),
                    group([
                      row(
                        label: 'معلومات الحساب',
                        icon: Icons.info_outline_rounded,
                        onTap: () {
                          Navigator.pop(ctx);
                          _openInfoSheet(t);
                        },
                      ),
                      row(
                        label: 'السيرة',
                        icon: Icons.description_outlined,
                        onTap: () {
                          Navigator.pop(ctx);
                          _openCvSheet(t);
                        },
                      ),
                    ]),
                    const SizedBox(height: 8),
                    group([
                      row(
                        label: 'تبليغ',
                        icon: Icons.flag_outlined,
                        onTap: () {
                          Navigator.pop(ctx);
                          _reportAccount();
                        },
                      ),
                      row(
                        label: _iBlockThem ? 'إلغاء الحظر' : 'حظر الحساب',
                        icon: _iBlockThem
                            ? Icons.lock_open_rounded
                            : Icons.block_rounded,
                        destructive: true,
                        onTap: () {
                          Navigator.pop(ctx);
                          if (_iBlockThem) {
                            _unblock();
                          } else {
                            _confirmBlock();
                          }
                        },
                      ),
                    ]),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  void _openInfoSheet(_ProfileTheme t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) {
        return DraggableScrollableSheet(
          initialChildSize: 0.78,
          minChildSize: 0.4,
          maxChildSize: 0.95,
          expand: false,
          builder: (context, scrollController) {
            final hasPersonal = _residence.isNotEmpty ||
                _displayName.trim().isNotEmpty;
            final hasStudy = _uni.isNotEmpty ||
                _fac.isNotEmpty ||
                _major.isNotEmpty ||
                _studyLevel.isNotEmpty;
            final hasWork = _work.isNotEmpty;
            final hasLinks = _github.isNotEmpty ||
                _linkedin.isNotEmpty ||
                _portfolio.isNotEmpty;
            final hasOther = _otherInfo.isNotEmpty;
            final isEmpty = !hasPersonal &&
                !hasStudy &&
                !hasWork &&
                !hasLinks &&
                !hasOther;

            return Container(
              decoration: BoxDecoration(
                color: t.cardBg,
                borderRadius:
                const BorderRadius.vertical(top: Radius.circular(24)),
              ),
              child: Column(
                children: [
                  const SizedBox(height: 10),
                  Container(
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: t.cardBorder,
                      borderRadius: BorderRadius.circular(999),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            'Profile info',
                            style: TextStyle(
                              color: t.textPrimary,
                              fontSize: 17,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Divider(height: 1, color: t.cardBorder),
                  Expanded(
                    child: ListView(
                      controller: scrollController,
                      padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
                      children: [
                        if (isEmpty)
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 40),
                            child: Center(
                              child: Text(
                                'لا توجد معلومات',
                                style: TextStyle(
                                  color: t.textFaint,
                                  fontSize: 14,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ),
                          )
                        else ...[
                          // —— شخصية ——
