  void _openCvSheet(_ProfileTheme t) {
    final hasText = _otherInfo.isNotEmpty;
    final hasLinks =
        _github.isNotEmpty || _linkedin.isNotEmpty || _portfolio.isNotEmpty;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) {
        return DraggableScrollableSheet(
          initialChildSize: 0.45,
          minChildSize: 0.3,
          maxChildSize: 0.85,
          expand: false,
          builder: (context, scrollController) {
            return Container(
              decoration: BoxDecoration(
                color: t.cardBg,
                borderRadius:
                const BorderRadius.vertical(top: Radius.circular(20)),
              ),
              child: ListView(
                controller: scrollController,
                padding: const EdgeInsets.fromLTRB(20, 12, 20, 28),
                children: [
                  Center(
                    child: Container(
                      width: 36,
                      height: 4,
                      decoration: BoxDecoration(
                        color: t.cardBorder,
                        borderRadius: BorderRadius.circular(99),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'السيرة',
                    style: TextStyle(
                      color: t.textPrimary,
                      fontSize: 18,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                  const SizedBox(height: 12),
                  if (!hasText && !hasLinks)
                    Text('لا توجد سيرة بعد',
                        style: TextStyle(color: t.textFaint))
                  else ...[
                    if (hasText)
                      Text(
                        _otherInfo,
                        style: TextStyle(
                          color: t.textMuted,
                          fontSize: 15,
                          height: 1.45,
                        ),
                      ),
                    if (hasLinks) ...[
                      if (hasText) const SizedBox(height: 16),
                      if (_github.isNotEmpty)
                        ListTile(
                          contentPadding: EdgeInsets.zero,
                          leading: Icon(Icons.code, color: AppTeal.main),
                          title: const Text('GitHub'),
                          trailing: const Icon(Icons.open_in_new, size: 16),
                          onTap: () => _openLink(_github),
                        ),
                      if (_linkedin.isNotEmpty)
                        ListTile(
                          contentPadding: EdgeInsets.zero,
                          leading:
                          Icon(Icons.work_outline, color: AppTeal.main),
                          title: const Text('LinkedIn'),
                          trailing: const Icon(Icons.open_in_new, size: 16),
                          onTap: () => _openLink(_linkedin),
                        ),
                      if (_portfolio.isNotEmpty)
                        ListTile(
                          contentPadding: EdgeInsets.zero,
                          leading: Icon(Icons.language, color: AppTeal.main),
                          title: const Text('Portfolio'),
                          trailing: const Icon(Icons.open_in_new, size: 16),
                          onTap: () => _openLink(_portfolio),
                        ),
                    ],
                  ],
                ],
              ),
            );
          },
        );
      },
    );
  }
  Future<void> _openFollowList({required bool isFollowers}) async {
    if (!_isSelf) {
      final vis =
      isFollowers ? _followersVisibility : _followingVisibility;
      final ok = await canSeeAudienceList(
        ownerId: widget.userId,
        visibility: vis,
      );
      if (!ok) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              isFollowers
                  ? 'قائمة المتابعين خاصة'
                  : 'قائمة المتابَعين خاصة',
            ),
          ),
        );
        return;
      }
    }
    if (!mounted) return;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FollowListSheet(
        ownerId: widget.userId,
        isFollowers: isFollowers,
        isSelf: _isSelf,
      ),
    );
  }
