class _ProfileSearchHit {
  const _ProfileSearchHit.post(this.post)
      : comment = null,
        isComment = false;

  const _ProfileSearchHit.comment(this.post, this.comment)
      : isComment = true;

  final _Post post;
  final _Comment? comment;
  final bool isComment;
}

class _ProfileSearchSheetState extends State<_ProfileSearchSheet> {
  final _ctrl = TextEditingController();
  String _query = '';
  bool _loading = false;
  List<_ProfileSearchHit> _results = [];
  Timer? _debounce;

  @override
  void dispose() {
    _debounce?.cancel();
    _ctrl.dispose();
    super.dispose();
  }

  void _onQueryChanged(String q) {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 280), () {
      _runSearch(q);
    });
  }

  Future<void> _runSearch(String q) async {
    final text = q.trim().toLowerCase();
    if (!mounted) return;

    setState(() {
      _query = text;
      _loading = text.isNotEmpty;
      if (text.isEmpty) _results = [];
    });

    if (text.isEmpty || widget.authorId.isEmpty) {
      if (mounted) setState(() => _loading = false);
      return;
    }

    try {
      final snap = await FirebaseFirestore.instance
          .collection('community_posts')
          .where('authorId', isEqualTo: widget.authorId)
          .orderBy('createdAt', descending: true)
          .limit(100)
          .get();

      final hits = <_ProfileSearchHit>[];

      void walkComments(_Post post, List<_Comment> list) {
        for (final c in list) {
          // تعليقات صاحب الحساب فقط
          if (c.authorId == widget.authorId) {
            final body = c.text.toLowerCase();
            if (body.contains(text)) {
              hits.add(_ProfileSearchHit.comment(post, c));
            }
          }
          if (c.replies.isNotEmpty) {
            walkComments(post, c.replies);
          }
        }
      }

      for (final doc in snap.docs) {
        final post = _Post.fromFirestore(doc);

        final title = post.title.toLowerCase();
        final body = post.body.toLowerCase();
        final tags = post.tags.join(' ').toLowerCase();
        if (title.contains(text) || body.contains(text) || tags.contains(text)) {
          hits.add(_ProfileSearchHit.post(post));
        }

        walkComments(post, post.comments);
      }

      if (!mounted) return;
      setState(() {
        _results = hits;
        _loading = false;
      });
    } catch (e) {
      debugPrint('profile search failed: $e');
      if (!mounted) return;
      setState(() {
        _loading = false;
        _results = [];
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final t = widget.t;
    final bottomInset = MediaQuery.viewInsetsOf(context).bottom;
    final maxH = MediaQuery.sizeOf(context).height * 0.75;

    return AnimatedPadding(
      duration: const Duration(milliseconds: 120),
      curve: Curves.easeOut,
      padding: EdgeInsets.only(bottom: bottomInset),
      child: Align(
        alignment: Alignment.bottomCenter,
        child: Material(
          color: t.cardBg,
          borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
          clipBehavior: Clip.antiAlias,
          child: ConstrainedBox(
            constraints: BoxConstraints(maxHeight: maxH),
            child: SafeArea(
              top: false,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const SizedBox(height: 10),
                  Container(
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: t.cardBorder,
                      borderRadius: BorderRadius.circular(99),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(12, 12, 8, 8),
                    child: Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: _ctrl,
                            autofocus: true,
                            onChanged: _onQueryChanged,
                            textInputAction: TextInputAction.search,
                            style: TextStyle(color: t.textPrimary, fontSize: 15),
                            decoration: InputDecoration(
                              hintText:
                              'بحث في منشورات وتعليقات ${widget.authorName}...',
                              hintStyle:
                              TextStyle(color: t.textFaint, fontSize: 13),
                              prefixIcon: Icon(
                                Icons.search_rounded,
                                color: t.textFaint,
                                size: 22,
                              ),
                              filled: true,
                              fillColor: t.isDark
                                  ? Colors.white.withValues(alpha: 0.06)
                                  : Colors.black.withValues(alpha: 0.05),
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(14),
                                borderSide: BorderSide.none,
                              ),
                              contentPadding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 10,
                              ),
                              isDense: true,
                            ),
                          ),
                        ),
                        TextButton(
                          onPressed: () => Navigator.pop(context),
                          child: Text(
                            'إلغاء',
                            style: TextStyle(
                              color: AppTeal.main,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Divider(height: 1, color: t.cardBorder),

                  // المحتوى القابل للتمرير — يمنع Overflow
                  Flexible(
                    child: _loading
                        ? const Center(
                      child: Padding(
                        padding: EdgeInsets.all(24),
                        child: SizedBox(
                          width: 28,
                          height: 28,
                          child: CircularProgressIndicator(
                            strokeWidth: 2.5,
                          ),
                        ),
                      ),
                    )
                        : _query.isEmpty
                        ? Center(
                      child: Padding(
                        padding: const EdgeInsets.all(24),
                        child: Text(
                          'ابحث في المنشورات والتعليقات',
                          style: TextStyle(
                            color: t.textFaint,
                            fontSize: 13.5,
                          ),
                        ),
                      ),
                    )
                        : _results.isEmpty
                        ? Center(
                      child: Padding(
                        padding: const EdgeInsets.all(24),
                        child: Text(
                          'لا توجد نتائج',
                          style: TextStyle(
                            color: t.textFaint,
                            fontSize: 13.5,
                          ),
                        ),
                      ),
                    )
                        : ListView.separated(
                      padding: const EdgeInsets.fromLTRB(
                        12,
                        8,
                        12,
                        20,
                      ),
                      itemCount: _results.length,
                      separatorBuilder: (_, __) =>
                      const SizedBox(height: 8),
                      itemBuilder: (context, i) {
                        final hit = _results[i];
                        if (hit.isComment) {
                          return _searchCommentTile(hit, t);
                        }
                        return _PostCard(
                          post: hit.post,
                          showAuthorHeader: false,
                          compact: true,
                          onChanged: () {},
                          onDelete: () async {},
                          onHidden: () {},
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _searchCommentTile(_ProfileSearchHit hit, _ProfileTheme t) {
    final c = hit.comment!;
    final title = hit.post.title.trim();

    return Material(
      color: t.isDark
          ? Colors.white.withValues(alpha: 0.04)
          : Colors.black.withValues(alpha: 0.03),
      borderRadius: BorderRadius.circular(14),
      child: InkWell(
        borderRadius: BorderRadius.circular(14),
        onTap: () {
          Navigator.of(context).push(
            MaterialPageRoute(
              builder: (_) => CommentsScreen(post: hit.post),
            ),
          );
        },
        child: Padding(
          padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Icon(Icons.chat_bubble_outline, size: 14, color: t.textFaint),
                  const SizedBox(width: 6),
                  Text(
                    'تعليق',
                    style: TextStyle(
                      color: t.textFaint,
                      fontSize: 11.5,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  const Spacer(),
                  Text(
                    c.timeAgo,
                    style: TextStyle(color: t.textFaint, fontSize: 11),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Text(
                c.text.trim(),
                maxLines: 4,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  color: t.textPrimary,
                  fontSize: 14,
                  height: 1.35,
                ),
              ),
              if (title.isNotEmpty) ...[
                const SizedBox(height: 8),
                Text(
                  'على: $title',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(color: t.textFaint, fontSize: 12),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

