DocumentReference<Map<String, dynamic>> _followRequestRef(
    String toUid,
    String fromUid,
    ) {
  return FirebaseFirestore.instance
      .collection('users')
      .doc(toUid)
      .collection('follow_requests')
      .doc(fromUid);
}

Future<bool> isUserPrivate(String userId) async {
  if (userId.isEmpty) return false;
  try {
    final doc = await FirebaseFirestore.instance
        .collection('users')
        .doc(userId)
        .get();
    final raw = doc.data()?['privacy'];
    if (raw is Map) return raw['privateAccount'] == true;
  } catch (e) {
    debugPrint('isUserPrivate failed: $e');
  }
  return false;
}

Future<Set<String>> loadFollowingIds() async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return {};
  try {
    final snap = await FirebaseFirestore.instance
        .collection('users')
        .doc(me)
        .collection('following')
        .get();
    return snap.docs.map((d) => d.id).toSet();
  } catch (e) {
    debugPrint('loadFollowingIds failed: $e');
    return {};
  }
}

Future<void> syncAuthorPrivateOnPosts({
  required String uid,
  required bool isPrivate,
}) async {
  final snap = await FirebaseFirestore.instance
      .collection('community_posts')
      .where('authorId', isEqualTo: uid)
      .get();
  if (snap.docs.isEmpty) return;

  var batch = FirebaseFirestore.instance.batch();
  var n = 0;
  for (final d in snap.docs) {
    batch.update(d.reference, {'authorPrivate': isPrivate});
    n++;
    if (n == 400) {
      await batch.commit();
      batch = FirebaseFirestore.instance.batch();
      n = 0;
    }
  }
  if (n > 0) await batch.commit();
}
Future<bool> canInteractWithAuthor({
  required String authorId,
  required String audience, // everyone | followers | mutual | none
}) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return false;
  if (authorId.isEmpty || me == authorId) return true;

  switch (audience) {
    case 'none':
      return false;
    case 'everyone':
      return true;
    case 'followers':
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .doc(authorId)
          .collection('followers')
          .doc(me)
          .get();
      return snap.exists;
    case 'mutual':
      final a = await FirebaseFirestore.instance
          .collection('users')
          .doc(authorId)
          .collection('followers')
          .doc(me)
          .get();
      if (!a.exists) return false;
      final b = await FirebaseFirestore.instance
          .collection('users')
          .doc(me)
          .collection('followers')
          .doc(authorId)
          .get();
      return b.exists;
    default:
      return true;
  }
}

Future<bool> canSeeAudienceList({
  required String ownerId,
  required String visibility,
}) async {
  return canInteractWithAuthor(authorId: ownerId, audience: visibility);
}

Future<bool> canRepostAuthor(String authorId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return false;
  if (me == authorId) return true;
  try {
    final doc = await FirebaseFirestore.instance
        .collection('users')
        .doc(authorId)
        .get();
    final raw = doc.data()?['privacy'];
    final who = raw is Map
        ? (raw['whoCanRepost'] ?? 'everyone').toString()
        : 'everyone';
    return canInteractWithAuthor(authorId: authorId, audience: who);
  } catch (e) {
    debugPrint('canRepostAuthor failed: $e');
    return true;
  }
}

Future<bool> canCommentOnAuthor(String authorId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return false;
  if (me == authorId) return true;
  try {
    final doc = await FirebaseFirestore.instance
        .collection('users')
        .doc(authorId)
        .get();
    final raw = doc.data()?['privacy'];
    final who = raw is Map
        ? (raw['whoCanComment'] ?? 'everyone').toString()
        : 'everyone';
    return canInteractWithAuthor(authorId: authorId, audience: who);
  } catch (e) {
    debugPrint('canCommentOnAuthor failed: $e');
    return true;
  }
}
Future<void> setFollowing({
  required String me,
  required String targetId,
  required String targetName,
  String? targetPhotoUrl,
  required String myName,
  String? myPhotoUrl,
  required bool follow,
}) async {
  if (me.isEmpty || targetId.isEmpty || me == targetId) return;

  if (follow) {
    final blocked = await isAccountBlocked(targetId) ||
        await isBlockedByAccount(targetId);
    if (blocked) throw StateError('blocked');
  }

  final db = FirebaseFirestore.instance;
  final followingRef =
  db.collection('users').doc(me).collection('following').doc(targetId);
  final followerRef =
  db.collection('users').doc(targetId).collection('followers').doc(me);
  final requestRef = _followRequestRef(targetId, me);

  if (follow) {
    final already = await followingRef.get();
    if (already.exists) {
      await requestRef.delete();
      return;
    }

    final targetPrivate = await isUserPrivate(targetId);
    if (targetPrivate) {
      await requestRef.set({
        'uid': me,
        'name': myName,
        'photoUrl': myPhotoUrl,
        'status': 'pending',
        'createdAt': FieldValue.serverTimestamp(),
      });
      followRevision.value++;
      unawaited(pushNotification(
        toUid: targetId,
        type: 'follow_request',
        actorName: myName.isEmpty ? 'طالب UniSpace' : myName,
        actorPhotoUrl: myPhotoUrl,
        message: 'طلب متابعتك',
      ));
      return;
    }

    final batch = db.batch();
    batch.set(followingRef, {
      'uid': targetId,
      'name': targetName,
      'photoUrl': targetPhotoUrl,
      'createdAt': FieldValue.serverTimestamp(),
    });
    batch.set(followerRef, {
      'uid': me,
      'name': myName,
      'photoUrl': myPhotoUrl,
      'createdAt': FieldValue.serverTimestamp(),
    });
    batch.delete(requestRef);
    await batch.commit();
    followRevision.value++;
    unawaited(pushNotification(
      toUid: targetId,
      type: 'follow',
      actorName: myName.isEmpty ? 'طالب UniSpace' : myName,
      actorPhotoUrl: myPhotoUrl,
      message: 'بدأ بمتابعتك',
    ));
    return;
  }

  final batch = db.batch();
  batch.delete(followingRef);
  batch.delete(followerRef);
  batch.delete(requestRef);
  await batch.commit();
  followRevision.value++;
}

Future<void> cancelFollowRequest(String targetId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || targetId.isEmpty) return;
  await _followRequestRef(targetId, me).delete();
  followRevision.value++;
}

Future<void> acceptFollowRequest({
  required String fromId,
  required String fromName,
  String? fromPhotoUrl,
}) async {
  final me = FirebaseAuth.instance.currentUser;
  final myUid = me?.uid;
  if (myUid == null || fromId.isEmpty || fromId == myUid) return;

  String myName = (me?.displayName ?? '').trim();
  String? myPhoto = me?.photoURL;
  try {
    final myDoc = await FirebaseFirestore.instance
        .collection('users')
        .doc(myUid)
        .get();
    final d = myDoc.data();
    final fn = (d?['firstName'] ?? '').toString().trim();
    final ln = (d?['lastName'] ?? '').toString().trim();
    final fromNames = [fn, ln].where((e) => e.isNotEmpty).join(' ');
    if (fromNames.isNotEmpty) myName = fromNames;
    final p = d?['profileImageUrl']?.toString();
    if (p != null && p.isNotEmpty) myPhoto = p;
  } catch (_) {}
  if (myName.isEmpty) myName = 'طالب UniSpace';

  final db = FirebaseFirestore.instance;
  final batch = db.batch();
  batch.set(
    db.collection('users').doc(fromId).collection('following').doc(myUid),
    {
      'uid': myUid,
      'name': myName,
      'photoUrl': myPhoto,
      'createdAt': FieldValue.serverTimestamp(),
    },
  );
  batch.set(
    db.collection('users').doc(myUid).collection('followers').doc(fromId),
    {
      'uid': fromId,
      'name': fromName,
      'photoUrl': fromPhotoUrl,
      'createdAt': FieldValue.serverTimestamp(),
    },
  );
  batch.delete(_followRequestRef(myUid, fromId));
  await batch.commit();
  followRevision.value++;

  unawaited(pushNotification(
    toUid: fromId,
    type: 'follow_accepted',
    actorName: myName,
    actorPhotoUrl: myPhoto,
    message: 'قبل طلب المتابعة',
  ));
}

Future<void> rejectFollowRequest(String fromId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || fromId.isEmpty) return;
  await _followRequestRef(me, fromId).delete();
  followRevision.value++;
}


DocumentReference<Map<String, dynamic>> _blockedAccountRef(
    String ownerId,
    String targetId,
    ) {
  return FirebaseFirestore.instance
      .collection('users')
      .doc(ownerId)
      .collection('blocked_accounts')
      .doc(targetId);
}

DocumentReference<Map<String, dynamic>> _blockedByRef(
    String victimId,
    String blockerId,
    ) {
  return FirebaseFirestore.instance
      .collection('users')
      .doc(victimId)
      .collection('blocked_by')
      .doc(blockerId);
}

Future<bool> isAccountBlocked(String targetId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || targetId.isEmpty || me == targetId) return false;
  try {
    final doc = await _blockedAccountRef(me, targetId).get();
    return doc.exists;
  } catch (e) {
    debugPrint('isAccountBlocked failed: $e');
    return false;
  }
}
Future<bool> isBlockedByAccount(String otherId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || otherId.isEmpty || me == otherId) return false;

  try {
    final reverse = await FirebaseFirestore.instance
        .collection('users')
        .doc(me)
        .collection('blocked_by')
        .doc(otherId)
        .get();
    if (reverse.exists) return true;
  } catch (e) {
    debugPrint('blocked_by read failed: $e');
  }

  try {
    final theirs = await FirebaseFirestore.instance
        .collection('users')
        .doc(otherId)
        .collection('blocked_accounts')
        .doc(me)
        .get();
    if (theirs.exists) return true;
  } catch (e) {
    debugPrint('their blocked_accounts read failed: $e');
  }

  return false;
}
Future<Set<String>> loadHiddenAuthorIds() async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null) return {};
  final ids = <String>{};
  try {
    final blocked = await FirebaseFirestore.instance
        .collection('users')
        .doc(me)
        .collection('blocked_accounts')
        .get();
    for (final d in blocked.docs) {
      ids.add(d.id);
    }
  } catch (e) {
    debugPrint('load blocked_accounts failed: $e');
  }
  try {
    final blockedBy = await FirebaseFirestore.instance
        .collection('users')
        .doc(me)
        .collection('blocked_by')
        .get();
    for (final d in blockedBy.docs) {
      ids.add(d.id);
    }
  } catch (e) {
    debugPrint('load blocked_by failed: $e');
  }
  return ids;
}

Future<void> blockAccount({
  required String targetId,
  required String targetName,
  String? targetPhotoUrl,
}) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || targetId.isEmpty || me == targetId) return;

  final db = FirebaseFirestore.instance;
  final batch = db.batch();

  batch.set(_blockedAccountRef(me, targetId), {
    'targetId': targetId,
    'targetName': targetName,
    'targetPhotoUrl': targetPhotoUrl,
    'blockedAt': FieldValue.serverTimestamp(),
  });
  batch.set(_blockedByRef(targetId, me), {
    'blockerId': me,
    'blockedAt': FieldValue.serverTimestamp(),
  });

  // قطع المتابعة في الاتجاهين (الحاجب يملك الحذف بفضل القواعد)
  batch.delete(db.collection('users').doc(me).collection('following').doc(targetId));
  batch.delete(db.collection('users').doc(targetId).collection('followers').doc(me));
  batch.delete(db.collection('users').doc(targetId).collection('following').doc(me));
  batch.delete(db.collection('users').doc(me).collection('followers').doc(targetId));

  await batch.commit();
  blockedListRevision.value++;
  followRevision.value++;
}

Future<void> unblockAccount(String targetId) async {
  final me = FirebaseAuth.instance.currentUser?.uid;
  if (me == null || targetId.isEmpty) return;

  final batch = FirebaseFirestore.instance.batch();
  batch.delete(_blockedAccountRef(me, targetId));
  batch.delete(_blockedByRef(targetId, me));
  await batch.commit();
  blockedListRevision.value++;
}




class FollowRequestsScreen extends StatelessWidget {
  const FollowRequestsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    final me = FirebaseAuth.instance.currentUser?.uid;

    return Scaffold(
      backgroundColor: t.pageBg,
      appBar: AppBar(
        title: const Text('طلبات المتابعة'),
        backgroundColor: t.pageBg,
        surfaceTintColor: Colors.transparent,
      ),
      body: me == null
          ? Center(
        child: Text('سجّل الدخول أولاً', style: TextStyle(color: t.textFaint)),
      )
          : StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('users')
            .doc(me)
            .collection('follow_requests')
            .snapshots(),
        builder: (context, snap) {
          if (!snap.hasData) {
            return const Center(child: CircularProgressIndicator());
          }
          return FutureBuilder<Set<String>>(
            future: loadBlockedUserIds(),
            builder: (context, blockedSnap) {
              final blocked = blockedSnap.data ?? {};
              final visible = snap.data!.docs.where((d) {
                final id = (d.data()['uid'] ?? d.id).toString();
                return !blocked.contains(id);
              }).toList();

              if (visible.isEmpty) {
                return Center(
                  child: Text(
                    'لا توجد طلبات',
                    style: TextStyle(color: t.textFaint),
                  ),
                );
              }

              return ListView.separated(
                padding: const EdgeInsets.fromLTRB(12, 8, 12, 24),
                itemCount: visible.length,
                separatorBuilder: (_, __) => const SizedBox(height: 4),
                itemBuilder: (context, i) {
                  final d = visible[i].data();
                  final id = (d['uid'] ?? visible[i].id).toString();
                  final name = (d['name'] ?? 'طالب UniSpace').toString();
                  final photo = d['photoUrl']?.toString();
                  return _FollowRequestTile(
                    userId: id,
                    name: name,
                    photoUrl: photo,
                    t: t,
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}

